<template>
  <div class="Approach theme--grey">
    <div class="Section-bounding js-bounding">
      <div class="page__container">
        <div class="page__hero" ref="cover">
          <div class="page__hero__wrap">
            <div class="page__hero__copy">
              <h1 v-html="page.acf[0].intro"></h1>
            </div>
          </div>
        </div>
      </div>
      <div class="bi u-vacuum theme--black u-relative">
        <Titleline
          label="Our approach"
          :first="true"
          :animate="true"
          :pullup="true"
          :overlap="true"
          :short="true"
        ></Titleline>
        <div class="u-vacuum--restore">
          <div class="bi__copy" ref="biTrigger">
            <div class="page__container"></div>
          </div>
        </div>
      </div>
    </div>
    <div class="Approach-slides js-slides">
      <video
        width="3350"
        height="2000"
        playsinline
        autoplay
        loop
        muted
        class="bubble"
        style="position: absolute; right: -200px; top: -100px"
        ref="bubble-video"
      >
        <source src="../assets/Bubble-compressed.mp4" type="video/mp4" />
      </video>
      <div class="bi__copy--1" ref="copy1">
        <h2 v-html="page.acf[0].copy_1"></h2>
      </div>
      <div class="bi__copy--2" ref="copy2">
        <h2 v-html="page.acf[0].copy_2"></h2>
      </div>
      <div class="bi__copy--3" ref="copy3">
        <h2 v-html="page.acf[0].copy_3"></h2>
      </div>
      <div class="bi__copy--4" ref="copy4">
        <h2 v-html="page.acf[0].copy_4"></h2>
      </div>
    </div>
    <Footer></Footer>
  </div>
</template>

<script>
import size from "size";
import sniffer from "sniffer";
import Scroll from "@/components/scroll";
import Titleline from "@/components/modules/Titleline";
import Footer from "@/components/Footer";

export default {
  name: "Approach",
  extends: Scroll,
  components: {
    Titleline,
    Footer,
  },
  data() {
    return {
      page: [],
    };
  },
  created: function () {
    this.page = this.$root.$data.content.pages.approach;
    this.tl = null;
  },
  mounted() {
    this.$eventBus.$emit("updateScroll");
    this.$eventBus.$emit("changeTheme", "light");
    this.init();
    this.addController();
    this.animateIn();

    if (sniffer.isDevice) {
      this.$refs.cover.style.height = `${window.innerHeight}px`;
    }
  },
  beforeDestroy: function () {
    this.destroy();
    TweenMax.killTweensOf(this.tl);
    this.tl = null;
  },
  destroyed: function () {
    this.$eventBus.$emit("changeTheme", "dark");
  },
  methods: {
    getUIExtend: function () {
      this.slides = this.$el.querySelector(".js-slides");
      this.circles = this.$el.querySelectorAll(".js-circle");
      this.stagger = this.$el.querySelectorAll(".js-stagger");
      this.section = this.$el.querySelector(".bi__copy");
      this.bubble = this.$el.querySelector(".bubble");
    },
    addController: function () {
      const { copy1, copy2, copy3, copy4 } = this.$refs;
      const tl = (this.tl = new TimelineMax({ paused: true }));
      tl.to(this.slides, 1, { autoAlpha: 1 }, 0);

      //set

      //bubble
      //const bezPoints = [{x:'+=150', y: '+=50'}, {x:'-=350', y: '-=100'}, {x: '+=300', y: '+=50'}]
      //tl.to(this.bubble, 10, {bezier:bezPoints})

      //timeline
      tl.to(copy1, 3, { autoAlpha: 1 });
      tl.to(copy1, 3, { autoAlpha: 0 }, "+=3");

      tl.to(copy2, 3, { autoAlpha: 1 });
      tl.to(copy2, 3, { autoAlpha: 0 }, "+=3");

      tl.to(copy3, 3, { autoAlpha: 1 });
      tl.to(copy3, 3, { autoAlpha: 0 }, "+=3");

      tl.to(copy4, 3, { autoAlpha: 1 });
      tl.to(copy4, 3, { autoAlpha: 0 }, "+=3");

      tl.to(this.slides, 2, { autoAlpha: 0 }, "+=1");
    },
    rAFExtend: function () {
      const current = this.data.current;
      const progress =
        (this.data.current - size.height) / (this.data.max - size.height * 3);
      const clamp = Math.min(Math.max(progress, 0), 1);
      this.tl.progress(clamp);
      if (
        current >= size.height - 65 &&
        current <= this.data.max - size.height - 65
      ) {
        this.header.classList.remove("theme--light");
      } else {
        this.header.classList.add("theme--light");
      }
      if (
        !window.App.menu &&
        this.mouse.y >= size.height - current &&
        this.mouse.y + current <= this.data.max - size.height
      ) {
        this.$eventBus.$emit("cursor:color", "white");
      } else {
        this.$eventBus.$emit("cursor:color", "black");
      }
    },
    animateIn: function () {
      const tl = new TimelineMax({ paused: true });
      tl.add(() => this.$eventBus.$emit("ready"), 0.5);
      tl.restart();
    },
    resize: function () {
      const { height } = size;
      const length = 7;
      const h = height * length;
      this.section.style.height = `${h}px`;
    },
  },
};
</script>

<!-- Add "scoped" attribute to limit CSS to this component only -->
<style scoped lang="scss">
.Approach {
  //padding-bottom: 0;

  .Section-bounding {
    background-color: #e6e6e6;
  }

  .page__hero__copy {
    @include breakpoint(not-phab) {
      max-width: 85%;
    }
  }

  .theme--black,
  .Approach-slides {
    cursor: url("../assets/circle-white.svg") 15 10, auto;
  }

  .bi__copy--2 {
    img {
      max-width: 870px;
      width: 100%;
    }
  }

  &-slides {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    text-align: center;
    z-index: 5;
    opacity: 0;
    visibility: hidden;
    > div {
      position: absolute;
      top: 50%;
      left: 50%;
      transform: translateX(-50%) translateY(-50%);
      width: 100%;
      max-width: 1100px;
      padding: 0 40px;
      color: white;
      opacity: 0;
      visibility: hidden;

      @include breakpoint(tab) {
        /deep/ br {
          display: inline;
          content: "";
          &:after {
            content: "\a0";
            display: inline-block;
          }
        }
      }
    }

    video {
      .is-device & {
        width: 90%;
        height: 400px;
        left: 30px;
        top: 50% !important;
        margin-top: -400px;
        right: auto;
      }
    }
  }

  .line-wrap {
    position: relative;
  }
  .line {
    position: absolute;
    height: 5px;
    width: 96%;
    bottom: 3px;
    left: 3px;
    background: white;

    @include breakpoint(desk) {
      height: 4px;
    }
    @include breakpoint(tab) {
      height: 3px;
      bottom: 0;
    }
  }
  .equal {
    position: relative;
    line-height: 0;

    > div {
      margin: 0 auto;
      display: block;
      width: 30px;
      height: 5px;
      background: white;
    }
    &-1 {
      margin-bottom: 10px !important;
      //top: 42%;
    }
    &-2 {
      //top: 58%;
    }
  }

  .bi__copy {
    &--3 {
      max-width: 1200px;
    }
    &--4 {
      max-width: 1200px;
    }
    &--5 {
      max-width: 1200px;
    }
  }

  // .bi {
  // 	position: relative;

  // 	&__copy {
  // 		//padding-top: 350px;
  // 		height: 100vh;
  // 		text-align: center;
  // 		margin: 0 auto;

  // 		@include breakpoint(phab) {
  // 			//padding-top: 290px;
  // 		}

  // 		&--1 {

  // 		}
  // 		&--2 {

  // 		}
  // 		&--3 {
  // 			.bi__circles {
  // 				max-width: 1000px;
  // 				@include breakpoint(phab) {
  // 					width: 90%;
  // 					//top: -100px;
  // 				}
  // 			}
  // 		}
  // 		&--4 {

  // 		}
  // 		&--5 {

  // 		}
  // 	}
  // }
}
</style>



