<template>
	<!-- mode="in-out" -->
	<transition appear
    v-on:appear="enter"
    v-on:leave="leave"
    v-bind:css="false"
  >
	<div class="Careers theme--grey">
		<div class="Careers-transform js-transform">
			<div class="Careers-transform js-transform">
				<div class="Section-bounding js-bounding">
					<div class="page__container">
						<div class="page__hero" ref="cover">
							<div class="page__hero__wrap">
								<div class="page__hero__copy">
									<h1 v-html='page.acf[0].intro'></h1>
								</div>
							</div>
						</div>
					</div>
					<div class="messages u-vacuum theme--black">
						<Titleline label="Work at Loaf" :first="true" :animate="true" :pullup="true" :overlap="true" :short="true"></Titleline>
						<div class="u-vacuum--restore">
							<div class="messages__copy js-copy"></div>
						</div>
					</div>
					<div id="vacancies" class="vacancies u-vacumn theme--black" ref="vacancies">
						<!-- <Titleline label="Vacancies" :pullup="true" :short="true"></Titleline> -->
						<div class="u-vacuum--restore">
							<div class="page__container u-pad-b--lg theme--black">
								<h1>Opportunities</h1>
								<div class="u-flex--not-tab u-pad-t--sm">
									<div class="vacancies__jobs">
										<h6>Current vacancies</h6>
										<div v-for="item in vacancies">
											<a :href="'/careers/' + item.post_name" @click="openMoreinfo($event, '/careers/' + item.post_name)">
												<h1 class="hover hover--link u-inline-block">{{item.post_title}}</h1>
											</a>
										</div>
									</div>
									<div class="vacancies__placements">
									<h6>Placements &amp; collaborations</h6>
									<h6 class="tall" v-html="page.acf[0].placements"></h6>
								</div>
								</div>
							</div>
						</div>
					</div>
				</div>
				<div class="Careers-slides js-slides">
					<div class="messages__copy--1 theme--black" ref="copy1">
						<h1>{{page.acf[0].copy_1}}</h1>
					</div>
					<div class="messages__copy--2 theme--black" ref="copy2">
						<h1>{{page.acf[0].copy_2}}</h1>
					</div>
					<div class="messages__copy--3 theme--black" ref="copy3">
						<h1>{{page.acf[0].copy_3}}</h1>
					</div>
					<div class="messages__copy--4 theme--black" ref="copy4">
						<h1>{{page.acf[0].copy_4}}</h1>
					</div>
				</div>
				<Footer></Footer>
			</div>
		</div>
	</div>
	</transition>
</template>

<script>
	import size from 'size'
	import sniffer from 'sniffer'
	import Scroll from '@/components/scroll'
	import Footer from '@/components/Footer'
	import Titleline from '@/components/modules/Titleline'
	import { isModifiedClick } from '@/utils'

	export default {
		name: 'Careers',
		extends: Scroll,
		components: {
			Titleline,
			Footer
		},
		data() {
			return {
				page: [],
				vacancies: []
			}
		},
		created: function(){
			this.page = this.$root.$data.content.pages.careers
			this.vacancies = this.$root.$data.content.vacancy
			this.tl = null
			this.h = null
		},
		mounted() {
			this.$eventBus.$emit('updateScroll')
			this.$eventBus.$emit('changeTheme', 'light')
			this.init()
			this.addController()
			this.animateIn()
			this.$eventBus.$emit('ready')
			this.$eventBus.$on('resize', this.scrollTo)

			if(sniffer.isDevice) {
				this.$refs.cover.style.height = `${window.innerHeight}px`
			}
		},
		beforeDestroy: function() {
			TweenMax.killTweensOf(this.tl)
			this.tl = null
			this.destroy()
		},
		destroyed(){
			this.$eventBus.$emit('changeTheme', 'dark')
		},
		methods: {
			getUIExtend: function() {
				this.transform = this.$el.querySelectorAll('.js-transform')
				this.slides = this.$el.querySelector('.js-slides')
				this.section = this.$el.querySelector('.js-copy')
				this.area = {
					el: this.$el.querySelector('.theme--black'),
					bounding: null
				}
			},
			addController: function() {
				const { copy1, copy2, copy3, copy4 } = this.$refs
		 		const tl = this.tl = new TimelineMax({ paused: true })
		 		tl.set(this.slides, { autoAlpha: 1 })
		 		tl.to(copy1, 0.5, { autoAlpha: 1 })
		 		tl.to(copy1, 0.5, { autoAlpha: 0 })
		 		tl.to(copy2, 0.5, { autoAlpha: 1 })
		 		tl.to(copy2, 0.5, { autoAlpha: 0 })
		 		tl.to(copy3, 0.5, { autoAlpha: 1 })
		 		tl.to(copy3, 0.5, { autoAlpha: 0 })
		 		tl.to(copy4, 0.5, { autoAlpha: 1 })
		 		tl.to(copy4, 0.5, { autoAlpha: 0 })
		 		tl.set(this.slides, { autoAlpha: 0 })
			},
		  enter: function (el, done) {
		  	TweenMax.set(this.$el, { position: 'fixed', top: 0, left: 0, width: '100%' })
				done()
		  },
			animateIn: function() {
				const tl = new TimelineMax({ paused: true })
				tl.set(this.$el, { position: 'relative' })
				tl.restart()
			},
		  leave: function (el, done) {
		  	const tl = new TimelineMax({ paused: true, onComplete: done })
		  	tl.set(this.$el, { position: 'fixed', top: 0, left: 0, right: 0, width: '100%' })
		  	tl.staggerTo(this.transform, 1, {
					cycle: {
						x: [size.width, -size.width]
					},
					ease: Quint.easeInOut
				}, 0, 0)
				tl.restart()
		  },
			rAFExtend: function() {
				const { top, bottom } = this.area.bounding
				const current = this.data.current
				const progress = (this.data.current - size.height) / (this.data.max - (size.height * 4))
				const clamp = Math.min(Math.max(progress, 0), 1)
				this.tl.progress(clamp)
				if (current >= top - 65 && current <= bottom) {
					this.header.classList.remove('theme--light')
				} else {
					this.header.classList.add('theme--light')
				}
				if (!window.App.menu && this.mouse.y >= top - current && this.mouse.y + current <= bottom) {
					this.$eventBus.$emit('cursor:color', 'white')
				} else {
					this.$eventBus.$emit('cursor:color', 'black')
				}
			},
			resize: function() {
				const { height } = size
				const length = 7
				const h = this.h = height * length
				this.section.style.height = `${h}px`
				this.area.bounding = this.area.el.getBoundingClientRect()
				this.$eventBus.$emit('resize')
			},
			scrollTo: function() {
				this.$eventBus.$off('resize', this.scrollTo)
				const hash = location.hash.substr(1)
				if (hash == 'vacancies' && window.routeStorage.lastYPos) {
					this.data.target = this.data.current = window.routeStorage.lastYPos
					window.routeStorage.lastYPos = null
				}
			},
			openMoreinfo: function(event, path) {
				// Let cmd/ctrl/shift-click open the real href in a new tab or window
				if (isModifiedClick(event)) return
				event.preventDefault()
				window.routeStorage.lastYPos = window.scrollY
				this.$router.push({ path: path, params: { prevView: 'careers' } })
			}
		}
	}
</script>

<!-- Add "scoped" attribute to limit CSS to this component only -->
<style scoped lang="scss">
	.Careers {
		padding-bottom: 0;
		// cursor: url('../assets/circle.svg') 15 10, auto;

		.Careers-transform {
			width: 100%;
			height: 100%;
			overflow: hidden;
		}

		.Section-bounding {
			background-color: #E6E6E6;
		}

		.page__hero__copy {
			@include breakpoint(not-phab) {
				max-width: 85%;
			}
		}

		&-slides {
			position: fixed;
			top: 0; left: 0;
			width: 100%;
			height: 100%;
			z-index: 5;
			visibility: hidden;
			div {
				position: absolute;
				top: 50%;
				left: 50%;
				transform: translateX(-50%) translateY(-50%);
				width: 100%;
				padding: 0 40px;
				color: white;
				opacity: 0;
				visibility: hidden;
			}

			$site-mw: 1800;

			h1 {
				font-size: 250/($site-mw+120)*100vw;
				text-align: center;
			}
		}

		.messages {
			position: relative;

			&__copy {
				//padding-top: 350px;
				height: 100vh;
				//text-align: center;
				margin: 0 auto;

				$site-mw: 1800;

				h1 {
					font-size: 250/($site-mw+120)*100vw;
					//@include fontSize(250px);
					margin-left: 100px;

					@include breakpoint(lap) {
						margin-left: 40px;
					}
					@include breakpoint(phab) {
						margin-left: 0;
						text-align: center;
					}
				}
				@include breakpoint(phab) {
					//padding-top: 290px;
				}
			}
		}

		.vacancies {

			.u-flex--not-phab {

			}

			h6 {
				margin-bottom: 80px;
				@include breakpoint(tab) {
					margin-bottom: 40px;
				}
			}
			&__jobs {
				@include breakpoint(not-tab) {
					width: 50%;
				}
				h4 {
					line-height: 1.05;
					margin-bottom: 30px;
				}
				h1 {
					line-height: 1.1;
					margin-bottom: 10px;
					@include breakpoint(desk) {
						font-size: scaled-rem(60);
					}
				}
			}
			&__placements {
				max-width: 400px;

				h6 {
					margin-bottom: 90px;
					@include breakpoint(tab) {
						margin-bottom: 50px;
					}
				}

				@include breakpoint(tab) {
					margin-top: 100px;
				}

				@include breakpoint(not-tab) {
					padding-left: 100px;
				}
			}
		}

	}

</style>



