<script>
import size from "size";
import sniffer from "sniffer";
import fit from "math-fit";
import SplitText from "../../plugins/gsap/src/minified/utils/SplitText.min.js";
import { decodeImage, imageAlt, workLabel } from "../../utils.js";
import Scroll from "@/components/scroll";

const assign = Object.assign;
const body = document.body;

export default {
  name: "Projects",
  extends: Scroll,
  data() {
    return {
      items: [],
    };
  },
  created() {
    this.images = [];
    this.image = null;
    this.scale = 1;
    this.options.threshold = 0;
  },
  mounted() {
    //console.log('Projects:mounted')
    this.loadImages();
    this.addSplit();
    this.addHover();
    this.init();
    this.animateIn();
  },
  beforeDestroy() {
    //console.log('Projects:beforeDestroy')
    this.cleanup();
    this.destroy();
  },
  methods: {
    addHover: function () {
      const items = this.$el.querySelectorAll(".item-ratio");
      items.forEach((item) => {
        item.querySelector(".image-src").addEventListener("mouseover", () => {
          item.classList.add("hover");
        });
        item.querySelector(".image-src").addEventListener("mouseout", () => {
          item.classList.remove("hover");
        });
        //
        item.querySelector(".meta").addEventListener("mouseover", () => {
          item.classList.add("hover");
        });
        item.querySelector(".meta").addEventListener("mouseout", () => {
          item.classList.remove("hover");
        });
      });
    },
    backgroundImage: function (landscape, portrait, raw) {
      if (window.innerWidth > 800 || !portrait) {
        return landscape;
      } else {
        return portrait;
      }
    },
    addSplit: function () {
      if (sniffer.isDevice) return;
      const titles = this.$el.querySelectorAll(".meta__title");
      this.splits = [];
      titles.forEach((title) => {
        this.splits.push(new SplitText(title, { type: "words, lines" }));
        title.classList.add("split");
      });
    },
    getUIExtend: function () {},
    loadImages: function () {
      const onload = () => {};
      const images = {};
      const els = this.$el.querySelectorAll(".js-image");
      els.forEach((dom) => {
        const el = dom.querySelector(".js-src");
        const post = dom.getAttribute("data-post");
        const bounds = el.getBoundingClientRect();
        const src = dom.getAttribute("data-src");
        const img = this.loadImage(el, src);
        // Created in JS, so the alt is set here: the media library's alt
        // text, else "Client — Title"
        const content = this.$root.$data.content;
        const work = content && content.work ? content.work[post] : null;
        img.alt = work ? imageAlt(work.acf[0].feature_image, workLabel(work)) : "";
        images[post] = img;
        const meta = dom.querySelector(".meta");
        if (!sniffer.isDevice) {
          TweenMax.set(meta, {
            x:
              dom.offsetLeft <= bounds.width * 0.25
                ? bounds.width - 60
                : -meta.offsetWidth + 60,
          });
        }
      });
      this.images = images;
    },
    resetImage: function (el, img) {
      TweenMax.killTweensOf(img);
      TweenMax.set(img, {
        scale: 1,
        x: 0,
        y: 0,
      });

      const { width, height } = size;
      const bounds = el.getBoundingClientRect();
      const { contain, cover } = this.getFitScreen(img, width, height);
      const scaler = 1;

      assign(img.style, {
        position: "absolute",
        width: `${cover.width * scaler}px`,
        height: `${cover.height * scaler}px`,
      });

      const scale = (cover.width * scaler) / img.naturalWidth;
      const focusPointX = el.getAttribute("data-focus-x") * scale;
      const focusPointY = el.getAttribute("data-focus-y") * scale;

      TweenMax.set(img, {
        x: -(focusPointX - bounds.width / 2),
        y: -(focusPointY - bounds.height / 2),
      });

      TweenMax.set(el, { autoAlpha: 0 });
    },
    loadImage: function (el, src) {
      const img = decodeImage(src, () => {
        this.resetImage(el, img);

        el.insertBefore(img, el.firstChild);
        TweenMax.fromTo(
          el,
          0.4,
          {
            autoAlpha: 0,
          },
          {
            autoAlpha: 1,
            ease: Linear.easeNone,
          }
        );
      });
      return img;
    },
    inView: function (el, data, direction) {
      if (data.state || el.classList.contains("in-viewport")) return;
      data.state = true;
      el.classList.add("in-viewport");
      const img = el.querySelector("img");
      TweenMax.set(el.querySelector(".image-src"), { autoAlpha: 1 });
      if (sniffer.isDesktop) {
        const offset = data.left <= size.width * 0.25 ? -300 : 300;
        const delay = Math.random() * 0.25;
        const unit = 300;
        TweenMax.fromTo(
          el,
          2.75,
          {
            autoAlpha: 0,
            x: offset,
            y: direction === "top" ? -unit : unit,
          },
          {
            autoAlpha: 1,
            x: 0,
            y: 0,
            delay: delay,
            ease: Quint.easeOut,
          }
        );
        if (img) {
          const { top, left, width, height, post, href } =
            this.getProjectAttributes(el);
          const { contain, cover } = this.getFitScreen(
            this.images[post],
            width,
            height
          );
          const scale = img.width / img.naturalWidth;
          const focusPointX =
            el.querySelector(".image-src").getAttribute("data-focus-x") * scale;
          const focusPointY =
            el.querySelector(".image-src").getAttribute("data-focus-y") * scale;
          TweenMax.to(img, 10, {
            scale: cover.width / img.width,
            x: -(focusPointX - width / 2),
            y: -(focusPointY - height / 2),
          });
        }
        const stagger = el.querySelectorAll(".js-stagger");
        TweenMax.staggerFromTo(
          stagger,
          1.4,
          {
            x: data.left <= size.width * 0.25 ? -100 : 100,
            autoAlpha: 0,
          },
          {
            x: 0,
            autoAlpha: 1,
            delay: 0.75,
            ease: Quint.easeOut,
          },
          0.13
        );
      }
    },
    outView: function (el, data, direction) {
      if (!data.state) return;
      data.state = false;
      el.classList.remove("in-viewport");
      const img = el.querySelector("img");
      if (img) {
        this.resetImage(el.querySelector(".image-src"), img);
      }
    },
    getProjectAttributes: function (currentTarget) {
      const { top, left, width, height } =
        currentTarget.getBoundingClientRect();
      const post = currentTarget.getAttribute("data-post");
      const href = currentTarget.getAttribute("href");
      return { post, href, top, left, width, height };
    },
    getFitScreen: function (image, width, height) {
      const origin = { w: image.naturalWidth, h: image.naturalHeight };
      const contain = fit(origin, { width, height });
      const cover = fit(origin, { width: size.width, height: size.height });
      return { origin, contain, cover };
    },
    openProject: function (e) {
      e.preventDefault();
      const { currentTarget } = e;

      const video = currentTarget.querySelector("video");
      if (video) {
        TweenMax.to(video, 0.2, { autoAlpha: 0 });
      }

      const img = currentTarget.querySelector("img");
      let scale = (this.scale = img._gsTransform ? img._gsTransform.scaleY : 1);
      TweenMax.killTweensOf(img);

      const tl = new TimelineMax({ paused: true });
      const stagger = currentTarget.querySelectorAll(".js-stagger");
      const { top, left, width, height, post, href } =
        this.getProjectAttributes(currentTarget);
      if (sniffer.isDevice) {
        //this.$router.push({ path: href, params: { prevView: 'home' } })
        //return
      }

      const { contain, cover } = this.getFitScreen(
        this.images[post],
        width,
        height
      );
      const image = this.images[post];
      body.style.overflow = "hidden";

      this.image = image;
      this.canvas = document.createElement("canvas");
      this.ctx = this.canvas.getContext("2d");
      this.tween = null;
      window.App.el.appendChild(this.canvas);
      this.resizeCanvas();

      this.rect = {
        top: top,
        left: left,
        width: width,
        height: height,
      };
      this.tween = {
        sw: image.naturalWidth,
        sh: image.naturalHeight,
        top: img.getBoundingClientRect().top,
        left: img.getBoundingClientRect().left,
        //top: top + contain.top - (contain.height * Math.abs(1 - scale) / 2),
        //left: left + contain.left - (contain.width * Math.abs(1 - scale) / 2),
        width: img.getBoundingClientRect().width,
        height: img.getBoundingClientRect().height,
      };

      tl.staggerTo(
        stagger,
        0.3,
        {
          autoAlpha: 0,
          ease: Linear.easeNone,
          onComplete: () =>
            TweenMax.ticker.addEventListener("tick", this.onUpdate),
        },
        0.1,
        0
      );
      tl.to(
        this.rect,
        1.25,
        {
          left: 0,
          top: 0,
          width: size.width,
          height: size.height,
          ease: Quint.easeInOut,
        },
        0.4
      );
      tl.to(
        this.tween,
        1.25,
        {
          left: cover.left,
          top: cover.top,
          width: cover.width,
          height: cover.height,
          ease: Quint.easeInOut,
          onComplete: () => {
            document.body.style.overflow = "";
            App.el.removeChild(this.canvas);
            this.$router.push({ path: href, params: { prevView: "home" } });
          },
        },
        0.4
      );
      window.routeStorage = {
        route: "home",
        coverImage: this.image,
      };
      tl.restart();
    },
    resize: function () {
      const { width, height } = size;
      this.resizeCanvas();
    },
    resizeCanvas: function () {
      if (!this.canvas) return;
      const { width, height } = size;
      const dpr = window.dpr;
      this.ctx.scale(dpr, dpr);
      this.canvas.width = width * dpr;
      this.canvas.height = height * dpr;
      Object.assign(this.canvas.style, {
        position: "fixed",
        top: 0,
        left: 0,
        width: `${width}px`,
        height: `${height}px`,
        zIndex: 6,
      });
    },
    onUpdate: function () {
      const { width, height } = size;
      const { ctx } = this;
      const dpr = window.dpr;
      ctx.clearRect(0, 0, width * dpr, height * dpr);
      ctx.save();
      ctx.beginPath();
      ctx.moveTo(this.rect.left * dpr, this.rect.top * dpr);
      ctx.lineTo(
        this.rect.left * dpr + this.rect.width * dpr,
        this.rect.top * dpr
      );
      ctx.lineTo(
        this.rect.left * dpr + this.rect.width * dpr,
        this.rect.top * dpr + this.rect.height * dpr
      );
      ctx.lineTo(
        this.rect.left * dpr,
        this.rect.top * dpr + this.rect.height * dpr
      );
      ctx.lineTo(this.rect.left * dpr, this.rect.top * dpr);
      ctx.closePath();
      ctx.clip();
      ctx.fillStyle = `rgba(255,0,106,.5)`;
      ctx.fillRect(
        this.tween.left * dpr,
        this.tween.top * dpr,
        this.tween.width * dpr,
        this.tween.height * dpr
      );
      // ctx.translate((this.tween.width * dpr) / 2, (this.tween.height * dpr) / 2)
      // ctx.scale(this.scale, this.scale)
      // ctx.translate(-(this.tween.width * dpr) / 2, -(this.tween.height * dpr) / 2)
      ctx.drawImage(
        this.image,
        0,
        0,
        this.tween.sw,
        this.tween.sh,
        this.tween.left * dpr,
        this.tween.top * dpr,
        this.tween.width * dpr,
        this.tween.height * dpr
      );
      ctx.restore();
    },
    cleanup: function () {
      const { TweenMax } = this.$GSAP;
      TweenMax.ticker.removeEventListener("tick", this.onUpdate);
      this.canvas = null;
      this.ctx = null;
      this.images = null;
      this.image = null;
      this.rect = null;
      this.tween = null;
    },
  },
};
</script>

<style lang="scss">
.Home {
  position: relative;

  .Home-transform {
    width: 100%;
    height: 100%;
    overflow: hidden;
  }

  .Section-bounding {
    .is-desktop & {
      //padding-bottom: 200px;
    }
    background: $black;
  }

  .item-ratio {
    position: relative;
    display: block;
    padding-top: 117px;

    @media (min-width: 600px) and (max-width: 1024px) {
      //between phab and tab
      width: 47%;
      display: inline-block;
      &:nth-child(odd) {
        margin-right: 5%;
      }
    }

    .image {
      cursor: url("../../assets/plus-white.svg") 15 10, auto;
      opacity: 0;
      &.in-viewport {
        opacity: 1;
      }
      @media (max-width: 1024px) {
        width: 100% !important;
      }

      img {
        will-change: transform;
      }

      .meta__title.split {
        > div[style*="block"] {
          display: table !important;
        }
        > div > div {
          margin-right: 12px;
          @include breakpoint(phab) {
            margin-right: 6px;
          }
        }
      }
      .meta__title {
        &:hover > div {
          &:after,
          &:before {
            transform: scaleX(0) !important;
          }
        }
      }
      .is-desktop & {
        &:hover {
          .meta__title div:after,
          .meta__title div:before {
            transform: scaleX(1) !important;
            transform-origin: left center;
          }
        }
      }

      &-ratio {
        overflow: hidden;
      }

      &-src {
        &--video {
          img {
            //display: none;
            //transform: none !important;
          }
        }
        video {
          position: absolute;
          z-index: 1;
          top: 0;
          left: 0;
          width: 100%;
          height: 101%;
          object-fit: cover;
          object-position: top;
        }
      }
    }

    .meta {
      position: absolute;
      z-index: 2;
      top: 50%;
      transform: translateY(-50%);
      z-index: 2;
      color: white;

      .is-stagger {
        opacity: 0;
        visibility: hidden;
      }

      &__title {
        margin-bottom: 2.5rem;
        //max-width: 650px;
        display: block;

        @include fontSize(70px);

        @media (max-width: 1024px) {
          font-size: 27px;
          br {
            display: none;
          }
        }
      }
      p {
        @media (min-width: 1025px) {
          position: absolute;
          top: -30px;
          white-space: nowrap;
        }
      }

      @media (max-width: 1024px) {
        left: 20px !important;
        right: auto !important;
        text-align: left !important;
        top: calc(100% + 13px) !important;
        transform: none !important;
        margin: 0;

        &__title {
          margin-bottom: 0;
        }
        p {
          margin-bottom: 10px;
        }
      }
    }

    // image orientations
    &:nth-child(odd) .image {
      margin-left: auto;
    }
    &:nth-child(even) .meta {
      @include breakpoint(not-phab) {
        left: -20px;
      }
    }

    &:nth-child(even) {
      .image {
        margin-right: auto;
      }
      .meta {
        //text-align: right;
        @include breakpoint(1440px) {
          //right: -270px;
          //max-width: 500px;
        }
      }
    }

    // image sizes
    &:nth-child(1),
    &:nth-child(4),
    &:nth-child(6),
    &:nth-child(10),
    &:nth-child(12),
    &:nth-child(16) {
      .image {
        @extend .image--3x2;
        width: 59%;
      }
    }

    &:nth-child(2),
    &:nth-child(5),
    &:nth-child(7),
    &:nth-child(11),
    &:nth-child(14) {
      .image {
        @extend .image--2x3;
        width: 41%;
      }
    }

    &:nth-child(3),
    &:nth-child(8),
    &:nth-child(13),
    &:nth-child(15) {
      .image {
        @extend .image--1x1;
        width: 42%;
        margin-top: -9.7rem;
      }
    }

    &:nth-child(8) {
      .image {
        margin-left: 5rem;
      }
    }

    // individual blocks
    &:nth-child(1) {
      .image {
        margin-right: 9rem;
      }
    }

    &:nth-child(4),
    &:nth-child(6),
    &:nth-child(12) {
      .image {
        margin-left: -40px;
        width: 59%;
      }
    }

    &:nth-child(5) {
      .image {
        margin-right: 20rem;
      }
    }

    &:nth-child(9) {
      .image {
        @extend .image--3x2;
        width: 60%;
        margin-top: 3rem;
      }
    }

    &:nth-child(10) {
      .image {
        margin-left: 100px;
      }
      .meta {
        text-align: left;
      }
    }

    @media (max-width: 1024px) {
      margin-top: 0;
      padding-top: 0;
      margin-bottom: 140px;

      .image {
        margin: 0 !important;
        &:before {
          padding-top: 100% !important;
        }
      }
    }
  }
  .image-src {
    transition: filter 0.5s ease;
  }

  .item-ratio.hover .image-src {
    filter: brightness(0.7);
  }
}
</style>



