<template>
  <transition appear v-on:appear="enter" v-on:leave="leave" v-bind:css="false">
    <div class="About page theme--white">
      <div
        class="introCopy__wrapper tw-w-full tw-h-screen tw-bg-white tw-relative tw-z-[2]"
      >
        <div class="page__container js-section tw-relative">
          <div class="introCopy page__hero" ref="cover">
            <div class="page__hero__wrap">
              <div
                class="page__hero__copy tw-pr-[20px] lg:tw-pr-0 tw-absolute max-container intro1"
                ref="intro1"
              >
                <p class="intro_title1 tw-font-[500] js-copy">
                  {{ page.acf[0].intro_1.title }}
                </p>
                <h1
                  v-html="page.acf[0].intro_1.description"
                  class="intro_description1 tw-font-[500] tw-leading-[1.1] lg:tw-leading-[1.05] js-copy"
                ></h1>
              </div>
              <div
                class="page__hero__copy tw-pr-[20px] lg:tw-pr-0 tw-absolute max-container intro2"
                ref="intro2"
              >
                <p class="intro_title2 tw-font-[500]">
                  {{ page.acf[0].intro_2.title }}
                </p>
                <!-- h2: one H1 per page (intro_1 is the H1). Sized and spaced
                     like the H1 by the .page__hero__copy rules below. -->
                <h2
                  v-html="page.acf[0].intro_2.description"
                  class="intro_description2 tw-font-[500] tw-leading-[1.1] lg:tw-leading-[1.05]"
                ></h2>
              </div>
            </div>
          </div>
        </div>
        <div
          class="workArrow tw-absolute tw-bottom-10 lg:tw-bottom-40 tw-right-[20px] cursor-plus"
        >
          <CircleArrow title="Our Work" url="/work" :dark="true" />
        </div>
      </div>

      <div class="Section-bounding js-bounding tw-relative tw-z-[12]">
        <div class="u-vacuum u-relative js-section">
          <div class="aboutContent">
            <div class="aboutContent__inner tw-bg-white">
              <div class="clients theme--black lg:tw-pt-[360px] tw-py-32">
                <div class="page__container">
                  <SectorNav
                    class="about__sectors"
                    theme="dark"
                    label="Sectors"
                    large
                  />
                  <div class="sectionTitle">
                    {{ page.acf[0].clients.title }}
                  </div>
                  <div class="clients-container tw-mt-20">
                    <!-- Moved by rAFExtend (tickMarquee), not a CSS animation:
                         see tickMarquee for why -->
                    <div class="clients-scroll" ref="clientsTrack">
                      <img
                        v-for="client in page.acf[0].clients.logos"
                        :key="client.id"
                        :src="client.url.replace('-scaled', '')"
                        :width="client.width"
                        :height="client.height"
                        @load="measureMarquee"
                        :alt="
                          imageAlt(client, page.acf[0].clients.title, 'Client logos')
                        "
                        class="client-logo"
                      />
                      <img
                        v-for="client in page.acf[0].clients.logos"
                        :key="`duplicate-${client.id}`"
                        :src="client.url.replace('-scaled', '')"
                        :width="client.width"
                        :height="client.height"
                        class="client-logo"
                        alt=""
                        aria-hidden="true"
                      />
                    </div>
                    <div class="gradient-overlay gradient-left"></div>
                    <div class="gradient-overlay gradient-right"></div>
                  </div>
                </div>
              </div>

              <div class="theme--black tw-py-20 lg:tw-py-44">
                <div class="page__container">
                  <div class="results">
                    <div
                      class="tw-flex tw-justify-between tw-items-center lg:tw-mb-16"
                    >
                      <div class="sectionTitle">
                        {{ page.acf[0].results.title }}
                      </div>
                      <img
                        src="../assets/circle-arrow.svg"
                        class="tw-w-[100px] lg:tw-w-[120px] tw-h-auto carouselArrow cursor-plus-white"
                        alt="Next result"
                        ref="arrow1"
                        @click="nextResultsSlide"
                      />
                    </div>

                    <carousel
                      :per-page="isMobile ? 1 : 3"
                      :center-mode="true"
                      class="tw-text-white tw-text-[18px] lg:tw-text-[21px] tw-mt-3 lg:tw-mt-0"
                      id="resultsCarousel"
                      ref="resultsCarousel"
                    >
                      <slide
                        v-for="(result, index) in page.acf[0].results.items"
                        :key="index"
                        class="lg:tw-pr-20"
                      >
                        <div class="tw-mb-5 tw-font-[500]">
                          {{ result.title }}
                        </div>
                        <div>{{ result.description }}</div>
                      </slide>
                    </carousel>

                    <div class="awards tw-mt-40 lg:tw-mt-[400px] tw-mb-6">
                      <div class="sectionTitle tw-mb-7">
                        {{ page.acf[0].awards.title }}
                      </div>
                      <div class="lg:tw-columns-2 tw-max-w-[900px]">
                        <div
                          v-for="result in page.acf[0].awards.items"
                          :key="result.id"
                          class="tw-text-white tw-text-[18px] lg:tw-text-[21px] tw-mb-10 last:tw-mb-0"
                        >
                          <div class="tw-font-[500]">{{ result.title }}</div>
                          <p class="tw-whitespace-pre-line">
                            {{ result.award }}
                          </p>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              </div>

              <div class="quotes tw-bg-white tw-py-36 tw-text-black">
                <div class="page__container">
                  <div
                    class="tw-flex tw-justify-between tw-items-center lg:tw-mb-10"
                  >
                    <div class="sectionTitle">
                      {{ page.acf[0].quotes.title }}
                    </div>
                    <img
                      src="../assets/circle-arrow-dark.svg"
                      class="tw-w-[120px] tw-h-auto carouselArrow cursor-plus"
                      alt="Next quote"
                      ref="arrow2"
                      @click="nextQuotesSlide"
                    />
                  </div>

                  <carousel
                    :per-page="1"
                    :center-mode="true"
                    class="tw-text-[21px]"
                    ref="quotesCarousel"
                    id="quotesCarousel"
                    @page-change="onQuotesPageChange"
                  >
                    <slide
                      v-for="(result, index) in page.acf[0].quotes.items"
                      :key="index"
                      class=""
                    >
                      <div class="tw-max-w-[920px]">
                        <div
                          class="tw-text-[24px] lg:tw-text-[40px] tw-font-[500] tw-leading-[1]"
                        >
                          "&nbsp;{{ result.quote }}&nbsp;"
                        </div>
                        <div
                          class="tw-text-[19px] lg:tw-max-w-[280px] lg:tw-max-w-none lg:tw-text-[22px] tw-font-[500] tw-mt-14"
                        >
                          <div>{{ result.author }}</div>
                          <div>{{ result.company }}</div>
                        </div>
                      </div>
                    </slide>
                  </carousel>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
      <Footer></Footer>
    </div>
  </transition>
</template>

<script>
import size from "size";
import sniffer from "sniffer";
import Scroll from "@/components/scroll";
import Footer from "@/components/Footer";
import CircleArrow from "@/components/modules/CircleArrow";
import beautifulIdea from "@/assets/beautiful-idea.vue";
import { Carousel, Slide } from "vue-carousel";
import { imageAlt } from "@/utils";
import SectorNav from "@/components/modules/SectorNav";
//import Titleline from "@/components/modules/Titleline";
//import GSAPScrollMagic from '../plugins/gsap-scrollmagic'

export default {
  name: "About",
  extends: Scroll,
  components: {
    SectorNav,
    Footer,
    CircleArrow,
    beautifulIdea,
    Carousel,
    Slide,
  },
  data() {
    return {
      page: [],
      isMobile: false,
      intro1: null,
      intro2: null,
      introTitle1: null,
      introDescription1: null,
      introTitle2: null,
      introDescription2: null,
      aboutContent: null,
      introCopy: null,
      tl2: null,
      workArrow: null,
      initialAboutContentTop: null,
    };
  },
  created: function () {
    this.resizing = false;
    this.page = this.$root.$data.content.pages.about;
  },
  mounted() {
    console.log("About:mounted");
    this.$eventBus.$emit("changeTheme", "light");
    this.$eventBus.$emit("updateScroll");
    this.init();
    this.$eventBus.$emit("setHeaderScrollThreshold", 1300); // Set custom scroll threshold for header visibility
    this.animateIn();
    this.addController();
    this.checkMobile();

    if (sniffer.isDevice) {
      this.$refs.cover.style.height = `${window.innerHeight}px`;
    }

    window.addEventListener("resize", this.checkMobile);
    this.setupMarquee();

    // Set initial carousel height
    this.$nextTick(() => {
      setTimeout(() => {
        this.updateCarouselHeight();
      }, 100);
    });
  },
  beforeDestroy: function () {
    console.log("About:beforeDestroy");
    window.removeEventListener("resize", this.checkMobile);
    if (this.marqueeObserver) this.marqueeObserver.disconnect();
    this.destroy();
  },
  destroyed: function () {
    this.$eventBus.$emit("setHeaderScrollThreshold", 100); // Reset to default threshold
  },
  methods: {
    imageAlt,
    enter: function (el, done) {
      console.log("About:enter", el);
      done();
    },
    leave: function (el, done) {
      console.log("About:leave", el);
      done();
    },
    getUIExtend: function () {
      this.header = document.querySelector(".Header");
      this.images = this.$el.querySelectorAll(".js-image");
      this.area = {
        el: this.$el.querySelector(".theme--black"),
        bounding: null,
      };
      this.intro1 = this.$el.querySelector(".intro1");
      this.introTitle1 = this.$el.querySelector(".intro_title1");
      this.introDescription1 = this.$el.querySelector(".intro_description1");
      this.intro2 = this.$el.querySelector(".intro2");
      this.introTitle2 = this.$el.querySelector(".intro_title2");
      this.introDescription2 = this.$el.querySelector(".intro_description2");
      this.aboutContent = this.$el.querySelector(".aboutContent");
      this.aboutContentInner = this.$el.querySelector(".aboutContent__inner");
      this.introCopy = this.$el.querySelector(".introCopy__wrapper");
      this.workArrow = this.$el.querySelector(".workArrow");
    },
    resize() {
      this.measureMarquee();
    },

    // Client logos: a strip shown twice, moving left one copy's width per
    // loop. It's moved here, every frame of the page's own scroll loop,
    // rather than by a CSS animation: Safari runs CSS animations on the GPU
    // but paints this very wide strip in tiles on the page side, which then
    // doesn't know where the strip has got to, so parts of it sometimes
    // weren't painted in time (blank stretches, logos flicking in and out).
    setupMarquee() {
      this.marqueeX = 0;
      this.marqueeLast = 0;
      this.marqueeHalf = 0;
      this.marqueeVisible = true;
      const container = this.$el.querySelector(".clients-container");
      if (window.IntersectionObserver && container) {
        this.marqueeObserver = new IntersectionObserver(
          (entries) => {
            this.marqueeVisible = entries[0].isIntersecting;
          },
          { rootMargin: "200px 0px" }
        );
        this.marqueeObserver.observe(container);
      }
      this.measureMarquee();
    },
    measureMarquee() {
      const track = this.$refs.clientsTrack;
      if (track) this.marqueeHalf = track.scrollWidth / 2;
    },
    tickMarquee() {
      const now = performance.now();
      // Cap the step so a background tab doesn't jump on return
      const dt = this.marqueeLast ? Math.min(now - this.marqueeLast, 100) : 0;
      this.marqueeLast = now;
      const track = this.$refs.clientsTrack;
      if (!track || !this.marqueeHalf || !this.marqueeVisible) return;
      const duration = window.innerWidth <= 600 ? 22000 : 20000;
      this.marqueeX =
        (this.marqueeX + (dt * this.marqueeHalf) / duration) % this.marqueeHalf;
      track.style.transform = `translate3d(${-this.marqueeX.toFixed(2)}px,0,0)`;
    },

    checkMobile() {
      this.isMobile = window.innerWidth < 1024; // lg breakpoint
    },
    addController() {
      this.introTitle2.style.opacity = 0;
      this.introDescription2.style.opacity = 0;

      // Scroll-driven crossfade from intro 1 to intro 2. Explicit from
      // values, so it doesn't depend on where the intro fade-in had got to
      // when it first rendered; immediateRender off so it doesn't show
      // intro 1 before its fade-in.
      const hidden = { autoAlpha: 0 };
      const shown = { autoAlpha: 1 };
      const at = (vars) => Object.assign({ immediateRender: false }, vars);
      this.tl2 = new TimelineMax({ paused: true });
      this.tl2.fromTo(this.introTitle1, 1, at(shown), hidden);
      this.tl2.fromTo(this.introDescription1, 1, at(shown), hidden, "-=0.8");
      this.tl2.fromTo(this.introTitle2, 1, at(hidden), shown, "-=0.3");
      this.tl2.fromTo(this.introDescription2, 0.8, at(hidden), shown, "-=0.9");
      this.tl2Started = false;

      // Capture initial position of aboutContentInner on page load
      this.$nextTick(() => {
        if (this.aboutContentInner) {
          this.initialAboutContentTop =
            this.aboutContentInner.getBoundingClientRect().top;
        }
      });
    },
    animateIn() {
      // Intro 1 fades in. Scrolling unlocks ("ready") at 1s, before this
      // finishes; rAFExtend completes it as soon as the scroll crossfade
      // takes over, so the two never fight over the same text.
      const tl = (this.introTl = new TimelineMax({}));
      this.workArrow.style.opacity = 0;
      tl.set(this.introTitle1, { autoAlpha: 0, y: 10 });
      tl.set(this.introDescription1, { autoAlpha: 0, y: 10 });

      tl.to(this.introTitle1, 1, { autoAlpha: 1, y: 0 });
      tl.to(this.introDescription1, 1, { autoAlpha: 1, y: 0 }, "-=0.8");
      tl.add(() => this.$eventBus.$emit("ready"), 1);

      tl.restart();

      // Separate from the intro timeline, so finishing that early doesn't
      // pop the arrow in
      TweenMax.to(this.workArrow, 1, { autoAlpha: 1, delay: 0.8 });
    },
    rAFExtend: function () {
      const current = this.data.current;
      this.tickMarquee();

      if (this.aboutContent) {
        // Use aboutContentInner instead since introCopy__wrapper is now fixed
        const rect = this.aboutContentInner.getBoundingClientRect();
        const viewportHeight = window.innerHeight;

        // Progress: 0 on page load, 1 when aboutContent top reaches 25% into viewport
        const targetPosition = viewportHeight * 1.05; // 25% from top = 75% from bottom

        if (this.initialAboutContentTop !== null) {
          // Calculate total distance to scroll (from initial position to target)
          const totalScrollDistance =
            this.initialAboutContentTop - targetPosition;

          // Calculate how much we've scrolled (current position vs initial)
          const scrolled = this.initialAboutContentTop - rect.top;

          // Calculate progress (0 to 1)
          let progress = scrolled / totalScrollDistance;
          progress = Math.max(0, Math.min(1, progress)); // Clamp between 0 and 1

          // Once scrolling starts the crossfade owns the intro text: finish
          // the fade-in first, then drive the crossfade from here on
          if (progress > 0 && !this.tl2Started) {
            this.tl2Started = true;
            if (this.introTl) this.introTl.progress(1);
          }
          if (this.tl2Started) this.tl2.progress(progress);
        }

        if (this.aboutContentInner.getBoundingClientRect().top <= 0) {
          this.introCopy.style.opacity = 0;
          this.introCopy.style.pointerEvents = "none";
        } else {
          this.introCopy.style.opacity = 1;
          this.introCopy.style.pointerEvents = "auto";
        }
      }
    },

    nextResultsSlide: function () {
      if (this.$refs.resultsCarousel) {
        const carousel = this.$refs.resultsCarousel;
        const nextPage = carousel.currentPage + 1;
        const totalPages = Math.ceil(carousel.slideCount / carousel.perPage);

        if (nextPage >= totalPages) {
          carousel.goToPage(0); // Go back to first page
        } else {
          carousel.goToPage(nextPage);
        }
      }
    },
    nextQuotesSlide: function () {
      if (this.$refs.quotesCarousel) {
        const carousel = this.$refs.quotesCarousel;
        const nextPage = carousel.currentPage + 1;
        const totalPages = Math.ceil(carousel.slideCount / carousel.perPage);

        if (nextPage >= totalPages) {
          carousel.goToPage(0); // Go back to first page
        } else {
          carousel.goToPage(nextPage);
        }
      }
    },
    onQuotesPageChange: function (pageNumber) {
      this.updateCarouselHeight(pageNumber);
    },
    updateCarouselHeight: function (pageIndex) {
      this.$nextTick(() => {
        const carousel = this.$refs.quotesCarousel;
        if (!carousel || !carousel.$el) return;

        const carouselEl = carousel.$el;
        const inner = carouselEl.querySelector(".VueCarousel-inner");
        if (!inner) return;

        const slides = inner.querySelectorAll(".VueCarousel-slide");
        if (slides.length === 0) return;

        const currentIndex =
          pageIndex !== undefined ? pageIndex : carousel.currentPage;
        const activeSlide = slides[currentIndex];

        if (activeSlide) {
          const contentWrapper = activeSlide.querySelector("div");
          if (contentWrapper) {
            carouselEl.style.height = contentWrapper.offsetHeight + "px";
          } else {
            carouselEl.style.height = activeSlide.offsetHeight + "px";
          }
        }
      });
    },
  },
};
</script>

<!-- Add "scoped" attribute to limit CSS to this component only -->
<style lang="scss">
#quotesCarousel {
  transition: height 0.5s ease-in-out !important;
}

.VueCarousel-pagination {
  bottom: -50px !important;
  top: auto !important;
}
#resultsCarousel .VueCarousel-dot {
  background-color: #444 !important;
  border-color: #444 !important;
  &--active {
    background-color: #fff !important;
    border-color: #fff !important;
  }
}
#quotesCarousel .VueCarousel-dot {
  background-color: #b5b5b5 !important;
  border-color: #b5b5b5 !important;
  &--active {
    background-color: #000 !important;
    border-color: #000 !important;
  }
}
</style>
<style scoped lang="scss">
// Sector links above the client logos, spaced like a section of their own
.about__sectors {
  margin-bottom: 200px;

  @include breakpoint(tab) {
    margin-bottom: 96px;
  }
}

.About {
  padding-bottom: 0;

  &__wrap {
    max-width: 1800px;
  }
}

.introCopy__wrapper {
  position: fixed;
  z-index: 2;
}

// The intro has to sit above the fold, so the offset, gaps and type scale
// with viewport height (clamped to the old fixed sizes at the top end).
.About .introCopy {
  // Keep clear of the header on mid-size screens; large screens use 26vh.
  .page__hero__wrap {
    padding-top: clamp(120px, 17vh, 220px);
    @include breakpoint(not-phab) {
      padding-top: clamp(120px, 20vh, 220px);
    }
    @include breakpoint(1024px, "min-width") {
      padding-top: unquote("min(380px, max(200px, min(25vh, 230px), 26vh))");
    }
  }

  .page__hero__copy > p {
    font-size: clamp(18px, 2.6vh, 22px);
    @include breakpoint(1024px, "min-width") {
      font-size: clamp(22px, 2.9vh, 32px);
    }
  }

  // Tied to width as well as height: a narrower column wraps into more lines.
  // intro_2 is an h2 (one H1 per page) but must look identical to the h1,
  // so it shares these rules and the h1's letter-spacing (the global h2
  // rule would otherwise tighten it to -0.027em)
  .page__hero__copy h1,
  .page__hero__copy h2 {
    letter-spacing: -0.015em;
    margin-top: clamp(16px, 3vh, 56px);
    font-size: unquote("clamp(20px, min(4.6vw, 3.6vh), 40px)");
    @include breakpoint(phab) {
      font-size: unquote("clamp(20px, min(7.4vw, 3.6vh), 34px)");
    }
    @include breakpoint(1024px, "min-width") {
      margin-top: clamp(20px, 4.5vh, 80px);
      font-size: unquote("clamp(26px, min(3.8vw, 5vh), 46px)");
      line-height: 1;
    }
    @include breakpoint(1280px, "min-width") {
      font-size: unquote("clamp(28px, min(3.2vw, 5.3vh), 66px)");
    }

    // v-html content, so reach past the scoped attribute
    /deep/ p {
      margin: 0;
    }
    /deep/ p + p {
      margin-top: 1em;
    }
    // Same weight for both blocks, whatever the editor bolded
    /deep/ strong {
      font-weight: inherit;
    }
  }

  // Width as a share of the container's content width. The copy is absolutely
  // positioned, so % resolves against the container's padding box -- take the
  // side padding (50px, or 80px above 1550px) off first. Wider below 1280px so
  // it doesn't wrap into too many lines; narrow enough to clear the Our Work
  // arrow. Needs .About .introCopy to beat .page:not(.Home) .page__hero__copy.
  .page__hero__copy {
    @include breakpoint(not-phab) {
      max-width: calc((100% - 100px) * 0.6);
    }
    @include breakpoint(1280px, "min-width") {
      max-width: calc((100% - 100px) * 0.55);
    }
    @include breakpoint(1551px, "min-width") {
      max-width: calc((100% - 160px) * 0.55);
    }
    @include breakpoint(phab) {
      max-width: none;
    }
  }
}

.Section-bounding {
  pointer-events: none;
}
.aboutContent {
  padding-top: 1950px;
}
.aboutContent__inner {
  pointer-events: auto;
}

.sectionTitle {
  padding-bottom: 50px;
  @include breakpoint(phab) {
    padding-bottom: 50px;
  }
}

.awardsImages {
  img {
    height: 150px;
    width: auto;
    @include breakpoint(phab) {
      width: 100%;
      height: auto;
    }
  }
}

.carouselArrow {
  margin-top: -55px;
  transition: transform 0.3s ease-in-out;

  @include breakpoint(not-phab) {
    &:hover {
      transform: translateX(10px);
    }
  }

  @include breakpoint(phab) {
    transform: translateX(30px);
    height: 100px;
  }
}

.clients-container {
  position: relative;
  overflow: hidden;
  width: 100%;
}

// Moved by tickMarquee (About.vue script)
.clients-scroll {
  display: flex;
  width: fit-content;
  will-change: transform;
}

// Not its own layer (no will-change): the strip is one very wide image,
// too wide for Safari to hold reliably as a separate GPU layer
.client-logo {
  height: 80px;
  width: auto;
  max-width: none;
  flex-shrink: 0;
  display: block;

  @include breakpoint(phab) {
    height: 65px;
  }
}

.gradient-overlay {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 150px;
  pointer-events: none;
  z-index: 2;

  @include breakpoint(phab) {
    width: 80px;
  }
}

.gradient-left {
  left: 0;
  background: linear-gradient(
    to right,
    rgba(0, 0, 0, 1) 0%,
    rgba(0, 0, 0, 0) 100%
  );
}

.gradient-right {
  right: 0;
  background: linear-gradient(
    to left,
    rgba(0, 0, 0, 1) 0%,
    rgba(0, 0, 0, 0) 100%
  );
}

</style>



