<template>
	<transition appear
		v-on:appear="enter"
    	v-on:leave="leave"
   		v-bind:css="false"
	>
	<div class="Vacancy flyout">
		<div class="flyout-transform js-transform">
			<div class="flyout-transform js-transform theme--white">
				<div class="Section-bounding js-bounding">
					<div class="page__container">
						<div class="page__inner">

							<div class="flyout__hero u-relative js-copy">
								<div class="flyout__close">
									<a href="/" @click="routerBack" aria-label="Back" class="close js-stagger"><img src="../assets/arrow-left.svg" alt=""></a>
								</div>

								<h3 class="js-stagger" v-html='page.post_title'></h3>
<!-- 								<p class="js-stagger">{{page.post_date}}</p>
 -->						</div>

							<div class="flyout__copy flyout__copy--restrict">
								<div class="Vacancy__details js-stagger js-copy">
									<div class="h6" v-html='page.post_content'></div>
								</div>
								<div class="Vacancy__footer js-stagger js-copy">
									<h6><a href="mailto:hello@loaf.agency" class="hover hover--link">Submit your CV and work examples</a></h6>
									<p>Submission deadline – {{page.acf[0].deadline}}</p>
								</div>
							</div>
						</div>
					</div>
				</div>

			</div>
		</div>
	</div>
	</transition>
</template>

<script>
	import size from 'size'
	import Scroll from '@/components/scroll'
	import Titleline from '@/components/modules/Titleline'
	import Footer from '@/components/Footer'
	import { isModifiedClick } from '@/utils'

	export default {
		name: 'Vacancy',
		extends: Scroll,
		components: {
			Titleline,
			Footer
		},
		data() {
			return {
				page: []
			}
		},
		created: function(){
			this.page = this.$root.$data.content.vacancy[this.$route.params.id]
			this.flyout = true
			// Title and meta are set by src/seo.js
		},
		mounted() {
			console.log('Vacancy:mounted')
			this.$eventBus.$emit('updateScroll')
			this.$eventBus.$emit('changeTheme', 'light')
			this.$eventBus.$emit('cursor:color', 'black')
			this.init()
			this.animateIn()
		},
		beforeDestroy: function() {
			this.destroy()
		},
		destroyed: function(){
			this.$eventBus.$emit('changeTheme', 'dark')
		},
		methods: {
			getUIExtend: function() {
				this.transform = this.$el.querySelectorAll('.js-transform')
				this.stagger = this.$el.querySelectorAll('.js-stagger')
			},
			routerBack: function(event) {
		  	// Let cmd/ctrl/shift-click open the real href in a new tab or window
		  	if (isModifiedClick(event)) return
		  	event.preventDefault()
		  	window.routeStorage.moreInfo = true
		  	this.$router.go(-1)
		  },
		  enter: function (el, done) {
		  	//console.log('Vacancy:enter', el)
		  	TweenMax.set(this.$el, { position: 'fixed', top: 0, left: 0, width: '100%', zIndex: 5 })
		  	done()
		  },
			animateIn: function() {
				console.log('Vacancy:animateIn')
				const tl = new TimelineMax({ paused: true })
				tl.set(this.$el, { position: 'relative' })
				tl.staggerFromTo(this.transform, 1, {
					cycle: {
						x: [-size.width, size.width]
					}
				}, {
					x: 0,
					ease: Quint.easeInOut
				}, 0, 0)
				tl.staggerFromTo(this.stagger, .65, {
					x: 20,
					autoAlpha: 0
				}, {
					x: 0,
					autoAlpha: 1,
					ease: Quint.easeOut
				}, .1, .35)
				tl.add(() => this.$eventBus.$emit('ready'), 1)
				tl.restart()
			},
		  leave: function (el, done) {
		  	console.log('Vacancy:leave', el)
		  	const tl = new TimelineMax({ paused: true, onComplete: done })
		  	tl.set(this.$el, { position: 'fixed', top: 0, left: 0, right: 0, width: '100%' })
		  	tl.staggerTo(this.transform, 1, {
					cycle: {
						x: [size.width, -size.width]
					},
					ease: Quint.easeInOut
				}, 0, 0)
				tl.staggerTo(this.stagger, .4, {
					autoAlpha: 0,
					ease: Linear.easeNone
				}, 0, 0)
				tl.restart()
		  },
			rAFExtend: function() {},
			resize: function() {}
		}
	}
</script>

<!-- Add "scoped" attribute to limit CSS to this component only -->
<style scoped lang="scss">
	.Vacancy {

		&__footer {
			padding-top: scaled-rem(80);

			p {
				margin-top: 20px;
			}
		}

	}
</style>


