<script>
import size from "size";
import sniffer from "sniffer";
import { decodeImage, toFixed } from "../utils.js";

const ease = 0.18;

export default {
  name: "Scroll",
  created: function () {
    this.options = { direction: "y", autoResize: true };
    this.cache = null;
    this.preloads = null;
    this.mouse = { x: 0, y: 0 };
    (this.data = {
      direction: null,
      scrolling: false,
      locked: false,
      ease: ease,
      current: 0,
      target: 0,
      last: 0,
      fixed: 0,
      max: 0,
    }),
      (this.flyout = false);
    this.disableSafari = false;
    this.headerScrollThreshold = 100; // Default scroll threshold for header visibility
  },
  mounted: function () {
    //console.log('Scroll:mounted')
    this.getUI();
    document.body.style.overflow = "hidden";
    // if(sniffer.isSafari) {
    //   this.disableSafari = true
    //   document.documentElement.classList.add('disable-safari-animations')
    // }
  },
  methods: {
    getUI: function () {
      const { width, height } = size;
      this.header = document.querySelector(".Header");
      this.footer = this.$el.querySelector(".Footer");
      this.bounding = this.$el.querySelector(".js-bounding");
      this.section = this.$el.querySelectorAll(".js-section");
      this.getUIExtend();
    },
    getUIExtend: function () {},
    init: function () {
      this.isDestroyed = false;
      window.addEventListener("resize", this.onResize);
      sniffer.isDesktop && window.addEventListener("mousemove", this.mousemove);
      this.getImages();
      this.preloadImages();
      this.observeLayout();
      this.$eventBus.$on("ready", this.onReady);
      this.$eventBus.$on(
        "setHeaderScrollThreshold",
        this.setHeaderScrollThreshold
      );
    },
    onReady: function () {
      this.data.ease = 1;
      this.$eventBus.$off("ready", this.onReady);
      this.options.autoResize && this.onResize();

      // New body height is calculated inside onTick so we need to wait too
      this.$nextTick(() => {
        window.scrollTo(0, this.data.target);
        document.body.style.overflow = "";

        //if(!sniffer.isSafari) {
        window.addEventListener("scroll", this.onScroll);
        TweenMax.ticker.addEventListener("tick", this.rAF);
        this.rAF(); // Call immediate too before we reset the ease
        //}

        this.data.ease = ease;
      });
    },
    destroy: function () {
      // console.log('Scroll:destroy')
      TweenMax.ticker.removeEventListener("tick", this.rAF);
      if (this.layoutObserver) this.layoutObserver.disconnect();
      window.removeEventListener("scroll", this.onScroll);
      window.removeEventListener("resize", this.onResize);
      sniffer.isDesktop &&
        window.removeEventListener("mousemove", this.mousemove);
      this.$eventBus.$off(
        "setHeaderScrollThreshold",
        this.setHeaderScrollThreshold
      );
      this.isDestroyed = true;
      this.cache = null;
      this.data = null;
    },
    mousemove: function (e) {
      this.mouse.x = e.clientX;
      this.mouse.y = e.clientY;
    },
    setHeaderScrollThreshold: function (threshold) {
      this.headerScrollThreshold = threshold || 100;
    },
    getImages: function () {
      const images = [];
      const preloads = Array.from(this.$el.querySelectorAll("img"));
      preloads.forEach((el) => {
        const loading = false;
        const loaded = false;
        const src = el.getAttribute("src");
        if (!src.includes("svg")) {
          images.push({
            el,
            src,
            loading,
            loaded,
          });
        }
      });
      this.preloads = images;
    },
    preloadImages: function () {
      const images = this.preloads;
      const done = (image) => {
        const indexOf = images.indexOf(image);
        indexOf > -1 && images.splice(indexOf, 1);
        image.loading = false;
        image.loaded = true;
        if (images.length === 0) {
          this.onResize();
        }
      };
      images.forEach((image) => {
        if (image.loading) return;
        image.loading = true;
        decodeImage(image.src, () => done(image));
      });
    },
    onScroll: function () {
      if (this.isDestroyed) return;
      const el = document.body;
      const scrollY = window.scrollY;
      if (this.data.current !== this.data.last)
        this.data.direction =
          this.data.current >= this.data.last ? "down" : "up";
      this.data.target = scrollY;
      this.data.last = this.data.current;
    },
    rAF: function () {
      if (this.isDestroyed) return;
      // Snap the page offset to whole device pixels. Fractional offsets put
      // block edges between pixels, and video layers round differently from
      // the content around them, which shows as thin lines at block joins.
      const dpr = window.devicePixelRatio || 1;
      const translate = Math.round(this.data.current * dpr) / dpr;
      this.data.scrolling =
        toFixed(this.data.target, 0) !== toFixed(this.data.current, 0);
      this.data.current +=
        (this.data.target - this.data.current) * this.data.ease;
      this.data.fixed = this.data.scrolling ? 3 : 0;
      sniffer.isDesktop &&
        !this.disableSafari &&
        (this.bounding.style.transform = `translate3d(0,-${translate}px,0)`);
      this.rAFSections();
      this.rAFElements();
      this.rAFExtend();
      if (
        sniffer.isDesktop &&
        !this.disableSafari &&
        this.data.current >= this.data.max - size.height * 2 &&
        this.footer
      ) {
        const parallax =
          (-size.height - (this.data.current - this.data.max)) / 2;
        this.footer.style.transform = `translate3d(0,${parallax}px,0)`;
      }
      if (this.data.scrolling) {
        document.body.classList.add("is-scrolling");
      } else {
        document.body.classList.remove("is-scrolling");
      }
      if (this.data.direction && scrollY > this.headerScrollThreshold) {
        document.body.classList.remove("is-scrolling--up");
        document.body.classList.remove("is-scrolling--down");
        document.body.classList.add(`is-scrolling--${this.data.direction}`);
      } else {
        document.body.classList.remove("is-scrolling--up");
        document.body.classList.remove("is-scrolling--down");
      }
    },
    rAFExtend: function () {},
    rAFElements: function () {
      if (!this.cache) return;
      const vertical = this.options.direction === "y";
      const threshold = this.options.threshold || 50;
      const boundary = vertical ? size.height : size.width;
      this.cache.forEach((data, index) => {
        const el = this.els[index];
        const { inView, start, end, direction } = this.isInView(data);
        if (!data.state && start > -threshold && end < boundary + threshold)
          return;
        inView
          ? this.inView(el, data, direction)
          : this.outView(el, data, direction);
      });
    },
    rAFSections: function () {
      if (!this.sections) return;
      this.sections.forEach((data, index) => {
        const { inView } = this.isInView(data);
        data.state = inView;
        if (!inView) return;
        data.fxs.length && this.applyFxs(data);
      });
    },
    applyFxs: function (data) {
      data.fxs.forEach((fx, i) => {
        const { el, type, speed } = fx;
        const offset = this.getSpeed(data, speed);
        const translate3d = toFixed(offset, this.data.fixed);
        let value = `none`;
        if (type === "translateX") value = `translate3d(${translate3d}px,0,0)`;
        if (type === "translateY") value = `translate3d(0,${translate3d}px,0)`;
        el.style.transform = value;
      });
    },
    getSpeed(section, speed) {
      const { start, middle } = section;
      const translate = toFixed(this.data.current, this.data.fixed);
      const centered = translate - (start - middle);
      return centered * speed;
    },
    isInView: function (bounds) {
      const { top, right, bottom, left, width, height } = bounds;
      const scrollY = this.data.target;
      const vertical = this.options.direction === "y";
      const threshold = 100;
      const boundary = vertical ? size.height : size.width;
      const start = (vertical ? top : left) - scrollY;
      const end = (vertical ? bottom : right) - scrollY;
      const inView = start < boundary + threshold && end > -threshold;
      const direction = start < 0 ? "top" : "bottom";
      return {
        top,
        right,
        bottom,
        left,
        start,
        end,
        inView,
        direction,
      };
    },
    inView: function (el, data, direction) {
      if (data.state) return;
      data.state = true;
      el.classList.add("in-viewport");
      //console.log('in view scroll.vue')
    },
    outView: function (el, data, direction) {
      if (!data.state) return;
      data.state = false;
      el.classList.remove("in-viewport");
      //console.log('out view scroll.vue ')
    },
    // Re-measure whenever the page's content changes size after load: a
    // carousel settling its height, video or embed sizes arriving, fonts.
    // Without this the scroll length (and the footer reveal, which works
    // from it) keeps the height measured at load, and in Safari, where
    // these settle later, the page could stop short with the bottom of the
    // content still over the footer. Measurements only: the "resize" event
    // isn't emitted, as some pages jump their scroll position on it.
    observeLayout: function () {
      if (!window.ResizeObserver) return;
      let frame = null;
      this.layoutObserver = new ResizeObserver(() => {
        if (frame) return;
        frame = requestAnimationFrame(() => {
          frame = null;
          if (this.isDestroyed) return;
          this.getBounding();
          this.getSections();
          this.getElements();
        });
      });
      this.layoutObserver.observe(this.$el);
    },
    onResize() {
      if (this.isDestroyed) return;
      this.getBounding();
      this.getSections();
      this.getElements();
      this.resize();
      this.$eventBus.$emit("resize");
    },
    getBounding: function () {
      this.$nextTick(() => {
        const el = this.bounding || this.$el;
        const bounding = this.$el.getBoundingClientRect();
        const max =
          bounding.height +
          (sniffer.isDesktop && !this.disableSafari && !this.flyout
            ? window.innerHeight
            : 0);
        this.data.max = max;
        document.body.style.height = `${max}px`;
      });
    },
    getSections: function () {
      if (!this.section.length) return;
      const vertical = this.options.direction === `y`;
      this.sections = [];
      this.section.forEach((el) => {
        const bounds = this.getBounds(el);
        const { inView, top, left, right, bottom } = this.isInView(bounds);
        const start = vertical
          ? top + (bottom - top) / 2
          : left + (right - left) / 2;
        const middle = (vertical ? size.height : size.width) / 2;
        const fxs = this.getEffects(el);
        this.sections.push({
          state: inView,
          top: top,
          left: left,
          right: right,
          bottom: bottom,
          start: start,
          middle: middle,
          fxs: fxs,
        });
      });
    },
    getBounds: function (el) {
      const scrollY = this.data.current;
      const vertical = this.options.direction === `y`;
      const bounding = el.getBoundingClientRect();
      return {
        top: bounding.top + (vertical ? scrollY : 0),
        right: bounding.right + (vertical ? 0 : scrollY),
        bottom: bounding.bottom + (vertical ? scrollY : 0),
        left: bounding.left + (vertical ? 0 : scrollY),
      };
    },
    getEffects: function (el) {
      //if(sniffer.isSafari) return
      const fxs = [];
      const effects = Array.from(el.querySelectorAll(".js-effect"));
      effects.forEach((el, i) => {
        const type = el.getAttribute("data-type");
        const speed = el.getAttribute("data-speed") || 0;
        fxs.push({ el, type, speed });
      });
      return fxs;
    },
    getElements: function () {
      //if(sniffer.isSafari) return
      this.cache = [];
      this.els = this.$el.querySelectorAll(".js-el");
      this.els.forEach((el, index) => {
        const bounds = el.getBoundingClientRect();
        const { inView, top, left, right, bottom } = this.isInView(bounds);
        const autoplay = el.hasAttribute("data-autoplay");
        const video = el.querySelector("video");
        this.cache.push({
          state: inView,
          top: top + window.scrollY,
          left: left,
          right: right,
          bottom: bottom + window.scrollY,
          video: autoplay ? video : null,
        });
      });
    },
  },
};
</script>



