<script>
import size from "size";
import SignupTrigger from "@/components/modules/SignupTrigger";
import moreThanCreative from "@/assets/more-than-creative.vue";

export default {
  name: "Header",
  components: {
    SignupTrigger,
    moreThanCreative,
  },
  data() {
    return {
      theme: "dark",
      burgerOpen: false,
      // "" | "hidden" | "fade": see the $route watcher. Kept in data (not
      // classList) so re-renders, e.g. on a theme change, don't drop it.
      routeReveal: "",
    };
  },
  computed: {
    headerClass() {
      const reveal = this.routeReveal ? ` Header--route-${this.routeReveal}` : "";
      return `Header theme--${this.theme}${reveal}`;
    },
  },
  created() {
    this.isBusy = false;
    this.$eventBus.$on("changeTheme", this.changeTheme);
    this.$eventBus.$on("toggleHeader", this.toggleHeader);
  },
  watch: {
    // Opening a page while the header is scrolled out of view (e.g. a case
    // study from a scrolled grid): the new page starts at the top, which
    // would slide the header back down. Instead, put it back in place
    // invisibly and fade it in once the new page is ready.
    $route: function () {
      const body = document.body;
      if (!body.classList.contains("is-scrolling--down")) return;
      clearTimeout(this.revealTimer);
      clearTimeout(this.revealCleanup);
      if (this.pendingReveal) this.$eventBus.$off("ready", this.pendingReveal);

      // In place at the top, invisible, with no transition, so dropping
      // the scrolled-away class below can't animate anything
      this.routeReveal = "hidden";
      body.classList.remove("is-scrolling--down", "is-scrolling--up");

      let revealed = false;
      const reveal = () => {
        if (revealed) return;
        revealed = true;
        this.$eventBus.$off("ready", reveal);
        this.pendingReveal = null;
        clearTimeout(this.revealTimer);
        // .Header--route-fade transitions opacity from 0 to 1. Two frames
        // first, so the hidden state has been painted even when "ready"
        // arrives straight after the route change (nothing to fade from
        // otherwise).
        requestAnimationFrame(() =>
          requestAnimationFrame(() => {
            this.routeReveal = "fade";
            // Back to the normal slide-on-scroll behaviour once faded in
            this.revealCleanup = setTimeout(() => {
              this.routeReveal = "";
            }, 600);
          })
        );
      };
      this.pendingReveal = reveal;
      this.$eventBus.$on("ready", reveal);
      this.revealTimer = setTimeout(reveal, 1500); // in case "ready" never comes
    },
  },
  mounted: function () {
    this.close = this.$el.querySelector(".js-close");
    this.els = this.$el.querySelectorAll(".js-transform");
    this.stagger = this.$el.querySelectorAll(".js-stagger");
    TweenMax.set(this.els[0], {
      x: "-100%",
    });
    TweenMax.set(this.els[1], {
      x: "100%",
    });
    this.onResize();

    window.addEventListener("resize", () => {
      this.$refs["burger1"].style.height = `${window.innerHeight}px`;
      this.$refs["burger2"].style.height = `${window.innerHeight}px`;
    });
  },
  methods: {
    onResize: function () {
      const { height } = size;
      // console.log(height);
      this.els.forEach((el) => {
        Object.assign(el.style, {
          height: `${height}px`,
        });
      });
    },
    toggleHeader: function (show) {
      show
        ? this.$el.classList.add("u-hide")
        : this.$el.classList.remove("u-hide");
    },
    changeTheme: function (theme) {
      this.theme = theme;
      this.$forceUpdate();

      //console.log(this.theme, "theme", Math.random());
    },
    logoClick: function () {
      this.toggleBurger();
      this.$router.push({ path: "/", params: {} });
    },
    toggleBurger: function (event) {
      if (this.isBusy) return;
      const tl = new TimelineMax({ paused: true });
      this.isBusy = true;
      this.burgerOpen = !this.burgerOpen;
      window.App.menu = this.burgerOpen;
      this.$eventBus.$emit("toggleBurger", this.burgerOpen);
      if (this.burgerOpen) {
        this.$eventBus.$emit("cursor:color", "black");
        tl.staggerFromTo(
          this.els,
          1,
          {
            cycle: {
              x: ["100%", "-100%"],
            },
          },
          {
            x: "0%",
            ease: Quint.easeInOut,
          },
          0,
          0
        );
        tl.staggerFromTo(
          this.stagger,
          0.75,
          {
            x: 30,
            autoAlpha: 0,
          },
          {
            x: 0,
            autoAlpha: 1,
            ease: Quint.easeOut,
          },
          0.05,
          0.5
        );
        // tl.add(() => this.close.classList.add("burger__trigger--open"), 0.35);
      } else {
        this.$eventBus.$emit("cursor:color", "white");
        tl.staggerTo(
          this.els,
          1,
          {
            cycle: {
              x: ["-100%", "100%"],
            },
            ease: Quint.easeInOut,
          },
          0,
          0
        );
        //tl.add(() => this.close.classList.remove("burger__trigger--open"), 0);
      }
      tl.add(() => (this.isBusy = false), 1);
      tl.restart();
    },
  },
};
</script>

