<template>
	<div ref="titleLine" :class="generateClass">
		<div class="before" ref="before"></div>
		<span ref="span">{{label}}</span>
		<div class="after" ref="after"></div>
	</div>
</template>

<script>
	export default {
		data() {
			return {
				titleClass: 'titleLine'
			}
		},
		props: {
			pullup: {
				type: Boolean,
				required: false
			},
			theme: {
				type: String,
				required: false
			},
			overlap: {
				type: Boolean,
				required: false
			},
			animate: {
				type: Boolean,
				required: false
			},
			autoStart: {
				type: Boolean,
				required: false,
				default: true
			},
			label: {
				type: String,
				required: true
			},
			first: {
				type: Boolean,
				default: false
			}
		},
		computed: {
			generateClass: function() {
				let titleClass = 'titleLine'
				if(this.pullup) titleClass += ' titleLine--pullup'
				if(this.overlap) titleClass += ' titleLine--overlap'
				if(this.theme) titleClass += ' titleLine--' + this.theme
				if(this.first) titleClass += ' first'
					
				return titleClass
			}
		},
		mounted() {
			this.isVisible = false
			//if(this.animate) {
				window.addEventListener('scroll', this.onScroll)
			//}
			this.set()
			if(this.autoStart) this.animateIn()
		},
		destroyed() {
			window.removeEventListener('scroll', this.onScroll)
		},
		methods: {
			set() {
				const { span, before, after } = this.$refs				
				TweenMax.set(before, {
					scaleY: 0,
					transformOrigin: 'top center'
				})
				TweenMax.set(after, {
					scaleY: 0,
					transformOrigin: 'bottom center'
				})
				TweenMax.set(span, {
					y: -10,
					autoAlpha: 0
				})
			},
			animateIn() {
				if (this.isVisible) return
				const { span, before, after } = this.$refs
				const tl = new TimelineMax({ paused: true })
				TweenMax.killTweensOf([span, before, after])
				tl.fromTo(before, .75, {
					scaleY: 0,
					transformOrigin: 'top center'
				}, {
					scaleY: 1,
					ease: Quint.easeOut
				}, 0)
				tl.fromTo(after, .75, {
					scaleY: 0,
					transformOrigin: 'bottom center'
				}, {
					scaleY: 1,
					ease: Quint.easeOut
				}, 0)
				tl.fromTo(span, .75, {
					y: -10,
					autoAlpha: 0
				}, {
					y: 0,
					autoAlpha: 1,
					ease: Quint.easeOut
				}, 0.5)
				tl.restart()
				this.isVisible = true
			},
			animateOut() {
				if (!this.isVisible) return
				const { span, before, after } = this.$refs
				const tl = new TimelineMax({ paused: true })
				TweenMax.killTweensOf([span, before, after])
				tl.to(before, .5, {
					scaleY: 0,
					transformOrigin: 'top center',
					ease: Quint.easeInOut
				}, 0)
				tl.to(after, .5, {
					scaleY: 0,
					transformOrigin: 'bottom center',
					ease: Quint.easeInOut
				}, 0)
				tl.to(span, .5, {
					autoAlpha: 0,
					ease: Quint.easeOut
				}, 0)
				tl.restart()
				this.isVisible = false
			},
			onScroll() {
				const bounding = this.$el.getBoundingClientRect()
				const mid = window.innerHeight/2

				if(bounding.top <= mid) {
					this.animateOut()
				} else {
					this.animateIn()
				}
			}
		}
	}
</script>


