<template>
  <transition appear v-on:appear="enter" v-on:leave="leave" v-bind:css="false">
    <div class="Home theme--white">
      <div class="Home-transform js-transform">
        <div class="Home-transform js-transform">
          <div class="Section-bounding js-bounding">
            <div
              class="tw-bg-white md:tw-pt-12 lg:tw-pt-[160px] tw-pb-20 lg:tw-pb-44 tw-text-loafblack"
            >
              <div class="page__container">
                <!-- The page's H1: the design has no visible heading here -->
                <h1 class="u-visually-hidden">Work</h1>
                <div class="Home__work u-vacuum" ref="work">
                  <div class="u-vacuum--restore">
                    <div
                      class="work__tags tw-flex tw-flex-col lg:tw-flex-row lg:tw-gap-4 tw-mb-10 lg:tw-mb-14"
                    >
                      <div
                        class="work__tag cursor-plus"
                        :class="activeTag === 'all' ? 'active' : ''"
                        @click="activeTag = 'all'"
                      >
                        <span class="text">All</span>
                        <span class="tw-pl-3 tw-hidden lg:tw-inline-block"
                          >|</span
                        >
                      </div>
                      <div
                        :class="activeTag === tag.slug ? 'active' : ''"
                        @click="activeTag = tag.slug"
                        v-for="(tag, index) in categories"
                        :key="tag.slug"
                        class="work__tag cursor-plus"
                      >
                        <span class="text">{{ tag.name }}</span>
                        <span
                          v-if="index !== categories.length - 1"
                          class="tw-pl-3 tw-hidden lg:tw-inline-block"
                          >|</span
                        >
                      </div>
                    </div>
                    <!-- Links to the sector pages (not a filter) -->
                    <SectorNav class="work__sectors" theme="solid" label="Sector" />
                  </div>
                </div>
              </div>
              <div class="tw-mx-auto tw-max-w-[1800px]">
                <div>
                  <div>
                    <div
                      class="tw-grid tw-grid-cols-1 md:tw-grid-cols-2 lg:tw-grid-cols-3 tw-gap-y-10 md:tw-gap-y-12"
                    >
                      <a
                        :key="item.ID"
                        v-for="item in filteredItems"
                        :ref="'work' + item.ID"
                        :href="'/work/' + item.post_name"
                        :data-post="item.post_name"
                        class="work__item tw-block tw-w-full tw-no-underline"
                        @click="handleWorkClick($event, item.post_name)"
                      >
                        <div
                          :class="[
                            'tw-aspect-square lg:tw-aspect-[13/9] tw-w-full tw-object-cover cursor-plus-white',
                            item.acf[0].feature_video ? 'image-src--video' : '',
                          ]"
                          :data-focus-x="item.acf[0].focus_point_x"
                          :data-focus-y="item.acf[0].focus_point_y"
                        >
                          <video
                            v-if="item.acf[0].feature_video"
                            autoplay
                            disableRemotePlayback
                            loop
                            muted
                            class="tw-w-full tw-h-full tw-object-cover"
                            playsinline
                            @loadeddata="$event.target.classList.add('is-loaded')"
                          >
                            <source
                              :src="item.acf[0].feature_video"
                              type="video/mp4"
                            />
                          </video>
                          <img
                            v-else-if="item.acf[0].work_page_image_override"
                            :src="
                              item.acf[0].work_page_image_override.sizes.large
                            "
                            :alt="
                              imageAlt(
                                item.acf[0].work_page_image_override,
                                workLabel(item)
                              )
                            "
                            class="tw-w-full tw-h-full tw-object-cover"
                          />
                          <img
                            v-else
                            :src="item.acf[0].feature_image.sizes.large"
                            :alt="imageAlt(item.acf[0].feature_image, workLabel(item))"
                            class="tw-w-full tw-h-full tw-object-cover"
                          />
                        </div>
                        <div class="meta">
                          <div class="meta__title">
                            <div
                              class="meta__title__item meta__title1 tw-font-medium tw-inline-block tw-mb-2"
                              v-html="
                                (item.acf[0].homepage_title_override
                                  ? item.acf[0].homepage_title_override
                                  : item.post_title
                                ).replace(/<br\s*\/?>/gi, '')
                              "
                            ></div>
                            <br />
                            <div
                              class="h2 meta__title__item meta__title2 js-stagger tw-inline-block"
                            >
                              {{ item.acf[0].client }} –
                              {{ item.acf[0].caption }}
                            </div>
                          </div>
                        </div>
                      </a>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
          <Footer></Footer>
        </div>
      </div>
    </div>
  </transition>
</template>

<script>
import Footer from "@/components/Footer";
import Scroll from "@/components/scroll";
import { isModifiedClick, imageAlt, workLabel } from "@/utils";
import SectorNav from "@/components/modules/SectorNav";

export default {
  name: "Work",
  extends: Scroll,
  components: {
    SectorNav,
    Footer,
  },
  data() {
    return {
      items: [],
      activeTag: "all",
      tags: [
        {
          name: "All",
          slug: "all",
        },
        {
          name: "Campaigns",
          slug: "campaigns",
        },
        {
          name: "Branding",
          slug: "branding",
        },
        {
          name: "Digital Experiences",
          slug: "digital-experiences",
        },
      ],
    };
  },
  computed: {
    filteredItems() {
      const itemsArray = Object.values(this.items).filter(
        (item) => item.status === "publish"
      );
      if (this.activeTag === "all") {
        return itemsArray;
      }
      return itemsArray.filter((item) => {
        return (
          item.category &&
          item.category.some((cat) => cat.slug === this.activeTag)
        );
      });
    },
  },
  created() {
    this.items = this.$root.$data.content.work;
    this.categories = this.$root.$data.content.work_categories;
    this.$eventBus.$emit("updateScroll");
    this.$eventBus.$emit("changeTheme", "light");
    this.$nextTick(() => {
      this.$eventBus.$emit("ready");
    });
  },
  mounted() {
    this.init();
    this.animateIn();
    this.restoreScrollPosition();
  },
  beforeDestroy: function () {
    this.destroy();
  },
  destroyed: function () {
    //  console.log("Work:destroyed");
  },
  methods: {
    imageAlt,
    workLabel,
    getUIExtend: function () {},
    enter: function (el, done) {
      //  console.log("Work:enter", el);
      done();
    },
    animateIn: function () {
      const atTop = this.$route.query.scrollY ? false : true;
      const tl = (this.tl = new TimelineMax());
      const workTags = this.$el.querySelector(".work__tags");
      const workItems = this.$el.querySelectorAll(".work__item");
      TweenMax.set(workTags, {
        opacity: 0,
      });
      TweenMax.set(workItems, {
        opacity: 0,
      });
      tl.to(workTags, 1, {
        opacity: 1,
      });
      tl.staggerFromTo(
        workItems,
        1,
        { opacity: 0 },
        { opacity: 1 },
        0.05,
        atTop ? "-=0.5" : "-1"
      );
    },
    leave: function (el, done) {
      //   const atTop = this.$route.query.scrollY ? false : true;
      //   const tl = (this.tl = new TimelineMax());
      //   const workTags = this.$el.querySelector(".work__tags");
      //   const workItems = this.$el.querySelectorAll(".work__item");

      //   tl.set(this.$el, {
      //     position: "fixed",
      //     top: 0,
      //     left: 0,
      //     right: 0,
      //     width: "100%",
      //   });

      //   if (atTop) {
      //     tl.to(workTags, 1, {
      //       opacity: 0,
      //     });
      //   }
      //   tl.staggerFromTo(workItems, 1, { opacity: 1 }, { opacity: 0 }, 0.1, "-1");
      //   tl.call(() => done());
      done();
    },
    resize: function () {},
    handleWorkClick(event, postName) {
      // Let cmd/ctrl/shift-click open the real href in a new tab or window
      if (isModifiedClick(event)) return;
      event.preventDefault();

      // Capture the current scroll position from the custom scroll system
      const scrollY = this.data ? this.data.current : window.scrollY;
      const roundedScrollY = Math.round(scrollY);

      // Navigate with the scroll position as a query parameter
      this.$router.push({
        path: `/work/${postName}`,
        query: { scrollY: roundedScrollY.toString() },
      });
    },
    restoreScrollPosition() {
      const scrollY = this.$route.query.scrollY;
      if (scrollY) {
        const targetScroll = parseInt(scrollY, 10);
        // Set both target and current for instant scroll
        this.$nextTick(() => {
          if (this.data) {
            this.data.target = targetScroll;
            this.data.current = targetScroll;
            // Also set the actual window scroll position
            window.scrollTo(0, targetScroll);
          }
        });
      }
    },
  },
};
</script>

<!-- Add "scoped" attribute to limit CSS to this component only -->
<style scoped lang="scss">
.Home {
  &__work {
    @media (max-width: 1024px) {
      padding-top: 120px;
    }
    @media (min-width: 1025px) {
      padding-top: 120px;
    }
  }

  .work {
    &__sectors {
      margin: -12px 0 56px;

      @include breakpoint(tab) {
        margin: -8px 0 40px;
      }
    }

    &__tags {
      font-weight: 500;
      letter-spacing: -0.04em;
      font-size: 25px;
      color: #979798;

      @include breakpoint(1440px, "max-width") {
        font-size: 22px;
      }

      .text {
        transition: color 0.3s ease;
      }
      .active .text {
        color: #000;
      }

      .work__tag {
        &:hover .text {
          color: #000;
        }
      }
      @include breakpoint(phab) {
        font-size: 18px;
      }
    }

    &__item {
      .meta__title__item {
        letter-spacing: -0.03em;
      }
      .meta__title div:after {
        background-color: black;
        bottom: -5px;
        //transform: scaleX(1);
      }
      .meta__title1,
      .meta__title2 {
        font-size: 23px;

        @include breakpoint(1440px, "max-width") {
          font-size: 20px;
        }
        @include breakpoint(phab) {
          font-size: 18px;
        }
      }

      img,
      video {
        transition: filter 0.5s ease;
        will-change: filter;
        background-color: #000;
      }

      // The tile's 13:9 box rarely lands on whole pixels, and Chrome can draw
      // the video frame a sliver short of it on any side, showing whatever is
      // behind as a thin line. So the video box is 1px bigger all round and
      // clipped back to its original size: the frame always covers the
      // visible area, which still lines up with the image tiles. The clip is
      // on the video, not the tile, as the tile also holds the gap below the
      // inline video. The black placeholder only stays until it has loaded.
      .image-src--video video {
        width: calc(100% + 2px);
        height: calc(100% + 2px);
        margin: -1px;
        clip-path: inset(1px);

        &.is-loaded {
          background-color: transparent;
        }
      }
      &:hover {
        img,
        video {
          filter: brightness(0.7);
        }

        .meta__title div:after {
          transform: scaleX(1);
          transform-origin: left center;
        }
      }

      .meta {
        padding: 25px 15px 25px 20px;
        line-height: 1;

        @include breakpoint(1440px, "max-width") {
          padding: 20px 10px 20px 15px;
        }

        @include breakpoint(phab) {
          padding: 20px 15px;
        }
      }
    }
  }
}
</style>



