<template>
	<div class="Share">
		<div @click="toggleShare" class="shareToggle u-inline-block"><p class="hover hover--link hover--link--cross u-inline-block">Share <span class="cross cross--small"></span></p></div>

		<ul class="shareList">
			<li class="shareList__child"><a v-bind:href="'https://twitter.com/intent/tweet?url=https://loaf.agency' + backURL" class="hover hover--link">Twitter</a></li>
			<li class="shareList__child"><a v-bind:href="'https://www.facebook.com/sharer/sharer.php?u=https://loaf.agency' + backURL" class="hover hover--link">Facebook</a></li>
			<li class="shareList__child"><a v-bind:href="'http://www.linkedin.com/shareArticle?mini=true&url=https://loaf.agency' + backURL" class="hover hover--link">LinkedIn</a></li>
			<li class="shareList__child"><a v-bind:href="'mailto:?body=https://loaf.agency' + backURL" class="hover hover--link">Email</a></li>
		</ul>
	</div>
</template>

<script>
	export default {
		data() {
			return {
				
			}
		},
		props: {
			backURL: {
				type: String,
				required: true
			}
		},
		mounted() {
			
		},
		destroyed() {
			
		},
		methods: {
			toggleShare: function(event) {
				event.currentTarget.classList.toggle('active')
				event.currentTarget.classList.toggle('disabled')

				this.stagger = this.$el.querySelectorAll('.shareList__child')
				const tl = new TimelineMax()
				if(event.currentTarget.classList.contains('active')) {
					tl.staggerFromTo(this.stagger, .5, {
						y: 0,
						autoAlpha: 0
					}, {
						y: 10,
						autoAlpha: 1
					}, .10, 0)
				} else {
					tl.staggerFromTo(this.stagger, .75, {
						y: 10,
						autoAlpha: 1
					}, {
						y: 0,
						autoAlpha: 0
					}, .10, 0)
				}
			}
		}
	}
</script>

<style lang="scss">
	
	.Share {
		position: relative;

		.cross {
			margin-top: -3px;
			@include breakpoint(phab) {
				display: none;	
			}
		}
		
		.shareToggle {
			display: block;
			font-size: scaled-rem(19);
			font-family: "Apercu-Mono" !important;
			letter-spacing: -1px;
		}
		
		.shareToggle {
			&.active {
				opacity: 0.5;
			}
		}

		.shareList {
			position: absolute;
			top: -11px;
    		left: 60px;
			display: block;
			li {
				opacity: 0;
				display: inline-block;
				margin-right: 2px;
				a {
					font-size: scaled-rem(16);
				}
			}
		}
	}

</style>


