<script>
import size from "size";
import sniffer from "sniffer";
import Scroll from "@/components/scroll";
import Footer from "@/components/Footer";
import Titleline from "@/components/modules/Titleline";
import Share from "@/components/modules/Share";
import GallerySlider from "@/components/modules/GallerySlider";
import AudioPlayer from "@/components/modules/AudioPlayer";
import {
  decodeImage,
  toFixed,
  isModifiedClick,
  imageAlt,
  workLabel,
} from "../utils";

export default {
  name: "Project",
  extends: Scroll,
  components: {
    GallerySlider,
    AudioPlayer,
    Titleline,
    Share,
    Footer,
  },
  data() {
    return {
      item: [],
      audioPlayerTime: null,
      playState: "Play",
      infoOpen: false,
      infoHeight: 0,
      nextUrl: null,
      carouselCount: 1,
      mouseClickPos: 0,
      mouseDragging: false,
      // Moving image blocks (by index) the visitor has turned the sound on for
      soundOn: {},
      videoWidth: 0,
    };
  },

  computed: {
    // "Client — Title": alt text fallback for this case study's images until
    // they have alt text in the WordPress media library
    imageContext: function () {
      return workLabel(this.item);
    },
    // Set when the case study was opened from a showcase collection
    showcaseSlug: function () {
      return this.$route.query.showcase || null;
    },
    // The grid we arrived from: the showcase collection, or /work
    backWorkPath: function () {
      return this.showcaseSlug ? `/showcase/${this.showcaseSlug}` : "/work";
    },
  },

  watch: {
    $route(to, from) {
      // this.setup()
    },
  },
  created: function () {
    this.options.autoResize = true;
    this.options.threshold = 0;
    this.item = this.$root.$data.content.work[this.$route.params.id];
    var that = this;
    Object.keys(this.$root.$data.content.work).forEach(function (item, index) {
      if (
        that.$root.$data.content.work[item].menu_order ==
        that.item.menu_order + 1
      ) {
        that.nextUrl = that.$root.$data.content.work[item].post_name;
      }
    });
    // Title, meta and robots (incl. noindex on drafts) are set by src/seo.js
  },
  mounted: function () {
    //console.log('Project:mounted')
    this.addImage();
    this.$eventBus.$emit("changeFooterTheme", "light");
    this.init();
    this.$nextTick(() => this.animateIn());
    this.$eventBus.$on("resize", this.scrollTo);
    if (this.$refs.audioPlayer) this.audioProgress();
    //this.$nextTick(() => this.findGreyOverlaps());

    const that = this;
    if (sniffer.isDesktop) {
      window.addEventListener("mouseup", function () {
        if (event.clientX != this.mouseClickPos) {
          that.mouseDragging = true;
        }
        setTimeout(function () {
          that.mouseDragging = false;
        }, 100);
      });
      window.addEventListener("mousedown", function (event) {
        this.mouseClickPos = event.clientX;
      });

      document.onkeydown = function (e) {
        e = e || window.event;
        if (e.keyCode == 27) {
          that.closeFullscreenVideo();
        }
      };
    }
  },
  beforeDestroy: function () {
    this.destroy();
  },
  destroyed: function () {
    //console.log('project destroyed')
    //this.$eventBus.$emit('changeTheme', 'dark')
  },
  methods: {
    imageAlt,
    getUIExtend: function () {
      this.stagger = this.$el.querySelectorAll(".js-stagger");
      this.alpha = this.$el.querySelector(".js-alpha");
      this.transform = this.$el.querySelectorAll(".js-transform");
    },
    addImage: function () {
      if (window.routeStorage.route === "home") {
        this.image = window.routeStorage.coverImage;
        this.image.style.transform = `none`;
        this.$refs.cover.insertBefore(this.image, this.$refs.cover.firstChild);
        this.resizeImage();
        delete window.routeStorage.coverImage;
      } else {
        if (this.$root.img_cache[this.item.post_title]) {
          this.image = this.$root.img_cache[this.item.post_title];
          this.resizeImage();
          TweenMax.set(this.image, { autoAlpha: 0 });
          this.$refs.cover.insertBefore(
            this.image,
            this.$refs.cover.firstChild
          );
          TweenMax.to(this.image, 1, {
            autoAlpha: 1,
          });
        } else {
          const objectPath =
            this.$root.$data.content.work[this.$route.params.id];
          let projectHero = objectPath.acf[0].feature_image;
          if (
            window.innerWidth > 800 &&
            objectPath.acf[0].feature_image_portrait
          ) {
            projectHero = objectPath.acf[0].feature_image_portrait;
          }
          this.image = decodeImage(projectHero.url, () => {
            this.resizeImage();
            TweenMax.set(this.image, { autoAlpha: 0 });
            this.$refs.cover.insertBefore(
              this.image,
              this.$refs.cover.firstChild
            );
            TweenMax.to(this.image, 1, {
              autoAlpha: 1,
            });
          });
        }
      }
      // The hero is created in JS (or reused from the homepage/cache), so its
      // alt is set here: the media library's alt text, else "Client — Title"
      if (this.image) {
        this.image.alt = imageAlt(this.item.acf[0].feature_image, this.imageContext);
      }
      window.routeStorage.route = "project";
    },
    enter: function (el, done) {
      if (!sniffer.isDevice && !sniffer.isSafari) {
        TweenMax.set(this.$el, {
          position: "fixed",
          top: 0,
          left: 0,
          width: "100%",
        });
        done();
      }
    },
    leave: function (el, done) {
      // Animate `el` (the element Vue is removing) rather than this.$el, which
      // is unreliable once the instance is being torn down.
      let finished = false;
      const finish = function () {
        if (finished) return;
        finished = true;
        done();
      };
      const tl = new TimelineMax({ onComplete: finish });
      tl.set(el, {
        position: "fixed",
        top: 0,
        left: 0,
        right: 0,
        width: "100%",
      });
      tl.to(el, 0.6, {
        opacity: 0,
      });
      // Safety net: navigating case study -> case study replaces the component
      // via the router-view key, and the timeline can stall mid-tween. Without
      // this the old page is never removed and both stay stacked in the DOM.
      setTimeout(finish, 900);
    },
    animateIn: function () {
      const tl = new TimelineMax({ paused: true });
      tl.staggerFromTo(
        this.stagger,
        0.75,
        {
          y: -20,
          autoAlpha: 0,
        },
        {
          y: 0,
          autoAlpha: 1,
        },
        0.2,
        0
      );
      tl.add(() => this.$eventBus.$emit("ready"), 0);
      setTimeout(function () {
        tl.restart();
      }, 200);
    },
    rAFExtend: function () {
      if (!this.image) return;
      const current = Math.round(Math.abs(this.data.current));
      if (!sniffer.isDevice) {
        const scale = 1 + current / (size.height * 4);
        const opacity = Math.max(
          0,
          Math.min(1 - current / (size.height * 0.25), 1)
        );
        this.alpha.style.opacity = opacity;
        this.image.style.transform = `scale3d(${scale},${scale},${scale})`;
      }
      if (current >= size.height - 65) {
        this.$eventBus.$emit("changeTheme", "light");
      } else {
        this.$eventBus.$emit("changeTheme", "dark");
      }
      if (
        window.App.menu ||
        (this.mouse.y >= size.height - current &&
          this.mouse.y + current <= this.data.max - 233)
      ) {
        this.$eventBus.$emit("cursor:color", "black");
      } else {
        this.$eventBus.$emit("cursor:color", "white");
      }

      if (!sniffer.isDevice && this.$refs.gallery) {
        const that = this;
        this.$refs.gallery.forEach(function (item) {
          if (
            that.mouse.y >= item.getBoundingClientRect().top &&
            that.mouse.y <= item.getBoundingClientRect().bottom
          ) {
            if (that.mouse.x < window.innerWidth / 2) {
              item.classList.add("leftCursor");
              item.classList.remove("rightCursor");
            } else {
              item.classList.remove("leftCursor");
              item.classList.add("rightCursor");
            }
          }
        });
      }
    },
    inView: function (el, data, direction) {
      if (data.state) return;
      data.state = true;
      el.classList.add("in-viewport");

      if (!this.touchesNeighbour(el)) {
        const unit = 130;
        const tl = new TimelineMax({});
        tl.set(el, {
          //autoAlpha:0,
          y: direction === "top" ? -unit : unit,
        });
        tl.to(el, 2.3, {
          //		        	autoAlpha: 1,
          y: 0,
          ease: Quint.easeOut,
        });
      }
      if (data.video) {
        setTimeout(function () {
          // console.log('start moving image - project.vue')
          data.video.play();
        }, 700);
      }
    },
    // A block that sits flush against the one above or below it (no margin
    // between them) must not slide in on its own: the 130px offset pulls it
    // away from its neighbour and opens a gap showing the page background
    // until the tween settles. Blocks are each wrapped in a v-for div, so the
    // neighbour is the first child of the next wrapper.
    touchesNeighbour: function (el) {
      const flush = "Project__block--noMarginTop";
      if (el.classList.contains(flush)) return true;
      const nextWrapper = el.parentElement && el.parentElement.nextElementSibling;
      const next = nextWrapper && nextWrapper.firstElementChild;
      return !!(next && next.classList.contains(flush));
    },
    outView: function (el, data, direction) {
      if (!data.state) return;
      //console.log('out view - project.vue')
      data.state = false;
      el.classList.remove("in-viewport");
      if (data.video) {
        //console.log('pause moving image - project.vue')
        data.video.pause();
        data.video.currentTime = 0;
      }
      if (el.classList.contains("active")) {
        //console.log('stop video!', el)
        el.querySelector("video").pause();
        el.classList.remove("playing");
        el.click();
      }
      this.carouselCount = 1;
    },
    resize: function () {
      // The hero image is sized by CSS (object-fit: cover), so it tracks the
      // viewport live while the window is being dragged. Nothing to do here.
    },
    resizeImage: function () {
      if (!this.image) return;
      // Fill the header and let the browser crop. Previously this computed
      // pixel sizes from the `size` module, whose values only update 150ms
      // after resizing stops — so the last resize often used a stale width
      // and left a black bar down the side until the next resize.
      Object.assign(this.image.style, {
        position: "absolute",
        top: "0",
        left: "0",
        width: "100%",
        height: "100%",
        objectFit: "cover",
        objectPosition: "center center",
      });
      if (sniffer.isDevice) {
        // Lock the height on touch devices so the hero doesn't jump when the
        // browser toolbar shows/hides (100vh includes the hidden toolbar).
        this.$refs.cover.style.height = `${window.innerHeight}px`;
      }
    },
    injectVideo: function (event, videoURL) {
      console.log("inject video");

      let videoObject;
      const video = event.currentTarget.querySelector(".video");
      const target = event.currentTarget;
      const that = this;

      if (!target.querySelector("video")) {
        //no video, inject, and go fullscreen
        console.log("no video, inject");
        this.videoFullscreen(target, video, videoURL);
      } else if (target.classList.contains("fullscreen")) {
        //already injected, disable fullscreen
        console.log("disable full");
        this.$eventBus.$emit("toggleHeader", false);
        if (target.classList.contains("in-viewport")) {
          window.scrollTo({
            top: window.scrollY + video.getBoundingClientRect().top - 60,
            behavior: "smooth",
          });
        }
        TweenMax.to(video, 1.2, {
          width: this.videoWidth,
          height: this.videoWidth * 0.56,
          ease: Power4.easeInOut,
          onComplete: function () {
            target.classList.remove(
              "fullscreen",
              "fullscreen-finished",
              "playing"
            );
            video.querySelector("video").pause();
            video.querySelector("video").remove();
            target.classList.remove("active");
            target.style.zIndex = 2;
            video.style.removeProperty("width");
            video.style.removeProperty("height");
          },
        });
      } else if (target.classList.contains("in-viewport")) {
        console.log("enable full");
        //already injected, enable fullscreen
        this.videoFullscreen(target, video, false);
        video.querySelector("video").play();
      } else {
        console.log("video out of view");
      }
    },
    videoFullscreen(target, video, videoURL) {
      const that = this;
      const videoInner = target.querySelector(".video__inner");
      target.classList.add("playing", "fullscreen");
      this.videoWidth = video.getBoundingClientRect().width;

      TweenMax.set(video, {
        width: this.videoWidth,
        maxWidth: "none",
      });

      setTimeout(function () {
        window.scrollTo({
          top: window.scrollY + video.getBoundingClientRect().top,
          behavior: "smooth",
        });
      }, 500);
      TweenMax.to(video, 1.2, {
        width: window.innerWidth,
        height: window.innerHeight + 30,
        ease: Power4.easeInOut,
        onComplete: function () {
          if (videoURL) {
            that.loadVideo(videoURL, videoInner);
            const videoObject = target.querySelector("video");
            TweenMax.fromTo(
              videoObject,
              2,
              {
                autoAlpha: 0,
              },
              {
                autoAlpha: 1,
              }
            );
          }
          target.classList.add("active");
          target.classList.add("fullscreen-finished");
        },
      });
      this.$eventBus.$emit("toggleHeader", true);
    },
    loadVideo(videoURL, videoInner) {
      let videoObject = document.createElement("video");
      videoObject.src = videoURL;
      videoObject.autoplay = true;
      videoObject.loop = true;
      videoObject.setAttribute("playsinline", null);
      videoObject.disableRemotePlayback = true;
      videoObject.controls = sniffer.isDevice ? true : false;
      videoInner.appendChild(videoObject);

      console.log("play button");
      if (sniffer.isIos) {
        let playButton = document.createElement("button");
        playButton.classList.add("video__playButton");
        playButton.innerHTML = "";
        playButton.addEventListener("click", (e) =>
          this.forcePlay(e, videoObject, playButton)
        );
        videoInner.appendChild(playButton);
      }
    },
    forcePlay: function (event, video, me) {
      event.stopPropagation();
      event.preventDefault();
      video.play();
      me.remove();
    },
    // ACF file fields come back as an array ({ url, ... }) or a plain URL
    // string depending on the field's return format — video_upload is an
    // array, video_upload_mobile is a URL — and as false/"" when empty.
    fileUrl: function (file) {
      if (!file) return "";
      return typeof file === "object" ? file.url || "" : file;
    },
    backgroundImage: function (landscape, portrait, raw) {
      if (window.innerWidth > 800 || !portrait) {
        if (raw) {
          return landscape;
        } else {
          return {
            "background-image": "url(" + landscape + ")",
          };
        }
      } else {
        if (raw) {
          return portrait;
        } else {
          return {
            "background-image": "url(" + portrait + ")",
          };
        }
      }
    },
    responsiveGallery: function (landscape, portrait) {
      if (window.innerWidth > 800 || !portrait) {
        return landscape;
      } else {
        return portrait;
      }
    },
    audioToggle: function (event) {
      const audioPlayer = this.$refs.audioPlayer[0];
      if (audioPlayer) {
        if (audioPlayer.paused) {
          audioPlayer.play();
          this.playState = "Pause";
        } else {
          audioPlayer.pause();
          this.playState = "Play";
        }
      }
    },
    audioProgress: function (event) {
      this.$nextTick(function () {
        const audioPlayer = this.$refs.audioPlayer[0];
        const audioPlayerTime = this.$refs.audioPlayerTime[0];
        const self = this;
        let seconds;
        let minutes;

        audioPlayer.addEventListener("loadedmetadata", function () {
          seconds = parseInt(audioPlayer.duration % 60);
          minutes = parseInt((audioPlayer.duration / 60) % 60);
          self.audioPlayerTime =
            ("0" + minutes).substr(-2) + ":" + ("0" + seconds).substr(-2);
        });

        audioPlayer.addEventListener("timeupdate", function () {
          if (audioPlayer.currentTime) {
            seconds = parseInt(audioPlayer.currentTime % 60);
            minutes = parseInt((audioPlayer.currentTime / 60) % 60);
            self.audioPlayerTime =
              ("0" + minutes).substr(-2) + ":" + ("0" + seconds).substr(-2);
          }
        });
      });
    },
    scrollTo: function () {
      //console.warn('scrollTo')
      this.$eventBus.$off("resize", this.scrollTo);
      if (
        window.routeStorage.moreInfo == true &&
        window.routeStorage.lastYPos
      ) {
        this.data.target = this.data.current = window.routeStorage.lastYPos;
        window.routeStorage.lastYPos = null;
      }
    },
    openMoreinfo: function (path, id) {
      window.routeStorage.lastYPos = window.scrollY;
      this.$router.push({ path: path, params: { id: id } });
    },
    backWork: function (event, id) {
      // Let cmd/ctrl/shift-click open the real href in a new tab or window
      if (isModifiedClick(event)) return;
      event.preventDefault();
      window.routeStorage.previousID = id;
      const scrollY = this.$route.query.scrollY;
      // scrollY is the scroll position of the grid we arrived from, so it has
      // to go back to that same grid -- the showcase, not /work
      this.$router.push({
        path: this.backWorkPath,
        query: scrollY ? { scrollY } : {},
      });
    },

    hasVolumeIndicator: function (block) {
      return !!(block.volume && block.volume.volume_indicator);
    },
    // Autoplay only works muted, so sound needs a click. Turning it on
    // restarts the video so the soundtrack is heard from the beginning.
    toggleSound: function (event, index) {
      const video = event.currentTarget.querySelector("video");
      if (!video) return;
      if (video.muted) {
        video.muted = false;
        video.currentTime = 0;
        video.play();
        this.$set(this.soundOn, index, true);
      } else {
        video.muted = true;
        this.$set(this.soundOn, index, false);
      }
    },
    carouselChange: function (id) {
      //console.log('change', id)
      //this.carouselCheckArrows(this.$refs['carousel_' + id])
    },
    // carouselClick: function(id) {
    // 	console.log('click', id)
    // 	this.carouselCheckArrows(this.$refs['carousel_' + id][0].$el)
    // },
    carouselClick: function (event) {
      // Navigation is handled by GallerySlider; once used, both arrows apply
      event.currentTarget.classList.remove("disableLeft");
      event.currentTarget.classList.remove("disableRight");
    },
  },
};
</script>

