            pointer-events: auto;
            transition: opacity 0.4s ease;

            @include breakpoint(not-phab) {
              margin-left: 40px;
            }

            // 20% smaller on mobile (text, icon and the gap between them)
            @include breakpoint(phab) {
              gap: 7px;
              font-size: 12.5px;

              .volumeIndicator__icon {
                width: 28.4px;
              }
            }

            // Theme "dark" (for light footage); icon follows via currentColor
            &--dark {
              color: black;
            }

            // Sound on: waves hold still to show it's playing
            &.is-on .volumeIndicator__wave {
              animation: none;
            }
          }

          // Only Book and Medium are loaded, so 700 is synthesised from Medium
          .volumeIndicator__text strong {
            display: block;
            font-weight: 700;
          }

          .volumeIndicator__icon {
            flex: 0 0 auto;
            // 60-unit-wide icon at the same scale as before (32px per 54 units)
            width: 35.5px;
            height: auto;
            fill: currentColor;
            overflow: visible;
          }

          // Sound waves ripple out from the speaker, the outer one following
          // the inner. Backwards fill keeps the outer hidden during its delay.
          .volumeIndicator__wave {
            transform-box: fill-box;
            transform-origin: left center;
            animation: volumeWave 1.6s ease-out infinite backwards;

            &--outer {
              animation-delay: 0.4s;
            }

            @media (prefers-reduced-motion: reduce) {
              animation: none;
            }
          }

          &.fullheight {
            video {
              width: 100%;

              @include breakpoint(not-phab) {
                height: 110vh;
              }
            }
          }
          &:not(.theme--white) {
            //padding-top: 120px !important;
          }
        }
      }

      &--quote {
        cursor: url("../assets/circle.svg") 15 10, auto;
        text-align: center;

        .wrapper {
          font-family: "Apercu-Mono";
          letter-spacing: -1px;
          max-width: 1200px;
          margin: 0 auto;

          .h5 {
            font-family: "Apercu-Mono";
            font-size: 22px;
            line-height: 1.5;
          }

          @include breakpoint(1250px) {
            .h5 {
              font-size: 20px;
            }
          }
          @include breakpoint(800px) {
            .h5 {
              font-size: 15px;
            }
            .meta {
              margin-top: 30px;
              font-size: 13px;
            }
          }
        }

        .meta {
          margin-top: 50px;
          font-size: 19px;
        }
      }

      &--iframe {
        .wrapper {
          overflow: hidden;
          position: relative;

          &:after {
            content: "";
            display: block;
            width: 100%;
            height: 100%;
            padding-bottom: 55%;
          }
        }
        iframe {
          position: absolute;
          width: 100%;
          height: 100%;
          overflow: hidden;
        }
      }
    }
  }

  .backtowork {
    text-align: center;
    padding: 120px 0;

    a:hover {
      cursor: url("../assets/plus.svg") 15 10, auto;
    }
    @include breakpoint(phab) {
      padding: 50px 0;
    }
  }

  .video__inner {
    position: relative;
    .video__playButton {
      position: absolute;
      top: 50%;
      left: 50%;
      transform: translate(-50%, -50%);
      z-index: 9999999;
      background: url("../assets/play-text.png") no-repeat;
      background-size: contain;
      background-position: center;
      z-index: 2;
      width: 40px;
      height: 22px;
      border: none;
      outline: none;
      appearance: none;
    }
  }
  // &__next {
