<template>
  <div
    class="GallerySlider"
    ref="viewport"
    @pointerdown="dragStart"
    @pointermove="dragMove"
    @pointerup="dragEnd"
    @pointercancel="dragCancel"
    @click="onClick"
  >
    <!-- Invisible element sized by the image_width CSS; its width is the
         slot a landscape image fills, which sets the gallery height -->
    <div class="GallerySlider__frame" ref="frame"></div>

    <div
      class="GallerySlider__track"
      :class="{ 'is-dragging': dragging }"
      :style="{
        height: height + 'px',
        transform: 'translate3d(' + (offset + dragOffset) + 'px,0,0)',
      }"
    >
      <div
        v-for="(item, index) in images"
        :key="index"
        ref="slides"
        :class="[
          'GallerySlider__slide',
          index === current ? 'is-active' : '',
        ]"
        :style="{ width: height * ratio(index) + 'px' }"
      >
        <img
          :src="item.url"
          :alt="imageAlt(item, altFallback)"
          draggable="false"
          @load="onImageLoad($event, index)"
        />
      </div>
    </div>

    <div v-if="images.length > 1" class="GallerySlider__dots">
      <span
        v-for="(item, index) in images"
        :key="index"
        :class="[
          'GallerySlider__dot',
          index === current ? 'GallerySlider__dot--active' : '',
        ]"
      ></span>
    </div>
  </div>
</template>

<script>
import { imageAlt } from "@/utils";
const SWIPE_THRESHOLD = 50;

export default {
  props: {
    images: {
      type: Array,
      default: () => [],
    },
    // Alt text for images with none in the media library (e.g. "Client —
    // Project title" from the case study)
    altFallback: {
      type: String,
      default: "",
    },
  },
  data() {
    return {
      current: 0,
      height: 0,
      offset: 0,
      dragging: false,
      dragOffset: 0,
      dragStartX: 0,
      wasDragged: false,
      // Natural sizes read from the <img> when ACF doesn't provide them
      loadedRatios: {},
    };
  },
  watch: {
    images: function () {
      this.current = 0;
      this.$nextTick(this.layout);
    },
  },
  mounted: function () {
    window.addEventListener("resize", this.layout);
    this.layout();
  },
  beforeDestroy: function () {
    window.removeEventListener("resize", this.layout);
  },
  methods: {
    imageAlt,
    ratio: function (index) {
      if (this.loadedRatios[index]) return this.loadedRatios[index];
      const item = this.images[index];
      if (item && item.width && item.height) return item.width / item.height;
      return 16 / 9;
    },
    onImageLoad: function (event, index) {
      const img = event.target;
      if (!img.naturalWidth || !img.naturalHeight) return;
      const r = img.naturalWidth / img.naturalHeight;
      if (Math.abs(r - this.ratio(index)) > 0.01) {
        this.$set(this.loadedRatios, index, r);
        this.layout();
      }
    },
    layout: function () {
      if (!this.$refs.frame || !this.images.length) return;
      // Height is what the widest image would be when filling the slot, so
      // nothing ever gets wider than the slot and every image shares it
      let widest = 0;
      for (let i = 0; i < this.images.length; i++) {
        widest = Math.max(widest, this.ratio(i));
      }
      this.height = Math.round(this.$refs.frame.offsetWidth / widest);
      this.$nextTick(this.position);
    },
    position: function () {
      const slides = this.$refs.slides;
      if (!slides || !slides[this.current]) return;
      const slide = slides[this.current];
      // Centre the active slide in the viewport
      this.offset =
        this.$refs.viewport.offsetWidth / 2 -
        (slide.offsetLeft + slide.offsetWidth / 2);
    },
    goTo: function (index) {
      const next = Math.max(0, Math.min(this.images.length - 1, index));
      if (next === this.current) return;
      this.current = next;
      this.position();
      this.$emit("change", next);
    },
    next: function () {
      this.goTo(this.current + 1);
    },
    prev: function () {
      this.goTo(this.current - 1);
    },
    dragStart: function (event) {
      if (event.pointerType === "mouse" && event.button !== 0) return;
      // Keep receiving moves/up if the pointer leaves the gallery mid-drag
      if (event.currentTarget.setPointerCapture) {
        event.currentTarget.setPointerCapture(event.pointerId);
      }
      this.dragging = true;
      this.wasDragged = false;
      this.dragStartX = event.clientX;
      this.dragOffset = 0;
    },
    dragMove: function (event) {
      if (!this.dragging) return;
      this.dragOffset = event.clientX - this.dragStartX;
      if (Math.abs(this.dragOffset) > 5) this.wasDragged = true;
    },
    dragEnd: function () {
      if (!this.dragging) return;
      const delta = this.dragOffset;
      this.dragging = false;
      this.dragOffset = 0;
      if (delta <= -SWIPE_THRESHOLD) this.next();
      else if (delta >= SWIPE_THRESHOLD) this.prev();
    },
    dragCancel: function () {
      this.dragging = false;
      this.dragOffset = 0;
    },
    onClick: function (event) {
      if (this.wasDragged) {
        this.wasDragged = false;
        return;
      }
      // Left half of the screen goes back, right half goes forward
      if (event.clientX < window.innerWidth / 2) this.prev();
      else this.next();
    },
  },
};
</script>

<style lang="scss">
.GallerySlider {
  position: relative;
  width: 100%;
  overflow: hidden;
  touch-action: pan-y;
  user-select: none;

  &__frame {
    height: 0;
    margin: 0 auto;
    width: 100%;
  }

  &__track {
    display: flex;
    align-items: flex-start;
    transition: transform 0.5s ease;
    will-change: transform;

    &.is-dragging {
      transition: none;
    }
  }

  &__slide {
    flex: 0 0 auto;
    height: 100%;
    margin-right: 50px;

    &:last-child {
      margin-right: 0;
    }

    img {
      display: block;
      width: 100%;
      height: 100%;
      max-width: none;
      pointer-events: none;
    }
  }

  &__dots {
    display: none;
    text-align: center;
    padding-top: 20px;
    line-height: 0;

    @include breakpoint(phab) {
      display: block;
    }
  }

  &__dot {
    display: inline-block;
    width: 4px;
    height: 4px;
    margin: 3px;
    border-radius: 50%;
    background-color: #dadada;
    border: 1px solid #cccccc;

    &--active {
      border-color: #9d9c9c;
      background-color: #9d9c9c;
    }
  }
}
</style>



