<template>
  <transition appear v-on:appear="enter" v-on:leave="leave" v-bind:css="false">
    <div class="EmotionPost flyout">
      <div class="flyout-transform js-transform">
        <div class="flyout-transform js-transform theme--white">
          <div class="Section-bounding js-bounding">
            <div class="page__container">
              <div class="page__inner theme--white">
                <div class="flyout__hero u-relative js-copy">
                  <div class="flyout__close">
                    <a
                      href="/emotion-lab"
                      @click="routerBack"
                      aria-label="Back to Emotion Lab"
                      class="close js-stagger"
                      ><img src="../assets/arrow-left.svg" alt=""
                    /></a>
                  </div>
                </div>
                <div class="flyout__copy js-copy js-stagger">
                  <div class="EmotionPost__intro">
                    <div class="image image--3x2 js-stagger">
                      <div
                        :class="[
                          'image-src',
                          'u-cover',
                          page.acf[0].poster_video ? 'video' : '',
                        ]"
                        :style="{
                          backgroundImage:
                            'url(' + page.acf[0].poster_image.url + ')',
                        }"
                      >
                        <video
                          v-if="page.acf[0].poster_video"
                          autoplay
                          loop
                          playsinline
                        >
                          <source
                            :src="page.acf[0].poster_video"
                            type="video/mp4"
                          />
                        </video>
                      </div>
                    </div>

                    <!-- The page's H1, styled as before via .h3 -->
                    <h1 class="h3 EmotionPost__title js-stagger">
                      {{ page.acf[0].sub_title }}<br />
                      {{ page.post_title }}
                    </h1>

                    <div class="EmotionPost__sub js-stagger">
                      <div class="EmotionPost__author">{{ page.author }}</div>
                      <div class="EmotionPost__meta">
                        <span class="u-capitalize">{{ page.type }} | </span>

                        <div class="u-inline-block">
                          <Share :backURL="$route.fullPath"></Share>
                        </div>
                      </div>
                    </div>
                  </div>
                  <div class="EmotionPost__body">
                    <div class="h6" v-html="page.post_content"></div>
                  </div>
                </div>
              </div>
            </div>
          </div>
          <Footer></Footer>
        </div>
      </div>
    </div>
  </transition>
</template>

<script>
import size from "size";
import sniffer from "sniffer";
import Scroll from "@/components/scroll";
import Footer from "@/components/Footer";
import Share from "@/components/modules/Share";
import { isModifiedClick } from "@/utils";

export default {
  name: "EmotionPost",
  extends: Scroll,
  components: {
    Footer,
    Share,
  },
  data() {
    return {
      page: [],
    };
  },
  created: function () {
    const $this = this;
    this.$root.$data.content.emotionlab.forEach(function (item) {
      if (item.post_name == $this.$route.params.id) {
        $this.page = item;
      }
    });
    if (!this.page) {
      console.log("No emotion lab post found!");
    }
    this.flyout = true;
    // Title and meta are set by src/seo.js
  },
  mounted() {
    this.$eventBus.$emit("cursor:color", "black");
    this.$eventBus.$emit("updateScroll");
    this.$eventBus.$emit("changeTheme", "light");
    this.init();
    this.animateIn();
  },
  beforeDestroy: function () {
    this.destroy();
  },
  destroyed: function () {
    //this.$eventBus.$emit('changeTheme', 'dark')
  },
  methods: {
    getUIExtend: function () {
      this.transform = this.$el.querySelectorAll(".js-transform");
      this.stagger = this.$el.querySelectorAll(".js-stagger");
    },
    enter: function (el, done) {
      //console.log('EmotionPost:enter', el)
      TweenMax.set(this.$el, {
        position: "fixed",
        top: 0,
        left: 0,
        width: "100%",
        zIndex: 5,
      });
      done();
    },
    animateIn: function () {
      //console.log('EmotionPost:animateIn')
      const tl = new TimelineMax({ paused: true });
      tl.set(this.$el, { position: "relative" });
      tl.staggerFromTo(
        this.transform,
        1,
        {
          cycle: {
            x: [-size.width, size.width],
          },
        },
        {
          x: 0,
          ease: Quint.easeInOut,
        },
        0,
        0
      );
      tl.staggerFromTo(
        this.stagger,
        0.65,
        {
          x: 20,
          autoAlpha: 0,
        },
        {
          x: 0,
          autoAlpha: 1,
          ease: Quint.easeOut,
        },
        0.1,
        0.35
      );
      tl.add(() => this.$eventBus.$emit("ready"), 1);
      tl.restart();
    },
    leave: function (el, done) {
      //console.log('EmotionPost:leave', el)
      const tl = new TimelineMax({ paused: true, onComplete: done });
      tl.set(this.$el, {
        position: "fixed",
        top: 0,
        left: 0,
        right: 0,
        width: "100%",
      });
      tl.staggerTo(
        this.transform,
        1,
        {
          cycle: {
            x: [size.width, -size.width],
          },
          ease: Quint.easeInOut,
        },
        0,
        0
      );
      tl.staggerTo(
        this.stagger,
        0.4,
        {
          autoAlpha: 0,
          ease: Linear.easeNone,
        },
        0,
        0
      );
      tl.restart();
    },
    resize: function () {},
    routerBack: function (event) {
      // Let cmd/ctrl/shift-click open the real href in a new tab or window
      if (isModifiedClick(event)) return;
      event.preventDefault();
      window.routeStorage.moreInfo = true;
      this.$router.push({ path: "/emotion-lab" });
    },
  },
};
</script>

<!-- Add "scoped" attribute to limit CSS to this component only -->
<style scoped lang="scss">
.EmotionPost {
  .js-device-only {
    display: none;
    .is-device & {
      display: block;
    }
  }
  .js-desktop-only {
    display: none;
    .is-desktop & {
      display: block;
    }
  }
  .flyout__hero {
    margin-bottom: 50px;

    @include breakpoint(phab) {
      margin-bottom: 40px;
    }
    .image {
      margin-bottom: 40px;
    }
  }

  &__intro {
    margin-bottom: 80px;
    .image {
      width: 100%;
      &.image {
        background: none !important;
      }
      video {
        width: 100%;
        height: 100%;
        object-fit: cover;
      }
      @include breakpoint(phab) {
        margin-bottom: 50px;
      }
    }

    &__copy {
      margin-top: 80px;
    }
  }

  &__title {
    margin-top: 50px;
  }

  &__sub {
    margin-top: 30px;
    @include breakpoint(phab) {
      font-size: 13px;
      /deep/ {
        .shareList {
          margin-top: 0 !important;
        }
        p,
        .shareList li a {
          font-size: 13px !important;
        }
      }
    }
  }

  &__meta {
    font-family: "Apercu-Mono";
    letter-spacing: -1px;
    white-space: nowrap;
    .Share {
      display: inline;
      /deep/ {
        .shareToggle {
          display: inline-block;
          margin-right: 20px;
          p {
            margin: 0;
          }
        }
        .shareList {
          display: inline-block;
          margin: 0;
          position: relative;
          top: -10px;
        }
        .shareList,
        .shareList li {
          display: inline-block;
        }
      }
    }
  }

  &__author {
    font-family: "Apercu-Mono";
    letter-spacing: -1px;
    margin-bottom: 5px;
  }

  &__body {
    @include breakpoint(not-phab) {
      max-width: 95%;
    }
  }

  &__footer {
    margin-top: 150px;
  }
}
</style>



