<template>
  <div
    class="Home__posts tw-bg-white tw-text-black tw-py-20 lg:tw-py-32 theme--white"
    ref="posts"
  >
    <div class="page__container">
      <div
        class="tw-flex tw-justify-between tw-items-center tw-mb-12 lg:tw-mb-28"
      >
        <h3 class="Home__posts__title sectionTitle">Latest News</h3>
        <div v-if="hasMorePages" class="latestNews__arrows">
          <button
            type="button"
            class="latestNews__arrow latestNews__arrow--prev cursor-plus"
            aria-label="Previous news stories"
            :disabled="atStart"
            @click="prevPage"
          >
            <img
              src="../../assets/arrow-right2.svg"
              class="tw-w-[23px] tw-h-auto"
              alt=""
            />
          </button>
          <button
            type="button"
            class="latestNews__arrow latestNews__arrow--next cursor-plus"
            aria-label="Next news stories"
            :disabled="atEnd"
            @click="nextPage"
          >
            <img
              src="../../assets/arrow-right2.svg"
              class="tw-w-[23px] tw-h-auto"
              alt=""
            />
          </button>
        </div>
      </div>

      <carousel
        ref="carousel"
        class="latestNews"
        :per-page="perPage"
        :navigation-enabled="false"
        @page-change="currentPage = $event"
      >
        <slide
          v-for="post in sortedPosts"
          :key="post.ID"
          class="latestNews__item"
        >
          <img
            :src="post.acf[0].image.url"
            :alt="imageAlt(post.acf[0].image, post.post_title)"
            class="tw-w-full tw-aspect-[17/9] tw-object-cover tw-object-center tw-mb-8 lg:tw-mb-16"
          />
          <div class="tw-max-w-[90%]">
            <p class="tw-mb-6 tw-font-bold">{{ post.post_title }}</p>
            <p class="tw-whitespace-pre-line" v-html="post.post_content"></p>
          </div>
        </slide>
      </carousel>
    </div>
  </div>
</template>

<script>
import { Carousel, Slide } from "vue-carousel";
import { imageAlt } from "@/utils";

// 4 per page from lg up, 2 on tablet, and 1 (with the next peeking in)
// on phones, matching the phab breakpoint in the styles below
const DESKTOP_QUERY = "(min-width: 1024px)";
const MOBILE_QUERY = "(max-width: 600px)";

export default {
  components: {
    Carousel,
    Slide,
  },
  props: {
    // Keyed by post slug, not an array
    posts: {
      type: Object,
      default: () => ({}),
    },
  },
  data() {
    return {
      isDesktop: true,
      isMobile: false,
      currentPage: 0,
    };
  },
  computed: {
    // Newest first. WordPress orders posts by menu_order, which is 0 for
    // every post, so they arrive oldest first; ID breaks ties between posts
    // with the same timestamp
    sortedPosts() {
      return Object.values(this.posts).sort(
        (a, b) => b.post_date.localeCompare(a.post_date) || b.ID - a.ID,
      );
    },
    perPage() {
      if (this.isDesktop) return 4;
      return this.isMobile ? 1 : 2;
    },
    pageCount() {
      return Math.ceil(this.sortedPosts.length / this.perPage);
    },
    hasMorePages() {
      return this.pageCount > 1;
    },
    atStart() {
      return this.currentPage <= 0;
    },
    atEnd() {
      return this.currentPage >= this.pageCount - 1;
    },
  },
  mounted() {
    this.desktopMql = window.matchMedia(DESKTOP_QUERY);
    this.mobileMql = window.matchMedia(MOBILE_QUERY);
    this.onBreakpoint = () => {
      this.isDesktop = this.desktopMql.matches;
      this.isMobile = this.mobileMql.matches;
    };
    this.onBreakpoint();
    this.desktopMql.addListener(this.onBreakpoint);
    this.mobileMql.addListener(this.onBreakpoint);
  },
  beforeDestroy() {
    if (!this.desktopMql) return;
    this.desktopMql.removeListener(this.onBreakpoint);
    this.mobileMql.removeListener(this.onBreakpoint);
  },
  methods: {
    imageAlt,
    // Step back a page; the arrow is disabled on the first one
    prevPage() {
      const carousel = this.$refs.carousel;
      if (!carousel || this.atStart) return;
      carousel.goToPage(this.currentPage - 1);
    },
    // Step forward a page; the arrow is disabled on the last one
    nextPage() {
      const carousel = this.$refs.carousel;
      if (!carousel || this.atEnd) return;
      carousel.goToPage(this.currentPage + 1);
    },
  },
};
</script>

<style scoped lang="scss">
// Gutter between slides; the negative margin keeps the last visible
// item flush with the container edge, as the grid was
.latestNews {
  margin-right: -16px;

  // Phones: one story at a time with the next peeking in. The carousel is
  // narrower than the container and doesn't clip its slides, so the next
  // one shows to its right; the section clips at the screen edge instead.
  @include breakpoint(phab) {
    width: 88%;
    margin-right: 0;

    /deep/ .VueCarousel-wrapper {
      overflow: visible;
    }
  }
}

.Home__posts {
  @include breakpoint(phab) {
    overflow: hidden;
  }
}

.latestNews__item {
  padding-right: 16px;
}

.latestNews__arrows {
  display: flex;
  align-items: center;
}

.latestNews__arrow {
  background: none;
  border: 0;
  padding: 8px;
  transition: transform 0.3s ease-in-out, opacity 0.3s ease-in-out;

  // Flush with the container edge, as the single arrow was
  &--next {
    padding-right: 0;
  }

  // Same artwork as next, mirrored on the image so the button's own
  // transform stays free for the hover nudge
  &--prev img {
    transform: scaleX(-1);
  }

  @include breakpoint(not-phab) {
    &--next:hover:not(:disabled) {
      transform: translateX(6px);
    }

    &--prev:hover:not(:disabled) {
      transform: translateX(-6px);
    }
  }

  // First page (prev) or last page (next) reached
  &:disabled {
    opacity: 0.3;
    cursor: default;
  }
}
</style>



