<template>
  <div class="AudioPlayer">
    <h4>{{ title }}</h4>
    <div class="audioPlayerTime u-inline-block">
      <p>{{ time }}</p>
    </div>
    <p class="audioPlayerAction u-inline-block" v-on:click="toggle">
      {{ playState }}
    </p>
    <audio
      ref="audio"
      @loadedmetadata="onMetadata"
      @timeupdate="onTimeUpdate"
      @play="onPlay"
      @pause="playState = 'Play'"
    >
      <source :src="src" type="audio/mpeg" />
    </audio>
  </div>
</template>

<script>
function formatTime(value) {
  const seconds = parseInt(value % 60);
  const minutes = parseInt((value / 60) % 60);
  return ("0" + minutes).substr(-2) + ":" + ("0" + seconds).substr(-2);
}

export default {
  props: {
    title: {
      type: String,
      default: "",
    },
    src: {
      type: String,
      required: true,
    },
  },
  data() {
    return {
      time: null,
      playState: "Play",
    };
  },
  mounted: function () {
    // Only one track in a collection plays at a time
    this.$eventBus.$on("audio:play", this.pauseOthers);
  },
  beforeDestroy: function () {
    this.$eventBus.$off("audio:play", this.pauseOthers);
  },
  methods: {
    toggle: function () {
      const audio = this.$refs.audio;
      if (audio.paused) {
        audio.play();
      } else {
        audio.pause();
      }
    },
    onMetadata: function () {
      this.time = formatTime(this.$refs.audio.duration);
    },
    onTimeUpdate: function () {
      const audio = this.$refs.audio;
      if (audio.currentTime) this.time = formatTime(audio.currentTime);
    },
    onPlay: function () {
      this.playState = "Pause";
      this.$eventBus.$emit("audio:play", this);
    },
    pauseOthers: function (player) {
      if (player !== this && !this.$refs.audio.paused) this.$refs.audio.pause();
    },
  },
};
</script>



