<template>
  <div :class="'Footer tw-bg-[#d8d4d3] Footer--' + this.theme">
    <div class="Footer__wrapper">
      <div class="page__container">
        <div class="Footer__inner">
          <div
            class="tw-grid tw-grid-cols-1 lg:tw-grid-cols-2 tw-gap-0 lg:tw-gap-40"
          >
            <div class="">
              <div class="Footer__copy">
                <div class="tw-flex tw-flex-col tw-gap-12 lg:tw-gap-24">
                  <h3 class="sectionTitle">Let's talk</h3>
                  <h3
                    class="tw-text-[32px] lg:tw-text-[55px] tw-leading-[1] font--bold"
                  >
                    <a href="mailto:hello@loaf.agency" class="tw-no-underline"
                      >hello@loaf.agency</a
                    ><br /><a href="tel:+441616729844" class="tw-no-underline"
                      >+44 (0)161 672 9844</a
                    >
                  </h3>
                  <div>
                    <p class="tw-text-[18px] lg:tw-text-[26px] tw-mb-10">
                      Colony, Jactin House, 24 Hood Street<br />Ancoats,
                      Manchester M4 6WX
                    </p>
                    <a
                      href="https://maps.app.goo.gl/ePk8dEjitZgEEsSB9"
                      target="_blank"
                      class="hover hover--link tw-uppercase tw-underline hover:tw-no-underline tw-text-[18px] lg:tw-text-[19px]"
                      >Google Maps</a
                    >
                  </div>
                </div>
                <moreThanCreative
                  classes="tw-w-[200px] lg:tw-w-[277px] tw-mt-20 lg:tw-mt-40 tw-hidden lg:tw-block"
                  :fill="theme === 'dark' ? 'white' : 'black'"
                />
              </div>
            </div>
            <div class="lg:tw-pl-28 tw-flex tw-flex-col tw-justify-between">
              <div class="tw-flex tw-flex-col lg:tw-gap-24">
                <h3 class="sectionTitle lg:tw-mb-1">&nbsp;</h3>
                <div class="Footer__social tw-leading-[1.1]">
                  <div class="Footer__social__item tw-flex tw-gap-3">
                    <a class="" href="https://instagram.com/loafcreative"
                      >Instagram</a
                    >
                    <img src="../assets/arrow-right2.svg" class="tw-w-[23px]" alt="" />
                  </div>
                  <div class="Footer__social__item tw-flex tw-gap-3">
                    <a
                      class=""
                      href="https://www.linkedin.com/company/loaf-creative/"
                      >LinkedIn</a
                    >
                    <img src="../assets/arrow-right2.svg" class="tw-w-[23px]" alt="" />
                  </div>
                </div>
              </div>

              <div
                class="tw-flex tw-flex-col tw-gap-2 tw-text-[14px] tw-mt-20 lg:tw-mt-0"
              >
                <div>&copy; {{ currentYear }}</div>
                <div>Company No. 06431134</div>
                <div>
                  <a href="/privacy-policy" class="hover hover--link"
                    >Privacy Policy & Terms of Service</a
                  >
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import size from "size";
import sniffer from "sniffer";
import SignupTrigger from "@/components/modules/SignupTrigger";
import moreThanCreative from "@/assets/more-than-creative.vue";

export default {
  name: "Footer",
  components: {
    SignupTrigger,
    moreThanCreative,
  },
  data() {
    return {
      theme: "light",
      form: {
        name: "",
      },
    };
  },
  props: {
    nextUrl: {
      type: String,
      required: false,
    },
  },
  computed: {
    currentYear: function () {
      return new Date().getFullYear();
    },
  },
  created() {
    this.$eventBus.$on("changeFooterTheme", this.changeTheme);
  },
  mounted() {
    this.$eventBus.$on("resize", this.onResize);
  },
  methods: {
    scrollToTop() {
      window.scroll({
        top: 0,
        left: 0,
        behavior: "smooth",
      });
    },
    onResize() {
      if (
        sniffer.isDesktop &&
        !document.documentElement.classList.contains(
          "disable-safari-animations"
        )
      ) {
        this.$el.style.height = `${window.innerHeight}px`;
      }
    },
    changeTheme(theme) {
      //console.log('change theme')
      this.theme = theme;
    },
  },
};
</script>

<!-- Add "scoped" attribute to limit CSS to this component only -->
<style lang="scss">
.Footer {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  width: 100%;
  z-index: 1;

  a:hover {
    cursor: url("../assets/plus.svg") 15 10, auto;
  }
  .is-device &,
  .is-safari.disable-safari-animations & {
    position: relative;
    height: auto;
    top: auto;
    left: auto;
    right: auto;
    bottom: auto;
  }

  &__wrapper {
    padding: 150px 0 50px;

    .is-desktop:not(.disable-safari-animations) & {
      position: absolute;
      left: 0;
      bottom: 60px;
      width: 100%;
      padding: 0;
    }
  }

  &__copy {
    a {
      transition: opacity 0.5s ease;
      &:hover {
        opacity: 0.5;
      }
    }
  }

  &__social {
    &__item {
      transition: opacity 0.5s ease;
      img {
        transition: all 0.5s ease;
      }
      &:hover {
        opacity: 0.5;
        img {
          transform: translateX(5px);
        }
      }
    }
    a {
      font-size: 38px;
      text-decoration: none;
      @include breakpoint(phab) {
        font-size: 25px;
      }

      &:after {
        display: none;
      }
    }
  }

  &__inner {
    position: relative;
    width: 100%;
    max-width: 1510px;
    letter-spacing: -0.03em;
    font-weight: 500;

    @include breakpoint(tab) {
      padding-right: 20px;
    }
  }
  &__top {
    position: absolute;
    top: -100px;
    left: 5px;

    @include breakpoint(phab) {
      top: -80px;
    }
  }

  &--right {
    width: 100%;
    max-width: 350px;
    align-self: flex-end;
  }
  &--left {
  }

  .page__container {
    padding-top: 0;
    padding-bottom: 0;
  }

  &--light {
    //theme
    background-color: #d8d4d3;
    color: black;
    cursor: url("../assets/circle.svg") 15 10, auto;

    a {
      color: black;
      cursor: url("../assets/circle.svg") 15 10, auto;
    }
  }
  &--dark {
    a {
      color: white;
    }
  }

  p {
  }

  &__start {
    margin-bottom: 40px;

    @include breakpoint(651px, "min-width") {
      margin-bottom: 60px;
    }

    @include breakpoint(730px, "min-width") {
      margin-bottom: 79px;
    }

    @include breakpoint(830px, "min-width") {
      margin-bottom: 60px;
    }

    @include breakpoint(901px, "min-width") {
      margin-bottom: 40px;
    }

    @include breakpoint(931px, "min-width") {
      margin-bottom: 40px;
    }

    @include breakpoint(1281px, "min-width") {
      margin-bottom: 45px;
    }
  }

  &__bi {
    height: 88px;
    display: flex;

    img {
      align-self: flex-end;
      width: 167px;
    }

    @include breakpoint(phab) {
      img {
        width: 140px;
      }
      .u-fit-w {
        align-self: flex-end;
        text-align: right;
        p {
          font-family: "Circular";
          letter-spacing: 0px;
          font-size: 10px;
          margin: 0;
        }
      }
    }
  }

  &__legal {
    display: flex;
    height: 90px;

    p {
      align-self: flex-end;
      font-size: 14px !important;
      margin: 0;
    }
  }

  &__viewall {
    margin-top: 100px;
    display: block;

    a {
      text-decoration: none;
    }
  }

  .Project__next {
    padding: 50px 0;
    position: relative;
    //margin-top: 130px;

    .u-flex {
      justify-content: space-between;
      align-items: center;
      @include fontSize(35px);
      line-height: 1;
      padding: 0 30px;

      a {
        text-decoration: none;
        color: white;
      }

      img {
        display: inline-block;
        vertical-align: middle;
      }

      :first-child img {
        margin-right: 7vw;
      }
      :last-child img {
        margin-left: 7vw;
      }

      @include breakpoint(1000px) {
        font-size: 20px;

        :first-child img {
          margin-right: 5vw;
        }
        :last-child img {
          margin-left: 5vw;
        }
      }
    }

    @include breakpoint(phab) {
      padding: 60px 0;

      .u-flex {
        font-size: 16px;
        padding: 10px;
      }
    }
  }
}
</style>



