<template>
  <transition appear v-on:appear="enter" v-on:leave="leave" v-bind:css="false">
    <div class="Emotion page">
      <div class="Emotion-transform js-transform">
        <div class="Emotion-transform js-transform theme--white">
          <div class="Section-bounding js-bounding">
            <div class="page__container">
              <div class="page__hero">
                <div class="page__hero__wrap !tw-pt-[150px] lg:!tw-pt-[350px]">
                  <div class="js-in tw-max-w-[1000px] max-lg:tw-pr-4">
                    <h1
                      class="tw-text-[30px] lg:tw-text-[60px] tw-font-[500] tw-leading-[1.1] lg:tw-leading-[1.05]"
                      v-html="page.acf[0].intro"
                    ></h1>
                  </div>
                </div>
              </div>
              <div class="Emotion__posts">
                <div class="posts u-flex--not-tab js-posts">
                  <div
                    v-for="(item, index) in items"
                    :class="'js-el post post--format-' + item.index"
                  >
                    <a
                      :href="'/emotion-lab/' + item.post_name"
                      @click="openMoreinfo($event, '/emotion-lab/' + item.post_name)"
                      class="post__wrapper"
                    >
                      <div class="post__poster image js-poster">
                        <div
                          class="image-src u-cover"
                          :style="{
                            backgroundImage:
                              'url(' + item.acf[0].poster_image.url + ')',
                          }"
                        >
                          <div v-if="item.acf[0].poster_video">
                            <video
                              disableRemotePlayback
                              autoplay
                              loop
                              muted
                              playsinline
                            >
                              <source
                                :src="item.acf[0].poster_video"
                                type="video/mp4"
                              />
                            </video>
                          </div>
                        </div>
                      </div>
                      <div class="post__desc">
                        <h3 class="post__title js-stagger tw-font-[400]">
                          <span class="hover hover--multiline-link">{{
                            item.acf[0].sub_title
                          }}</span
                          ><br />
                          <span class="tw-pt-2 tw-block">
                            {{ item.post_title }}</span
                          >
                        </h3>
                        <p class="post__meta js-stagger tw-font-[400]">
                          <span class="u-uppercase">{{ item.type }}</span>
                        </p>
                      </div>
                    </a>
                  </div>
                </div>
              </div>
            </div>
          </div>
          <Footer></Footer>
        </div>
      </div>
    </div>
  </transition>
</template>

<script>
const sniffer = require("sniffer");

import size from "size";
import Scroll from "@/components/scroll";
import Footer from "@/components/Footer";
import { isModifiedClick } from "@/utils";
import GSAPScrollMagic from "../plugins/gsap-scrollmagic";

export default {
  name: "Emotion",
  extends: Scroll,
  components: {
    Footer,
  },
  data() {
    return {
      page: [],
      items: [],
      infoOpen: false,
      infoHeight: 0,
    };
  },
  created: function () {
    this.options.autoResize = true;
    this.options.threshold = 0;
    this.page = this.$root.$data.content.pages.emotionlab;
    this.items = this.$root.$data.content.emotionlab;
    let index = 0;
    this.items.forEach(function (item) {
      item.index = index;
      index++;
      if (index > 16) index = 0;
    });
  },
  mounted() {
    this.$eventBus.$emit("changeTheme", "light");
    this.init();
    this.$nextTick(() => this.$eventBus.$emit("ready"));
    this.$eventBus.$on("resize", this.scrollTo);
  },
  beforeDestroy: function () {
    this.destroy();
  },
  destroyed: function () {
    // this.$eventBus.$emit("changeTheme", "dark");
  },
  methods: {
    getUIExtend: function () {
      this.transform = this.$el.querySelectorAll(".js-transform");
      this.in = this.$el.querySelectorAll(".js-in");
      this.posts = this.$el.querySelector(".js-posts");
    },
    enter: function (el, done) {
      if (!sniffer.isDevice && !sniffer.isSafari) {
        TweenMax.set(this.$el, {
          position: "fixed",
          top: 0,
          left: 0,
          width: "100%",
        });
        done();
      }
    },
    leave: function (el, done) {
      //console.log('Emotion:leave', this.transform)
      const tl = new TimelineMax({ paused: true, onComplete: done });
      tl.set(this.$el, {
        position: "fixed",
        top: 0,
        left: 0,
        right: 0,
        width: "100%",
      });
      tl.staggerTo(
        this.transform,
        1,
        {
          cycle: {
            x: [size.width, -size.width],
          },
          ease: Quint.easeInOut,
        },
        0,
        0
      );
      tl.restart();
    },
    rAFExtend: function () {
      //const current = Math.round(Math.abs(this.data.current))
      //console.log(current)
      // if (current <= this.data.max - size.height - 65) {
      // 	this.header.classList.remove('theme--light')
      // 	this.header.classList.add('theme--dark')
      // } else {
      // 	this.header.classList.remove('theme--dark')
      // 	this.header.classList.add('theme--light')
      // }
    },
    inView: function (el, data, direction) {
      if (data.state) return;
      data.state = true;
      el.classList.add("in-viewport");
      if (sniffer.isDevice) return;
      const poster = el.querySelector(".js-poster");
      const stagger = el.querySelectorAll(".js-stagger");
      const delay = Math.random() * 0.25;
      const unit = 200;
      TweenMax.fromTo(
        poster,
        1,
        {
          y: direction === "top" ? -unit : unit,
          autoAlpha: 0,
        },
        {
          y: 0,
          autoAlpha: 1,
          delay: delay,
          ease: Quint.easeOut,
        }
      );
      TweenMax.staggerFromTo(
        stagger,
        1,
        {
          x: 15,
          autoAlpha: 0,
        },
        {
          x: 0,
          autoAlpha: 1,
          delay: delay + 0.5,
          ease: Quint.easeOut,
        },
        0.15
      );
    },
    animateIn: function () {
      const tl = new TimelineMax({ paused: true });
      tl.staggerFromTo(
        this.in,
        1,
        {
          x: 20,
          autoAlpha: 0,
        },
        {
          x: 0,
          autoAlpha: 1,
          ease: Quint.easeOut,
        },
        0.15,
        0
      );
      tl.fromTo(
        this.posts,
        1,
        {
          y: 100,
          autoAlpha: 0,
        },
        {
          y: 0,
          autoAlpha: 1,
          ease: Quint.easeOut,
        },
        0.25
      );
      tl.add(() => this.$eventBus.$emit("cursor:color", "black"), 0);
      tl.add(() => this.$eventBus.$emit("ready"), 1);
      tl.restart();
    },
    resize: function () {
      const { width, height } = size;
    },
    scrollTo: function () {
      this.$eventBus.$off("resize", this.scrollTo);
      if (
        window.routeStorage.moreInfo == true &&
        window.routeStorage.lastYPos
      ) {
        this.data.target = this.data.current = window.routeStorage.lastYPos;
        window.routeStorage.lastYPos = null;
      }
    },
    openMoreinfo: function (event, path) {
      // Let cmd/ctrl/shift-click open the real href in a new tab or window
      if (isModifiedClick(event)) return;
      event.preventDefault();
      window.routeStorage.lastYPos = window.scrollY;
      this.$router.push({ path: path, params: {} });
    },
  },
};
</script>

<!-- Add "scoped" attribute to limit CSS to this component only -->
