    min-height: 0;
    padding-bottom: 250px;
    @include breakpoint(phab) {
      padding-bottom: 100px;
    }
  }

  &__learn {
    margin-top: 80px;
    font-family: "Apercu-Mono";
    font-size: 14px;
    letter-spacing: -1px;
    &__content {
      max-width: 1000px;
      overflow: hidden;
    }
  }

  .posts {
    flex-wrap: wrap;
    width: calc(100% + 35px);
    margin-right: -35px;

    @include breakpoint(tab) {
      width: 100%;
      margin: 0;
    }

    .post {
      flex: 1 0 33%;
      padding-right: 35px;
      text-decoration: none;
      a {
        text-decoration: none;
      }
      &__wrapper {
        display: block;
      }
      &__desc {
        padding-left: 12px;
        margin-top: 24px;
        @include breakpoint(tab) {
          padding-left: 0;
        }
      }
      &__title {
        font-size: scaled-rem(34);
        .hover:after {
          bottom: 3px;
          height: 2px;
        }
      }
      &__meta {
        font-family: "Apercu-Mono";
        font-size: 13px;
        letter-spacing: -1px;
        margin-top: 50px;
      }

      &__poster {
        overflow: hidden;
        video {
          position: absolute;
          width: 100%;
          height: 100%;
          object-fit: cover;
        }
      }
      &--format {
        &-0 {
          margin-bottom: 50px;
          flex-basis: 33%;
          flex-grow: 0;
          @media only screen and (max-width: 1024px) {
            flex-basis: 55%;
          }
          .image {
            margin-left: -60px;
            &:before {
              padding-bottom: 56%;
            }
          }
        }
        &-1 {
          flex-basis: 38%;
          flex-grow: 0;
          @media only screen and (max-width: 1024px) {
            flex-basis: 45%;
          }
          .post__wrapper {
            padding-left: 9%;
          }
        }
        &-2 {
          flex-basis: 27%;
          flex-grow: 0;
          @media only screen and (max-width: 1024px) {
            flex-basis: 40%;
          }
          .image {
            margin-right: -80px;
          }
          .post__wrapper {
            margin: -15px 0 0 auto;
            //width: 70%;
          }
          .post__poster {
            @extend .image--1x1;
          }
          .post__desc {
          }
        }
        &-3 {
          margin-top: 0px;
          @media only screen and (max-width: 1024px) {
            flex-basis: 50%;
            margin-left: 10%;
          }
          .image {
            &:before {
              padding-bottom: 47%;
            }
          }
          .post__wrapper {
            max-width: 80%;
            @include breakpoint(tab) {
              max-width: 100%;
            }
          }
        }
        &-4 {
          margin-top: -100px;
          padding-right: 6%;
          @media only screen and (max-width: 1024px) {
            margin-top: 40px;
            flex-basis: 45%;
          }
          .image {
            &:before {
              padding-bottom: 117%;
