          }
        }
        &-5 {
          position: relative;
          z-index: 1;
          .post__wrapper {
            margin-top: 75%;
            padding-right: 100px;
            @media only screen and (max-width: 1024px) {
              margin-top: 35%;
            }
          }
          .image {
            &:before {
              padding-bottom: 100%;
            }
          }
        }
        &-6,
        &-7 {
          margin-top: -218px;
          @media only screen and (max-width: 1024px) {
            flex-basis: 50%;
            margin-top: 40px;
          }
        }
        &-7 {
          flex-basis: 33%;
          margin-right: 34%;
          @media only screen and (max-width: 1024px) {
            flex-basis: 50%;
            margin-right: 0;
          }
        }
        &-8 {
          flex-basis: 31%;
          flex-grow: 0;
          margin-top: 150px;
          .post__wrapper {
            padding-left: 27%;
          }
          .image {
            @extend .image--1x1;
          }
        }
        &-9 {
          flex-basis: 62%;
          flex-grow: 0;
          padding-left: 5%;
          padding-right: 10%;
          margin-top: 15%;
          .image {
            &:before {
              padding-bottom: 95%;
            }
          }
        }
        &-10 {
          flex-basis: 48%;
          flex-grow: 0;
          margin-top: 10%;
          margin-bottom: 100px;

          .post__wrapper {
            //width: 74%;
          }
          .image {
            margin-left: -60px;
            @extend .image--1x1;
          }
        }
        &-11 {
          margin-top: 205px;
          flex-basis: 25%;
          flex-grow: 0;
          padding-right: 0;
          padding-left: 105px;
        }
        &-12 {
          margin-top: 500px;
          flex-basis: 25%;
          flex-grow: 0;
          padding-right: 0;
        }
        &-13 {
          margin-bottom: 100px;
        }
        &-14 {
        }
        &-15 {
        }
        &-16 {
          margin-top: 80px;
        }
      }
      @include breakpoint(tab) {
        flex: none;
        flex-basis: 100% !important;
        width: 100%; // 47% !important;
        display: inline-block;
        vertical-align: top;
        margin: 0 0 40px 0 !important;
        padding: 0 !important;
        // &:nth-child(odd) {
        // 	margin-right: 5% !important;
        // }
        &__poster {
          margin: 0 !important;
          &:before {
            padding-top: 0 !important;
            padding-bottom: 75% !important;
          }
        }
        &__wrapper {
          margin: 0 !important;
          padding: 0 !important;
        }
        &__title {
          font-size: scaled-rem(45);
        }
      }
    }
  }
}
</style>



