<template>
  <!-- Links to the sector (showcase) pages. Not a filter: each one is a
       page of its own. Used on Home (hero), About and Work. -->
  <nav
    v-if="sectors.length"
    :class="[
      'SectorNav',
      `SectorNav--${theme}`,
      large ? 'SectorNav--large' : '',
      aside ? 'SectorNav--aside' : '',
    ]"
    :aria-label="label || 'Sectors'"
  >
    <div v-if="label" :class="['SectorNav__label', large ? 'sectionTitle' : '']">
      {{ label }}
    </div>
    <ul class="SectorNav__list">
      <li v-for="sector in sectors" :key="sector.slug" class="SectorNav__item">
        <router-link
          :to="'/showcase/' + sector.slug"
          :class="[
            'SectorNav__pill',
            theme === 'dark' ? 'cursor-plus-white' : 'cursor-plus',
          ]"
          >{{ sector.label }}</router-link
        >
      </li>
    </ul>
  </nav>
</template>

<script>
import { plainText } from "@/utils";

export default {
  name: "SectorNav",
  props: {
    // "dark" on black/imagery (Home hero, About), "solid" black pills on
    // white (Work, Showcase)
    theme: {
      type: String,
      default: "dark",
      validator: (value) => ["dark", "solid"].indexOf(value) !== -1,
    },
    // Heading above the pills; empty for none
    label: {
      type: String,
      default: "Sectors",
    },
    // Large section heading (About) instead of the small label
    large: {
      type: Boolean,
      default: false,
    },
    // In a right-hand column (Showcase): from 1024px the block takes the
    // right 75% of it. Below that it's full width like the others.
    aside: {
      type: Boolean,
      default: false,
    },
  },
  computed: {
    // Published showcase pages from the global API, in their WordPress order.
    // Each can set a shorter "Navigation label" or be hidden (Showcase >
    // Sector navigation); otherwise the page title is used.
    sectors: function () {
      const content = this.$root.$data.content || {};
      const showcase = content.showcase || {};
      return Object.keys(showcase)
        .map((slug, index) => {
          const item = showcase[slug] || {};
          const acf = (Array.isArray(item.acf) ? item.acf[0] : item.acf) || {};
          return {
            slug: item.post_name || slug,
            label: plainText(acf.nav_label) || plainText(item.post_title),
            order: parseInt(item.menu_order, 10) || 0,
            index: index,
            hidden: !!acf.nav_hide,
          };
        })
        .filter((sector) => sector.slug && sector.label && !sector.hidden)
        .sort((a, b) => a.order - b.order || a.index - b.index);
    },
  },
};
</script>

<style scoped lang="scss">
.SectorNav {
  &__label {
    margin-bottom: 14px;

    // Small label (Home, Work, Showcase). Not on About, where .sectionTitle
    // sets the size (a scoped font-size here would outrank it) and the
    // heading lines up with "Clients" below rather than the pill text.
    &:not(.sectionTitle) {
      font-size: 16px;
      font-weight: 500;
      letter-spacing: -0.02em;
      line-height: 1.2;
      // In line with the text inside the first pill, not its edge: the
      // pill's left padding + border (15px + 1px; 11px + 1px on phab and
      // desktop)
      padding-left: 16px;

      @include breakpoint(phab) {
        padding-left: 12px;
      }

      @include breakpoint(1024px, "min-width") {
        padding-left: 12px;
      }
    }

    // Section heading size on About, with the same gap as Clients' logos
    &.sectionTitle {
      margin-bottom: 80px;

      @include breakpoint(tab) {
        margin-bottom: 40px;
      }
    }
  }

  &__list {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    margin: 0;
    padding: 0;
    list-style: none;

    @include breakpoint(phab) {
      gap: 8px;
    }

    @include breakpoint(1024px, "min-width") {
      gap: 9px;
    }
  }

  &__item {
    margin: 0;
  }

  &__pill {
    display: inline-block;
    padding: 6px 15px 7px;
    border: 1px solid;
    border-radius: 7px;
    font-size: 16px;
    font-weight: 500;
    letter-spacing: -0.02em;
    line-height: 1.2;
    text-decoration: none;
    white-space: nowrap;
    transition: color 0.3s ease, background-color 0.3s ease,
      border-color 0.3s ease;

    @include breakpoint(phab) {
      padding: 5px 11px 6px;
      font-size: 14px;
    }

    // Desktop: about 25% smaller than the base size
    @include breakpoint(1024px, "min-width") {
      padding: 4px 11px 5px;
      border-radius: 5px;
      font-size: 12px;
    }
  }

  // On black / imagery
  &--dark {
    color: #fff;

    .SectorNav__pill {
      color: #fff;
      border-color: rgba(255, 255, 255, 0.7);

      &:hover,
      &:focus-visible,
      &.router-link-active {
        color: #000;
        background-color: #fff;
        border-color: #fff;
      }
    }
  }

  // Black pills on white (Work, Showcase): the Home pills inverted, going
  // white with black text and border on hover and for the current sector
  &--solid {
    color: #000;

    .SectorNav__pill {
      color: #fff;
      background-color: #000;
      border-color: #fff;

      &:hover,
      &:focus-visible,
      &.router-link-active {
        color: #000;
        background-color: #fff;
        border-color: #000;
      }
    }
  }

  // A right-hand column: the block takes the right three-quarters of it,
  // its label and pills left-aligned and wrapping within that
  &--aside {
    @include breakpoint(1024px, "min-width") {
      width: 75%;
      margin-left: auto;
    }
  }

  &--large .SectorNav__pill {
    font-size: 18px;

    @include breakpoint(phab) {
      font-size: 14px;
    }

    @include breakpoint(1024px, "min-width") {
      font-size: 14px;
    }
  }
}
</style>



