<template>
  <div id="app" :class="'vs-section burger-open--' + this.burgerOpen">
    <div v-if="loading"></div>
    <div v-else>
      <Header></Header>
      <!-- Unknown case study / post / showcase slugs: the 404 view instead
           of a component with no data (src/seo.js also marks it noindex) -->
      <NotFound v-if="routeMissing" :key="'missing:' + $route.path"></NotFound>
      <!-- Key case studies and showcases by path so navigating between two
           of them rebuilds the component rather than reusing a stale one -->
      <router-view
        v-else
        :key="
          $route.name === 'Project' || $route.name === 'Showcase'
            ? $route.path
            : $route.name
        "
      ></router-view>
    </div>

    <svg
      ref="loader"
      class="loader"
      version="1.1"
      width="32"
      height="32"
      viewBox="0 0 32 32"
    >
      <circle ref="fillPath" class="fill-path" cx="16" cy="16" r="15" />
    </svg>
  </div>
</template>

<script>
import Header from "@/components/Header";
import NotFound from "@/components/NotFound";
import { resolveRoute } from "@/seo";
import GSAPScrollMagic from "./plugins/DrawSVGPlugin";
import sniffer from "sniffer";
//import Footer from '@/components/Footer'

export default {
  name: "App",
  components: {
    Header,
    NotFound,
    // Footer
  },
  data() {
    return {
      loading: true,
      burgerOpen: false,
    };
  },
  computed: {
    // A dynamic route (case study, post, showcase) whose slug isn't in the
    // WordPress data. Only knowable once the data has loaded, which is also
    // when the routes start rendering.
    routeMissing: function () {
      return resolveRoute(this.$route, this.$root.content).missing;
    },
  },
  created: function () {
    this.$eventBus.$on("toggleBurger", () => {
      this.burgerOpen = !this.burgerOpen;
      if (this.burgerOpen) {
        document.body.classList.add("burger-open--true");
      } else {
        document.body.classList.remove("burger-open--true");
      }
    });

    this.$nextTick(() => {
      TweenMax.set(this.$refs.fillPath, {
        drawSVG: `0%`,
      });
      TweenMax.ticker.addEventListener("tick", this.rAFExtend);
      this.loaderSize = this.$refs.loader.getBoundingClientRect();
      TweenMax.set(this.$refs.loader, {
        x: window.innerWidth / 2 - this.loaderSize.width / 2,
        y: window.innerHeight / 2 - this.loaderSize.height / 2,
      });
      document.body.classList.add("loading");
      sniffer.isDesktop && window.addEventListener("mousemove", this.mousemove);
    });

    this.$eventBus.$on("loaded", () => {
      this.animateIn();
    });
  },
  methods: {
    animateIn() {
      TweenMax.ticker.removeEventListener("tick", this.rAFExtend);
      window.removeEventListener("mousemove", this.mousemove);
      document.body.classList.remove("loading");
      document.getElementById("app").removeChild(this.$refs.loader);
      this.loading = false;
    },
    mousemove(e) {
      TweenMax.set(this.$refs.loader, {
        x: e.clientX - this.loaderSize.width / 2 + 2,
        y: e.clientY - this.loaderSize.height / 2 + 6,
      });
    },
    rAFExtend: function () {
      TweenMax.to(this.$refs.fillPath, 0.5, {
        drawSVG: `${this.$root.progress}%`,
      });
    },
  },
  updated() {
    // const appHeight = document.getElementsByClassName('Footer')[0].offsetHeight
    // document.getElementsByClassName('page')[0].style.marginBottom = appHeight + 'px'
  },
};
</script>

<style lang="scss">
.fade-enter-active,
.fade-leave-active {
  transition-duration: 0.98s;
  transition-property: opacity;
  transition-timing-function: cubic-bezier(0.23, 1, 0.32, 1);
}

.fade-enter,
.fade-leave-active {
  opacity: 0;
}

body {
  &.loading {
    cursor: none;
  }
}

.loader {
  position: absolute;

  .fill-path {
    fill: none;
    stroke: white;
    stroke-linecap: butt;
    stroke-width: 1.5px;
  }
}
</style>



