<template>
  <router-link
    v-if="url"
    :to="url"
    class="circle-link tw-flex tw-items-center tw-gap-8 tw-no-underline"
    ref="circleLink"
  >
    <div
      class="hover-wrapper tw-flex tw-items-center tw-gap-8 tw-w-full"
      :class="{ '': dark }"
      @mouseenter="startAnimation"
      @mouseleave="continueAnimation"
    >
      <div class="sectionTitle">{{ title }}</div>
      <div class="circle-container" :class="{ 'dark-mode': dark }">
        <img
          :src="
            dark
              ? require('../../assets/circle-arrow-dark.svg')
              : require('../../assets/circle-arrow.svg')
          "
          class="tw-w-[140px] tw-h-auto circle-arrow circle-arrow-1"
          alt=""
          ref="arrow1"
        />
        <img
          :src="
            dark
              ? require('../../assets/circle-arrow-dark.svg')
              : require('../../assets/circle-arrow.svg')
          "
          class="tw-w-[140px] tw-h-auto circle-arrow circle-arrow-2"
          alt=""
          ref="arrow2"
        />
      </div>
    </div>
  </router-link>
</template>

<script>
export default {
  props: {
    title: {
      type: String,
      default: "Our Work",
    },
    url: {
      type: String,
      default: null,
    },
    dark: {
      type: Boolean,
      default: false,
    },
  },
  data() {
    return {
      isAnimating: false,
    };
  },

  methods: {
    startAnimation() {
      this.animateArrows();
    },
    continueAnimation() {
      this.animateArrows();
    },
    animateArrows() {
      if (this.isAnimating) return;

      this.isAnimating = true;

      const arrow1 = this.$refs.arrow1;
      const arrow2 = this.$refs.arrow2;

      if (!arrow1 || !arrow2) {
        console.warn("Arrow refs not found");
        this.isAnimating = false;
        return;
      }

      // Move both arrows right
      arrow1.classList.add("move-right");
      arrow2.classList.add("stay-center");

      // Reset after animation completes
      setTimeout(() => {
        // Disable transitions temporarily
        arrow1.classList.add("no-transition");
        arrow2.classList.add("no-transition");

        // Remove move classes
        arrow1.classList.remove("move-right");
        arrow2.classList.remove("stay-center");

        // Force reflow
        arrow1.offsetHeight;
        arrow2.offsetHeight;

        // Re-enable transitions
        arrow1.classList.remove("no-transition");
        arrow2.classList.remove("no-transition");

        this.isAnimating = false;
        console.log("Animation reset complete");
      }, 1000); // Match CSS transition duration
    },
  },
};
</script>

<style lang="scss">
.circle-container {
  border: 1px solid white;
  border-radius: 100%;
  width: 140px;
  height: 140px;
  position: relative;
  overflow: hidden;

  @include breakpoint(lap) {
    width: 80px;
    height: 80px;
  }
  @include breakpoint(phab) {
    width: 50px;
    height: 50px;
  }

  &.dark-mode {
    border-color: #000000;
  }
}

.circle-arrow {
  position: absolute;
  top: 0;
  left: 0;
  width: 140px;
  height: 140px;
  transition: transform 1s cubic-bezier(0.86, 0, 0.07, 1);

  @include breakpoint(lap) {
    width: 80px;
    height: 80px;
  }
  @include breakpoint(phab) {
    top: -2px;
    width: 50px !important;
    height: 50px !important;
  }
}

.sectionTitle {
  @include breakpoint(phab) {
    font-size: 17px;
  }
}

// Initial positions
.circle-arrow-1 {
  transform: translateX(0); // center (visible)
}
.circle-arrow-2 {
  transform: translateX(-100%); // left (hidden)
}

// Animation classes
.move-right {
  transform: translateX(100%) !important;
}
.stay-center {
  transform: translateX(0) !important;
}

.no-transition {
  transition: none !important;
}
.hover-wrapper {
  background: none !important;
}
</style>



