<template>
  <transition appear v-on:appear="enter" v-on:leave="leave" v-bind:css="false">
    <div class="Privacy flyout">
      <div class="flyout-transform js-transform">
        <div class="flyout-transform js-transform theme--white">
          <div class="Section-bounding js-bounding">
            <div class="page__container">
              <div class="page__inner u-relative js-copy">
                <div class="flyout__close">
                  <a
                    href="/"
                    @click="routerBack"
                    aria-label="Back"
                    class="close js-stagger"
                    ><img src="../assets/arrow-left.svg" alt=""
                  /></a>
                </div>

                <div class="flyout__hero">
                  <!-- The page's H1, styled as before via .h4 -->
                  <h1 class="h4 js-stagger">Privacy policy</h1>
                </div>

                <div class="flyout__copy">
                  <div class="js-stagger" v-html="page.post_content"></div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  </transition>
</template>

<script>
import size from "size";
import Scroll from "@/components/scroll";
import Titleline from "@/components/modules/Titleline";
import { isModifiedClick } from "@/utils";
//import Footer from '@/components/Footer'

export default {
  name: "Privacy",
  extends: Scroll,
  components: {
    Titleline,
    //		Footer
  },
  data() {
    return {
      page: [],
    };
  },
  created: function () {
    this.flyout = true;
    this.page = this.$root.$data.content.pages.privacypolicy;
    console.log(this.page);
  },
  mounted() {
    //console.log('Privacy:mounted')
    this.$eventBus.$emit("updateScroll");
    this.$eventBus.$emit("changeTheme", "light");
    this.$eventBus.$emit("cursor:color", "black");
    this.init();
    this.animateIn();
  },
  beforeDestroy: function () {
    //console.log('Privacy:beforeDestroy')
    this.destroy();
  },
  destroyed: function () {
    this.$eventBus.$emit("changeTheme", "dark");
  },
  methods: {
    getUIExtend: function () {
      this.transform = this.$el.querySelectorAll(".js-transform");
      this.stagger = this.$el.querySelectorAll(".js-stagger");
    },
    onFocus() {
      this.$refs.form.classList.add("active");
    },
    onBlur: function (event) {
      this.$refs.form.classList.remove("active");
    },
    routerBack: function (event) {
      // Let cmd/ctrl/shift-click open the real href in a new tab or window
      if (isModifiedClick(event)) return;
      event.preventDefault();
      window.routeStorage.moreInfo = true;
      this.$router.go(-1);
    },
    enter: function (el, done) {
      //console.log('Privacy:enter', el)
      TweenMax.set(this.$el, {
        position: "fixed",
        top: 0,
        left: 0,
        width: "100%",
        zIndex: 5,
      });
      done();
    },
    animateIn: function () {
      const tl = new TimelineMax({ paused: true });
      tl.set(this.$el, { position: "relative" });
      tl.staggerFromTo(
        this.transform,
        1,
        {
          cycle: {
            x: [-size.width, size.width],
          },
        },
        {
          x: 0,
          ease: Quint.easeInOut,
        },
        0,
        0
      );
      tl.staggerFromTo(
        this.stagger,
        0.65,
        {
          x: 20,
          autoAlpha: 0,
        },
        {
          x: 0,
          autoAlpha: 1,
          ease: Quint.easeOut,
        },
        0.1,
        0.35
      );
      tl.add(() => this.$eventBus.$emit("ready"), 1);
      tl.restart();
    },
    leave: function (el, done) {
      //console.log('Privacy:leave', el)
      const tl = new TimelineMax({ paused: true, onComplete: done });
      tl.set(this.$el, {
        position: "fixed",
        top: 0,
        left: 0,
        right: 0,
        width: "100%",
      });
      tl.staggerTo(
        this.transform,
        1,
        {
          cycle: {
            x: [size.width, -size.width],
          },
          ease: Quint.easeInOut,
        },
        0,
        0
      );
      tl.staggerTo(
        this.stagger,
        0.4,
        {
          autoAlpha: 0,
          ease: Linear.easeNone,
        },
        0,
        0
      );
      tl.restart();
    },
    rAFExtend: function () {},
    resize: function () {},
  },
};
</script>

<!-- Add "scoped" attribute to limit CSS to this component only -->
<style scoped lang="scss">
.Privacy {
  .Section-bounding {
    background: white;
  }

  .flyout__hero {
    margin-bottom: scaled-rem(70);

    @include breakpoint(tab) {
      margin-bottom: 50px;
    }
  }

  .legal {
    @include breakpoint(tab) {
      max-width: 90%;
    }
    margin-top: 40px;
    font-size: 13px;
  }
}
</style>



