<template>
  <transition appear v-on:appear="enter" v-on:leave="leave" v-bind:css="false">
    <div class="Home">
      <div class="page__hero__copy js-slides tw-pointer-events-none">
        <div class="page__container tw-relative tw-h-full">
          <div class="tw-relative tw-h-full">
            <h1
              ref="copy1"
              class="copy__title copy__title--strapline"
            >
              <span>{{ content.strapline }} </span>
            </h1>
            <h2
              ref="copy2"
              class="copy__title copy__title--heading lg:tw-text-[28px] tw-text-[17px]"
            >
              {{ content.heading }}
            </h2>
            <div ref="copy3" class="copy__title copy__title--sectors">
              <SectorNav theme="dark" label="Sectors" />
            </div>
          </div>
        </div>
      </div>

      <div class="Home-transform js-transform theme--black">
        <div class="Home-transform js-transform">
          <div class="Section-bounding js-bounding">
            <div class="">
              <div class="workWrapper">
                <div class="tw-flex tw-justify-end tw-pr-[20px] lg:tw-mt-24">
                  <CircleArrow title="Our Work" url="/work" />
                </div>
                <div class="page__container">
                  <div class="sectionTitle tw-mt-28 tw-mb-12 lg:tw-mb-0">
                    Work highlights
                  </div>
                </div>

                <div class="Home__work u-vacuum u-relative tw-pb-24" ref="work">
                  <div class="u-vacuum--restore">
                    <div
                      :key="item.ID"
                      v-for="item in items"
                      class="item-ratio"
                    >
                      <router-link
                        :to="{ path: '/work/' + item.post_name }"
                        event=""
                        v-on:click.native="openProject"
                        :data-post="item.post_name"
                        :data-src="
                          backgroundImage(
                            item.acf[0].feature_image.url,
                            item.acf[0].feature_image_portrait.url
                          )
                        "
                        class="image js-image js-el"
                      >
                        <div
                          :class="[
                            'image-src',
                            item.acf[0].feature_video ? 'image-src--video' : '',
                            'u-cover',
                            'u-overflow-h',
                            'js-src',
                          ]"
                          :data-focus-x="item.acf[0].focus_point_x"
                          :data-focus-y="item.acf[0].focus_point_y"
                        >
                          <video
                            v-if="item.acf[0].feature_video"
                            autoplay
                            disableRemotePlayback
                            loop
                            muted
                            playsinline
                          >
                            <source
                              :src="item.acf[0].feature_video"
                              type="video/mp4"
                            />
                          </video>
                        </div>
                        <div class="page__container">
                          <div class="meta cursor-plus">
                            <p class="js-stagger">
                              {{ item.acf[0].client }} –
                              {{ item.acf[0].caption }}
                            </p>
                            <h2
                              class="meta__title js-stagger"
                              v-html="
                                item.acf[0].homepage_title_override
                                  ? item.acf[0].homepage_title_override
                                  : item.post_title
                              "
                            ></h2>
                          </div>
                        </div>
                      </router-link>
                    </div>
                  </div>
                </div>

                <div
                  class="tw-flex tw-justify-end tw-pr-[20px] lg:tw-mt-24 tw-pb-32"
                >
                  <CircleArrow title="About us" url="/about" />
                </div>
                <LatestNews :posts="posts" />
              </div>
            </div>
          </div>
          <Footer></Footer>
        </div>
      </div>

      <div class="bubble__wrapper">
        <video
          width="1800"
          height="1200"
          disableRemotePlayback
          autoplay
          loop
          muted
          playsinline
          class="bubble js-video"
          ref="bubble-video"
        >
          <source src="../assets/flower.mp4" type="video/mp4" />
        </video>
      </div>
    </div>
  </transition>
</template>

<script>
import size from "size";
import sniffer from "sniffer";
import Projects from "@/components/modules/Projects";
import Footer from "@/components/Footer";
import Titleline from "@/components/modules/Titleline";
import CircleArrow from "@/components/modules/CircleArrow";
import LatestNews from "@/components/modules/LatestNews";
import SectorNav from "@/components/modules/SectorNav";

export default {
  name: "Home",
  extends: Projects,
  components: {
    Titleline,
    Footer,
    CircleArrow,
    LatestNews,
    SectorNav,
  },
  data() {
    return {
      introComplete: false,
    };
  },
  created: function () {
    this.$eventBus.$emit("changeTheme", "dark");
    const work = this.$root.$data.content.work;
    this.content = this.$root.$data.content.pages.home.acf[0];
    const projects = this.content.projects || [];

    // Order items to match the homepage's Projects field order
    this.items = projects.map((item) => work[item.post_name]).filter(Boolean);

    this.posts = this.$root.$data.content.posts;
    this.tl = null;
    this.textHeight = 0;
  },
  mounted() {
    //console.log('Home:mounted')
    this.$eventBus.$on("toggleBurger", this.onToggleBurger);
    this.$eventBus.$on("resize", this.workResize);
    this.init();
    this.$eventBus.$emit("setHeaderScrollThreshold", 1500); // Set custom scroll threshold for header visibility
    this.addController();

    if (sniffer.isDevice) {
      this.$refs.cover.style.height = `${window.innerHeight}px`;
    }
  },
  beforeDestroy() {
    //console.log('Home:beforeDestroy')
    this.$eventBus.$off("toggleBurger", this.onToggleBurger);
  },
  onReady: function () {},
  methods: {
    workResize: function () {
      const els = this.$el.querySelectorAll(".js-image");
      els.forEach((dom) => {
        const el = dom.querySelector(".js-src");
        const bounds = el.getBoundingClientRect();
        const meta = dom.querySelector(".meta");
        if (!sniffer.isDevice) {
          TweenMax.set(meta, {
            x:
              dom.offsetLeft <= bounds.width * 0.25
                ? bounds.width - 60
                : -meta.offsetWidth + 60,
          });
        }
      });
    },
    getUIExtend: function () {
      this.transform = this.$el.querySelectorAll(".js-transform");
      this.video = this.$el.querySelector(".js-video");
      this.logo = document.querySelector(".Header__logo");
      this.burger = document.querySelector(".burger__trigger");
      this.lines = this.$el.querySelectorAll(".js-line");
      this.workContainer = this.$el.querySelector(".workWrapper");
      this.animateComplete = false;
      this.heroCopy = this.$el.querySelector(".page__hero__copy");
      this.textHeight = this.heroCopy.offsetHeight;
      // True while scrolling started before the intro finished (see rAFExtend)
      this.scrollFade = false;
    },
    onToggleBurger: function (v) {
      if (!v && window.location.hash) {
        window.scroll({
          top: size.height * 1.2,
          behavior: "smooth",
        });
      }
    },
    addController: function () {
      console.log("Home:addController");
      const { copy1, copy2, copy3 } = this.$refs;
      const tl = (this.tl = new TimelineMax());

      tl.set(copy1, { y: -10 });
      tl.set(copy2, { y: -10 });
      tl.set(copy3, { y: -10 });

      tl.set(this.video, { opacity: 0 });

      //timeline
      // The copy starts fading in while the video is still fading up (it
      // used to wait for the video, starting at 1.25s)
      tl.to(this.video, 1, { opacity: 1 }, 0);
      tl.to(copy1, 1, { autoAlpha: 1, y: 0 }, 0.3);
      tl.to(copy2, 1, { autoAlpha: 1, y: 0 }, 0.55);
      tl.to(copy3, 1, { autoAlpha: 1, y: 0 }, 0.75); // sector links
      tl.call(
        () => {
          this.introComplete = true;
          console.log("Home:introComplete");
          tl.pause();
        },
        null,
        null,
        "+=0.25"
      ); // Pause after copy2 finishes; scroll drives the timeline from here
      // Where the intro ends, so the scroll mapping in rAFExtend follows
      // whatever the intro's length is
      this.introEnd = tl.duration();

      // Let the page scroll straight away rather than holding it until the
      // intro above has finished (~3s). "ready" is what unlocks scrolling.
      this.$nextTick(() => this.$eventBus.$emit("ready"));

      // The sector links leave with the heading above them
      tl.addLabel("out");
      tl.to(copy2, 5, { autoAlpha: 0, y: 10 }, "out");
      tl.to(copy3, 5, { autoAlpha: 0, y: 10 }, "out");
      tl.to(copy1, 5, { autoAlpha: 0, y: 10 }, "-=4");
      tl.to(copy1, 5, { alpha: 0, y: 0 });
    },
    enter: function (el, done) {
      if (window.routeStorage.route === "project") {
        const transform = this.$el.querySelectorAll(".js-transform");
        const tl = new TimelineMax({ paused: true, onComplete: done });
        tl.set(this.$el, {
          position: "fixed",
          top: 0,
          left: 0,
          width: "100%",
          zIndex: 10,
        });
        tl.staggerFromTo(
          transform,
          1,
          {
            cycle: {
              x: [-size.width, size.width],
            },
          },
          {
            x: 0,
          },
          0
        );
        tl.set(this.$el, { position: "relative", zIndex: 1 });
        tl.restart();
      } else {
        done();
      }
    },
    leave: function (el, done) {
      done();
    },
    animateIn: function () {
      const tl = new TimelineMax({ paused: true });
      const delay = this.$root.firstLoad ? 300 : 0;

      tl.add(() => (this.animateComplete = true));
      tl.add(() => this.$eventBus.$emit("cursor:color", "white"), 0);

      const that = this;
      setTimeout(function () {
        tl.restart();
        that.$root.firstLoad = false;
      }, delay);
    },
    rAFExtend: function () {
      const current = this.data.current;

      if (
        !window.App.menu &&
        this.mouse.y + current <= this.data.max - size.height
      ) {
        this.$eventBus.$emit("cursor:color", "white");
      } else {
        this.$eventBus.$emit("cursor:color", "black");
      }

      // The hero copy is position: fixed, and the timeline below only follows
      // the scroll once the intro has finished. If scrolling starts during
      // the intro, fade the copy's wrapper with the scroll instead (the intro
      // keeps playing inside it), so it's gone before the work grid reaches
      // it. Hand back to the timeline only at the top, where both are fully
      // visible, so there's no jump.
      const scrolled = this.data.current > 1;
      if (!this.introComplete && scrolled) {
        this.scrollFade = true;
      } else if (this.scrollFade && this.introComplete && !scrolled) {
        this.scrollFade = false;
      }
      if (this.scrollFade) {
        // Gone by ~0.65x the hero's height, matching the pace of the
        // timeline's own scroll fade-out
        const opacity = Math.max(
          0,
          1 - this.data.current / (this.textHeight * 0.65)
        );
        this.heroCopy.style.opacity = opacity;
        // Once invisible, its sector links mustn't stay clickable over the
        // work grid
        this.heroCopy.style.visibility = opacity <= 0.02 ? "hidden" : "";
      } else if (this.heroCopy.style.opacity !== "") {
        this.heroCopy.style.opacity = "";
        this.heroCopy.style.visibility = "";
      }

      if (this.introComplete && !this.scrollFade) {
        // Scroll position -> the fade-out part of the timeline, which runs
        // from the end of the intro (this.introEnd) to the end
        const textProgress = this.data.current / (this.textHeight * 1.5);
        const clamped = Math.min(Math.max(textProgress, 0), 1);
        if (this.tl) {
          this.tl.time(
            this.introEnd + clamped * (this.tl.duration() - this.introEnd)
          );
        }
      }

      const videoProgress = this.data.current / (this.textHeight * 1.5);

      const alpha = videoProgress < 0.3 ? 1 : 1 - (videoProgress - 0.3) / 0.3;
      // During the intro the timeline is fading the video in; only take over
      // once it's done, or earlier if scrolling has started to fade it out
      if (this.introComplete || alpha < 1) {
        this.video.style.opacity = alpha;
      }
    },
  },
};
</script>

<!-- Add "scoped" attribute to limit CSS to this component only -->
<style scoped lang="scss">
.Home {
  z-index: 8;

  .Home__posts {
    &__title {
      font-size: scaled-rem(75);
    }
  }

  .bubble__wrapper {
    position: fixed;
    z-index: 9;
    left: 0px;
    top: 0px;
    height: 100vh;
    width: 100%;
    pointer-events: none;

    video {
      object-fit: cover;
      width: 100%;
      height: 100%;
    }

    @include breakpoint(tab) {
      height: 100vh;
      top: 0;

      video {
        object-fit: cover;
      }
    }
  }

  .page__hero {
    @include breakpoint(tab) {
      padding-right: 30px;
    }

    &__copy {
      position: fixed;
      //padding-top: 60vh;
      left: 0;
      height: 100vh;
      width: 100vw;
      z-index: 20;

      .copy__title {
        position: absolute;
        left: 0;
        opacity: 0;
        z-index: 2;
      }

      // The strapline sits in the middle of the screen at any size (margin
      // centring, not a transform: GSAP animates its y). The heading and
      // sector links are anchored to the bottom.
      .copy__title--strapline {
        top: 0;
        bottom: 0;
        height: -webkit-fit-content;
        height: -moz-fit-content;
        height: fit-content;
        margin: auto 0;
        font-size: 44px;

        // From lg: 77px, growing with the screen's width and height (height
        // too, so a wide but short screen doesn't push it into the heading),
        // up to 128px. The measure is in em so it keeps its two-line shape.
        @include breakpoint(1024px, "min-width") {
          font-size: 77px;
          font-size: unquote("clamp(77px, min(5.35vw, 11vh), 128px)");
          max-width: 9.5em;
        }

        // Short desktop windows: let it shrink a little to keep clear of
        // the heading below
        @media (min-width: 1024px) and (max-height: 700px) {
          font-size: unquote("clamp(56px, 11vh, 77px)");
        }
      }
      .copy__title--heading {
        bottom: 175px;

        @include breakpoint(1023px, "max-width") {
          bottom: 200px;
        }
      }
      .copy__title--sectors {
        bottom: 70px;
        right: 0;
        // The hero copy ignores the pointer; its links mustn't
        pointer-events: auto;

        @include breakpoint(1023px, "max-width") {
          bottom: 40px;
        }
      }
    }
  }

  .page__hero__copy__line {
    will-change: transform;
  }

  .page__hero__copy__line {
    @include breakpoint("1510px", "min-width") {
      display: block;
    }
  }

  .workWrapper {
    padding-top: 1650px;
    @include breakpoint(tab) {
      padding-top: 1200px;
    }
  }
  .work &__work {
    padding-bottom: 65px;
    padding-top: 80px;

    .u-vacuum--restore {
      @include breakpoint(tab) {
        padding-top: 150px;
      }
    }
  }
}
</style>



