<template>
  <transition appear v-on:appear="enter" v-on:leave="leave" v-bind:css="false">
    <div class="Home theme--white">
      <div class="Home-transform js-transform">
        <div class="Home-transform js-transform">
          <div class="Section-bounding js-bounding">
            <div
              class="tw-bg-white md:tw-pt-12 lg:tw-pt-[160px] tw-pb-20 lg:tw-pb-44 tw-text-loafblack"
            >
              <div class="page__container">
                <div class="Home__work u-vacuum" ref="work">
                  <div class="u-vacuum--restore" v-if="page">
                    <!-- Title + intro on the left half, sector links on the
                         right (under the intro on mobile) -->
                    <div class="showcase__intro">
                      <div class="showcase__main">
                        <div class="tw-max-w-[90%] md:tw-max-w-[660px]">
                          <h1 class="h1 showcase__subtitle tw-font-medium">
                            {{ page.acf.subtitle }}
                          </h1>
                          <div
                            class="h5 showcase__copy tw-mt-8 lg:tw-mt-[3rem]"
                            v-html="page.acf.introduction"
                          ></div>
                        </div>
                      </div>

                      <div
                        :class="[
                          'showcase__aside',
                          hasHighlight ? '' : 'showcase__aside--navOnly',
                        ]"
                      >
                        <!-- The sector pages; this one is marked current.
                             Desktop only: on mobile they're under the grid -->
                        <SectorNav
                          class="showcase__sectors showcase__sectors--side"
                          theme="solid"
                          label="Sectors"
                          aside
                        />
                        <div class="showcase__back">
                          <router-link to="/work" class="hover hover--link showcase__backLink"
                            >Back to work</router-link
                          >
                        </div>

                        <div
                          v-if="hasHighlight"
                          class="showcase__highlightBlock"
                        >
                          <div
                            class="h6 showcase__highlight"
                            v-html="page.acf.highlight.text"
                          ></div>
                          <img
                            v-if="page.acf.highlight.image"
                            :src="page.acf.highlight.image"
                            :alt="
                              plainText(page.acf.highlight.text) ||
                              plainText(page.acf.subtitle) ||
                              plainText(page.title && page.title.rendered)
                            "
                            class="tw-w-full tw-mt-10 lg:tw-mt-14"
                          />
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
              <div class="tw-mx-auto tw-max-w-[1800px] tw-mt-6 md:tw-mt-16 xl:tw-mt-[7em]">
                <div>
                  <div>
                    <div
                      class="tw-grid tw-grid-cols-1 md:tw-grid-cols-2 lg:tw-grid-cols-3 tw-gap-y-10 md:tw-gap-y-12"
                    >
                      <a
                        :key="item.ID"
                        v-for="item in items"
                        :ref="'work' + item.ID"
                        :href="'/work/' + item.post_name"
                        :data-post="item.post_name"
                        class="work__item tw-block tw-w-full tw-no-underline"
                        @click="handleWorkClick($event, item.post_name)"
                      >
                        <div
                          :class="[
                            'tw-aspect-square lg:tw-aspect-[13/9] tw-w-full tw-object-cover cursor-plus-white',
                            item.acf.feature_video ? 'image-src--video' : '',
                          ]"
                          :data-focus-x="item.acf.focus_point_x"
                          :data-focus-y="item.acf.focus_point_y"
                        >
                          <video
                            v-if="item.acf.feature_video"
                            autoplay
                            disableRemotePlayback
                            loop
                            muted
                            class="tw-w-full tw-h-full tw-object-cover"
                            playsinline
                          >
                            <source
                              :src="item.acf.feature_video"
                              type="video/mp4"
                            />
                          </video>
                          <img
                            v-else-if="item.acf.work_page_image_override"
                            :src="item.acf.work_page_image_override.sizes.large"
                            :alt="imageAlt(item.acf.work_page_image_override, workLabel(item))"
                            class="tw-w-full tw-h-full tw-object-cover"
                          />
                          <img
                            v-else-if="item.acf.feature_image"
                            :src="item.acf.feature_image.sizes.large"
                            :alt="imageAlt(item.acf.feature_image, workLabel(item))"
                            class="tw-w-full tw-h-full tw-object-cover"
                          />
                        </div>
                        <div class="meta">
                          <div class="meta__title">
                            <div
                              class="meta__title__item meta__title1 tw-font-medium tw-inline-block tw-mb-2"
                              v-html="
                                (item.acf.homepage_title_override
                                  ? item.acf.homepage_title_override
                                  : item.post_title
                                ).replace(/<br\s*\/?>/gi, '')
                              "
                            ></div>
                            <br />
                            <div
                              class="h2 meta__title__item meta__title2 js-stagger tw-inline-block"
                            >
                              {{ item.acf.client }} –
                              {{ item.acf.caption }}
                            </div>
                          </div>
                        </div>
                      </a>
                    </div>
                  </div>
                </div>
              </div>
              <!-- Mobile only: the sector pages after the work grid -->
              <div v-if="page" class="page__container showcase__bottom">
                <SectorNav
                  class="showcase__sectors"
                  theme="solid"
                  label="Sectors"
                />
                <div class="showcase__back">
                  <router-link to="/work" class="hover hover--link showcase__backLink"
                    >Back to work</router-link
                  >
                </div>
              </div>
            </div>
          </div>
          <Footer></Footer>
        </div>
      </div>
    </div>
  </transition>
</template>

<script>
import axios from "axios";
import Footer from "@/components/Footer";
import Scroll from "@/components/scroll";
import SectorNav from "@/components/modules/SectorNav";
import { isModifiedClick, imageAlt, workLabel, plainText } from "@/utils";

export default {
  name: "Showcase",
  extends: Scroll,
  components: {
    SectorNav,
    Footer,
  },
  data() {
    return {
      page: null,
      items: [],
    };
  },
  computed: {
    // The optional highlight text/image in the right-hand cell
    hasHighlight: function () {
      const highlight = this.page && this.page.acf && this.page.acf.highlight;
      return !!(highlight && (highlight.text || highlight.image));
    },
  },
  created() {
    this.$eventBus.$emit("updateScroll");
    this.$eventBus.$emit("changeTheme", "light");
    this.getShowcase();
  },
  mounted() {
    this.init();
    this.restoreScrollPosition();
  },
  beforeDestroy: function () {
    this.destroy();
  },
  destroyed: function () {
    //  console.log("Showcase:destroyed");
  },
  methods: {
    imageAlt,
    workLabel,
    plainText,
    getUIExtend: function () {},
    enter: function (el, done) {
      //  console.log("Showcase:enter", el);
      done();
    },
    getShowcase: function () {
      const slug = this.$route.params.id;
      // Shared with ShowcaseNav on the case study pages
      const cache = this.$root.$data.showcase_cache;
      if (cache && cache[slug]) {
        this.render(cache[slug]);
        return;
      }
      const url = `${this.$root.$data.dataDomain}/wp-json/wp/v2/showcase?slug=${slug}`;
      axios
        .get(url)
        .then((response) => {
          const page = response.data[0];
          if (!page) {
            this.$eventBus.$emit("ready");
            return;
          }
          if (cache) this.$set(cache, slug, page);
          this.render(page);
        })
        .catch((error) => {
          console.log(error);
        });
    },
    render: function (page) {
      this.page = page;
      this.items = page.acf.work || [];
      // Title and meta are set by src/seo.js (from the global data)
      this.$nextTick(() => {
        this.getImages();
        this.preloadImages();
        this.animateIn();
        this.$eventBus.$emit("ready");
      });
    },
    // Same entrance as the Work page: the intro (title, copy, sector links)
    // fades in, then the grid staggers in from halfway through it, and the
    // mobile sector links under the grid last
    animateIn: function () {
      const atTop = this.$route.query.scrollY ? false : true;
      const tl = (this.tl = new TimelineMax());
      const intro = this.$el.querySelector(".showcase__intro");
      const workItems = Array.from(this.$el.querySelectorAll(".work__item"));
      const bottom = this.$el.querySelector(".showcase__bottom");
      const grid = bottom ? workItems.concat(bottom) : workItems;
      TweenMax.set(intro, {
        opacity: 0,
      });
      TweenMax.set(grid, {
        opacity: 0,
      });
      tl.to(intro, 1, {
        opacity: 1,
      });
      tl.staggerFromTo(
        grid,
        1,
        { opacity: 0 },
        { opacity: 1 },
        0.05,
        atTop ? "-=0.5" : "-1"
      );
    },
    leave: function (el, done) {
      done();
    },
    resize: function () {},
    handleWorkClick(event, postName) {
      // Let cmd/ctrl/shift-click open the real href in a new tab or window
      if (isModifiedClick(event)) return;
      event.preventDefault();

      // Capture the current scroll position from the custom scroll system
      const scrollY = this.data ? this.data.current : window.scrollY;
      const roundedScrollY = Math.round(scrollY);

      // Navigate with the scroll position, plus the showcase we came from so
      // the case study can offer navigation across the rest of the collection
      this.$router.push({
        path: `/work/${postName}`,
        query: {
          scrollY: roundedScrollY.toString(),
          showcase: this.$route.params.id,
        },
      });
    },
    restoreScrollPosition() {
      const scrollY = this.$route.query.scrollY;
      if (scrollY) {
        const targetScroll = parseInt(scrollY, 10);
        // Set both target and current for instant scroll
        this.$nextTick(() => {
          if (this.data) {
            this.data.target = targetScroll;
            this.data.current = targetScroll;
            // Also set the actual window scroll position
            window.scrollTo(0, targetScroll);
          }
        });
      }
    },
  },
};
</script>

<!-- Add "scoped" attribute to limit CSS to this component only -->
<style scoped lang="scss">
$showcaseGrey: #716f6f;

.Home {
  &__work {
    @media (max-width: 1024px) {
      padding-top: 120px;
    }
    @media (min-width: 1025px) {
      padding-top: 120px;
    }
  }

  .showcase {
    // One column on mobile; two equal halves from Tailwind's lg (1024px)
    &__intro {
      display: grid;
      grid-template-columns: minmax(0, 1fr);
      row-gap: 48px;

      @include breakpoint(1024px, "min-width") {
        grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
      }
    }

    &__main {
      @include breakpoint(1024px, "min-width") {
        padding-right: 48px;
      }
    }

    &__highlightBlock {
      margin-top: 48px;

      @include breakpoint(1023px, "max-width") {
        margin-top: 0;
      }
    }

    // Beside the intro on desktop, after the work grid on mobile
    &__sectors--side {
      @include breakpoint(1023px, "max-width") {
        display: none;
      }
    }

    &__bottom {
      margin-top: 56px;

      @include breakpoint(1024px, "min-width") {
        display: none;
      }
    }

    // Under the sector links, in line with the left of the pills (the same
    // right-hand block on desktop), a little larger than the pills' text
    &__back {
      margin-top: 48px;

      @include breakpoint(1024px, "min-width") {
        width: 75%;
        margin-left: auto;
      }
    }

    &__backLink {
      color: #000;
      font-size: 19px;
      font-weight: 500;
      letter-spacing: -0.02em;
      line-height: 1.2;

      @include breakpoint(phab) {
        font-size: 16px;
      }
    }

    // With no highlight the right-hand cell holds only the (desktop) sector
    // links, so on mobile drop it rather than leave an empty grid row
    &__aside--navOnly {
      @include breakpoint(1023px, "max-width") {
        display: none;
      }
    }

    &__subtitle {
      line-height: 0.95;
    }

    // Colour is inherited by the v-html paragraphs
    &__copy {
      color: #1e1f21; // loafblack
      font-weight: 500;
      line-height: 1.25;
      // em, so the measure tracks the fluid type scale (~60 characters)
      max-width: 30em;
    }

    &__highlight {
      color: $showcaseGrey;
    }
  }

  .work {
    &__item {
      .meta__title__item {
        letter-spacing: -0.03em;
      }
      .meta__title div:after {
        background-color: black;
        bottom: -5px;
        //transform: scaleX(1);
      }
      .meta__title1,
      .meta__title2 {
        font-size: 23px;

        @include breakpoint(1440px, "max-width") {
          font-size: 20px;
        }
        @include breakpoint(phab) {
          font-size: 18px;
        }
      }

      img,
      video {
        transition: filter 0.5s ease;
        will-change: filter;
        background-color: #000;
      }
      &:hover {
        img,
        video {
          filter: brightness(0.7);
        }

        .meta__title div:after {
          transform: scaleX(1);
          transform-origin: left center;
        }
      }

      .meta {
        padding: 25px 15px 25px 20px;
        line-height: 1;

        @include breakpoint(1440px, "max-width") {
          padding: 20px 10px 20px 15px;
        }

        @include breakpoint(phab) {
          padding: 20px 15px;
        }
      }
    }
  }
}
</style>


<!-- Not scoped: these target the markup ACF returns inside v-html -->
<style lang="scss">
.showcase__copy p:last-child,
.showcase__highlight p:last-child {
  margin-bottom: 0;
}

.showcase__highlight a {
  color: #1e1f21; // loafblack
  font-weight: 500;

  // The underline (and its hover retract) comes from `p a { @extend .hover--link }`
  // in _ui.scss, which draws it as an absolutely positioned :after. That :after
  // resolves width:100% to 0 when the inline box fragments across two lines, so
  // keep the link on a single line -- same fix as .meta__title in main.scss.
  display: inline-block;
}
</style>



