<template>
	<transition appear
		v-on:appear="enter"
   	 	v-on:leave="leave"
    	v-bind:css="false"
	>
	<div class="Signup flyout">
		<div class="flyout-transform js-transform">
			<div class="flyout-transform js-transform theme--white">
				<div class="Section-bounding js-bounding">
					<div class="page__container">
						<div class="page__inner u-relative js-copy">
							<div class="flyout__close">
								<a href="/" @click="routerBack" aria-label="Back" class="close js-stagger"><img src="../assets/arrow-left.svg" alt=""></a>
							</div>


							<div class="flyout__hero">
								<!-- The page's H1, styled as before via .h4 -->
								<h1 class="h4 js-stagger">Sign up to our newsletter</h1>
							</div>

							<div class="flyout__copy">
								<div class="js-stagger h6">
									<p v-if="!error">Sign up to receive the latest thoughts, work, opinions and activity from the Loaf Studio.</p>
									<p v-else>There seems to be an error. Please ensure your email address has been entered correctly.</p>
									<form v-if="!subscribed" ref="form" action="" class="signup" @submit.prevent="register">
										<div class="u-flex">
											<input ref="email" v-model="form.email" name="email" class="input" type="text" @focus="onFocus" >
											<img @click="register" class="u-block arrow" src="../assets/arrow-right.svg" alt="Sign up">
										</div>
									</form>
									<div v-else>
										<p>Thanks for signing up</p>
									</div>

									<div class="legal">
										<p>Your email address is stored securely and will never be shared with any third parties. If you’d like to unsubscribe at any point, you can do so by clicking the unsubscribe link on any newsletter we send you. For further details, please read our <router-link to="/privacy-policy" class="hover hover--link">Privacy Policy.</router-link></p>
									</div>
								</div>
							</div>

						</div>

					</div>
				</div>

			</div>
		</div>
	</div>
	</transition>
</template>

<script>
	import size from 'size'
	import Scroll from '@/components/scroll'
	import Titleline from '@/components/modules/Titleline'
	import axios from 'axios'
	import { isModifiedClick } from '@/utils'
	//import Footer from '@/components/Footer'

	export default {
		name: 'Signup',
		extends: Scroll,
		components: {
			Titleline,
	//		Footer
		},
		data() {
			return {
				page: [],
				subscribed: false,
				error: false,
				form: {
					email: ''
				}
			}
		},
		created: function(){
			this.flyout = true
		},
		mounted() {
			//console.log('Signup:mounted')
			this.$eventBus.$emit('updateScroll')
			this.$eventBus.$emit('changeTheme', 'light')
			this.$eventBus.$emit('cursor:color', 'black')
			this.init()
			this.animateIn()
		},
		beforeDestroy: function() {
			//console.log('Signup:beforeDestroy')
			this.destroy()
		},
		destroyed: function(){
			this.$eventBus.$emit('changeTheme', 'dark')
		},
		methods: {
			getUIExtend: function() {
				this.transform = this.$el.querySelectorAll('.js-transform')
				this.stagger = this.$el.querySelectorAll('.js-stagger')
			},
			register: function() {
				const email = this.$refs.email.value
				axios.get(this.$root.dataDomain + '/cm/cm.php?email=' + email).then((response) =>
        {
		          console.log(response);
              if(!response || !response.data || response.data !== 'success') { this.error = true; return; }

              console.log('subscribed!');
		          this.subscribed = true
		          this.error = false

		        }).catch((error) => {
		          console.log(error)
		          this.error = true
		        })
			},
			onFocus() {
		  		this.$refs.form.classList.add('active')
		  	},
		  	onBlur: function(event) {
		  		this.$refs.form.classList.remove('active')
		  	},
		  routerBack: function(event) {
		  	// Let cmd/ctrl/shift-click open the real href in a new tab or window
		  	if (isModifiedClick(event)) return
		  	event.preventDefault()
		  	window.routeStorage.moreInfo = true
		  	this.$router.go(-1)
		  },
		  enter: function (el, done) {
		  	//console.log('Signup:enter', el)
		  	TweenMax.set(this.$el, { position: 'fixed', top: 0, left: 0, width: '100%', zIndex: 5 })
		  	done()
		  },
			animateIn: function() {
				const tl = new TimelineMax({ paused: true })
				tl.set(this.$el, { position: 'relative' })
				tl.staggerFromTo(this.transform, 1, {
					cycle: {
						x: [-size.width, size.width]
					}
				}, {
					x: 0,
					ease: Quint.easeInOut
				}, 0, 0)
				tl.staggerFromTo(this.stagger, .65, {
					x: 20,
					autoAlpha: 0
				}, {
					x: 0,
					autoAlpha: 1,
					ease: Quint.easeOut
				}, .1, .35)
				tl.add(() => this.$eventBus.$emit('ready'), 1)
				tl.restart()
			},
		  leave: function (el, done) {
		  	//console.log('Signup:leave', el)
		  	const tl = new TimelineMax({ paused: true, onComplete: done })
		  	tl.set(this.$el, { position: 'fixed', top: 0, left: 0, right: 0, width: '100%' })
		  	tl.staggerTo(this.transform, 1, {
					cycle: {
						x: [size.width, -size.width]
					},
					ease: Quint.easeInOut
				}, 0, 0)
				tl.staggerTo(this.stagger, .4, {
					autoAlpha: 0,
					ease: Linear.easeNone
				}, 0, 0)
				tl.restart()
		  },
			rAFExtend: function() {},
			resize: function() {}
		}
	}
</script>

<!-- Add "scoped" attribute to limit CSS to this component only -->
<style scoped lang="scss">
	.Signup {

		&.flyout {
    	height: 100vh;
		}

		.Section-bounding {
			background: white;
		}

		.page__inner {
			max-width: 500px !important;
		}

		.flyout__hero {
			margin-bottom: scaled-rem(70);

			@include breakpoint(tab) {
				margin-bottom: 50px;
			}
		}

		.legal {
			@include breakpoint(tab) {
				max-width: 90%;
			}
			margin-top: 40px;
			font-size: 13px;
		}
	}
</style>



